    ( -z "$output_size_name" ||
      "$output_size_name" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ) ]] || return 1
  benchmark_pressure_trusted_regular_path "$input" || return $?

  coproc BENCHMARK_PRESSURE_SNAPSHOT_BROKER {
