      "$BENCHMARK_PRESSURE_PYTHON_EXECUTABLE" -I /dev/fd/3 \
      "$input" "$maximum_bytes" "$EUID" \
      "$BENCHMARK_PRESSURE_PYTHON_EXECUTABLE" \
      "$BENCHMARK_PRESSURE_TIMEOUT_EXECUTABLE" \
