class InvalidJSON(Exception):
    pass


class BoundedStream:
    def __init__(self, source, maximum):
        self.source = source
        self.maximum = maximum
        self.buffer = b""
        self.offset = 0
        self.total = 0

    def _fill(self):
        if self.offset < len(self.buffer):
            return True
        chunk = self.source.read(65536)
        if not chunk:
            self.buffer = b""
            self.offset = 0
            return False
        self.total += len(chunk)
        if self.total > self.maximum:
            raise InvalidJSON()
        self.buffer = chunk
        self.offset = 0
        return True

    def peek(self):
        if not self._fill():
            return None
        return self.buffer[self.offset]

    def take(self):
        value = self.peek()
        if value is None:
            raise InvalidJSON()
        self.offset += 1
        return value


class UniqueObjectKeyParser:
    whitespace = frozenset((0x20, 0x09, 0x0A, 0x0D))

    def __init__(self, stream, maximum_depth, maximum_members):
        self.stream = stream
        self.maximum_depth = maximum_depth
        self.maximum_members = maximum_members
        self.members = 0

    def parse(self):
        self._space()
        self._value(0)
        self._space()
        if self.stream.peek() is not None:
            raise InvalidJSON()

    def _space(self):
        while self.stream.peek() in self.whitespace:
            self.stream.take()

    def _value(self, depth):
        token = self.stream.peek()
        if token == 0x7B:
            self._object(depth + 1)
        elif token == 0x5B:
            self._array(depth + 1)
        elif token == 0x22:
            self._string(False)
        elif token == 0x74:
            self._literal(b"true")
        elif token == 0x66:
            self._literal(b"false")
        elif token == 0x6E:
            self._literal(b"null")
        elif token == 0x2D or (token is not None and 0x30 <= token <= 0x39):
            self._number()
        else:
            raise InvalidJSON()

    def _object(self, depth):
        if depth > self.maximum_depth:
            raise InvalidJSON()
        self.stream.take()
        self._space()
        keys = set()
        if self.stream.peek() == 0x7D:
            self.stream.take()
            return
        while True:
            if self.stream.peek() != 0x22:
                raise InvalidJSON()
            key = self._string(True)
            self.members += 1
            if self.members > self.maximum_members or key in keys:
                raise InvalidJSON()
            keys.add(key)
            self._space()
            if self.stream.take() != 0x3A:
                raise InvalidJSON()
            self._space()
            self._value(depth)
            self._space()
            separator = self.stream.take()
            if separator == 0x7D:
                return
            if separator != 0x2C:
                raise InvalidJSON()
            self._space()

    def _array(self, depth):
        if depth > self.maximum_depth:
            raise InvalidJSON()
        self.stream.take()
        self._space()
        if self.stream.peek() == 0x5D:
            self.stream.take()
            return
        while True:
            self._value(depth)
            self._space()
            separator = self.stream.take()
            if separator == 0x5D:
                return
            if separator != 0x2C:
                raise InvalidJSON()
            self._space()

    def _string(self, retain):
        raw = bytearray((self.stream.take(),))
        while True:
            value = self.stream.take()
            raw.append(value)
            if value == 0x22:
                break
            if value < 0x20:
                raise InvalidJSON()
            if value == 0x5C:
                escaped = self.stream.take()
                raw.append(escaped)
                if escaped == 0x75:
                    for _ in range(4):
                        digit = self.stream.take()
                        raw.append(digit)
                        if not (0x30 <= digit <= 0x39 or
                                0x41 <= digit <= 0x46 or
                                0x61 <= digit <= 0x66):
                            raise InvalidJSON()
                elif escaped not in b'"\\/bfnrt':
                    raise InvalidJSON()
        try:
            decoded = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise InvalidJSON() from None
        if not isinstance(decoded, str):
            raise InvalidJSON()
        return decoded if retain else None

    def _literal(self, expected):
        for byte in expected:
            if self.stream.take() != byte:
                raise InvalidJSON()

    def _digits(self):
        count = 0
        while True:
            value = self.stream.peek()
            if value is None or not 0x30 <= value <= 0x39:
                return count
            self.stream.take()
            count += 1

    def _number(self):
        if self.stream.peek() == 0x2D:
            self.stream.take()
        first = self.stream.peek()
        if first == 0x30:
            self.stream.take()
            following = self.stream.peek()
            if following is not None and 0x30 <= following <= 0x39:
                raise InvalidJSON()
        elif first is not None and 0x31 <= first <= 0x39:
            self._digits()
        else:
            raise InvalidJSON()
        if self.stream.peek() == 0x2E:
            self.stream.take()
            if self._digits() == 0:
                raise InvalidJSON()
        if self.stream.peek() in (0x65, 0x45):
            self.stream.take()
            if self.stream.peek() in (0x2B, 0x2D):
                self.stream.take()
            if self._digits() == 0:
                raise InvalidJSON()


def main():
    path = sys.argv[1]
    maximum = int(sys.argv[2])
    maximum_depth = int(sys.argv[3])
    expected_size = int(sys.argv[4])
    if maximum < 1 or maximum_depth < 1 or expected_size < 1:
        raise InvalidJSON()
    with open(path, "rb", buffering=0) as source:
        before = os.fstat(source.fileno())
        if before.st_size != expected_size or before.st_size > maximum:
            raise InvalidJSON()
        stream = BoundedStream(source, maximum)
        UniqueObjectKeyParser(stream, maximum_depth, maximum).parse()
        after = os.fstat(source.fileno())
        if (after.st_dev != before.st_dev or after.st_ino != before.st_ino or
                after.st_size != before.st_size or stream.total != expected_size):
            raise InvalidJSON()


try:
    main()
except (InvalidJSON, OSError, ValueError, RecursionError):
    sys.exit(1)
