}

benchmark_pressure_cycle_directory_roster_matches() {
  local -r manifest="$1"
  local -r expected_file_count="$2"
  local manifest_dir="${3:-${manifest%/*}}"
  local manifest_basename="${4:-${manifest##*/}}"
  local directory_entries=""
  local directory_name=""
  local directory_type=""
  local directory_extra=""
  local directory_rows=0
  local manifest_rows=0

  [[ "$expected_file_count" =~ ^[1-9][0-9]*$ &&
    ( "$manifest_basename" == private-manifest.json ||
      "$manifest_basename" =~ ^\.private-manifest\.[A-Za-z0-9]+$ ) ]] || return 1
  benchmark_pressure_bounded_directory_roster \
    "$manifest_dir" directory_entries || return $?
  ((${#directory_entries} <= 4096)) || return 1
  while IFS=: read -r directory_name directory_type directory_extra; do
    ((directory_rows += 1))
    [[ -z "$directory_extra" && "$directory_type" == f ]] || return 1
    if [[ "$directory_name" == "$manifest_basename" ]]; then
      ((manifest_rows += 1))
    else
      jq -e --arg name "$directory_name" \
        'any(.files[]; .name == $name)' "$manifest" >/dev/null || return $?
    fi
  done <<<"$directory_entries"
  ((directory_rows == expected_file_count + 1 && manifest_rows == 1))
}

validate_benchmark_pressure_private_manifest() (
  local -r manifest_input="$1"
  local -r expected_cycle="$2"
  local -r supplied_private_root="${3:-}"
  local -r supplied_manifest_dir="${4:-}"
  local manifest_lexical_input="${BENCHMARK_PRESSURE_PUBLICATION_SOURCE_LEXICAL_PATH:-$manifest_input}"
  local manifest=""
  local manifest_leaf="${manifest_lexical_input##*/}"
  local manifest_path=""
  local manifest_fd=""
  local manifest_snapshot_fd=""
  local manifest_original=""
  local manifest_snapshot_source_identity=""
  local manifest_input_identity=""
  local manifest_snapshot_sha256=""
  local manifest_snapshot_size=""
  local manifest_identity=""
  local lexical_manifest_identity=""
  local observed_manifest_identity=""
  local manifest_sha256=""
  local observed_manifest_sha256=""
  local manifest_dir=""
  local manifest_dir_lexical="${manifest_lexical_input%/*}"
  local expected_cycle_name=""
  local role=""
  local name=""
  local expected_sha256=""
  local expected_size=""
  local extra=""
  local path=""
  local identity=""
  local observed_sha256=""
  local limits=""
  local maximum_bytes=""
  local maximum_lines=""
  local roster=""
  local expected_rows=0
  local observed_rows=0
  local map_id=""
  local map_entries=""
  local resolved=""
  local phase_sha256=""
  local expected_phase_sha256=""
  local stack_sha256=""
  local manifest_stack_sha256=""
  local load_started_sha256=""
  local ready_sha256=""
  local release_published_sha256=""
  local release_sha256=""
  local prepare_value=""
  local fill_value=""
  local verify_value=""
  local cleanup_value=""
  local manifest_value=""
  local recovery_one_sha256=""
  local recovery_two_sha256=""
  local private_root=""
  local private_root_lexical=""
  local private_root_fd=""
  local manifest_dir_fd=""
  local private_root_identity=""
  local manifest_dir_identity=""
  local observed_private_root_identity=""
  local observed_manifest_dir_identity=""
  local lexical_private_root_identity=""
  local lexical_manifest_dir_identity=""
  local leaf_fd=""
  local snapshot_fd=""
  local pinned_path=""
  local original_pinned_path=""
  local pinned_identity=""
  local pinned_sha256=""
  local snapshot_source_identity=""
  local snapshot_sha256=""
  local snapshot_size=""
  local pinned_key=""
  local campaign_key=""
  local campaign_snapshot=false
  local -a BENCHMARK_PRESSURE_PINNED_EVIDENCE_FDS=()
  local -a BENCHMARK_PRESSURE_SNAPSHOT_EVIDENCE_FDS=()
  local -A BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS=()
  local -A BENCHMARK_PRESSURE_ORIGINAL_EVIDENCE_PATHS=()
  local -A BENCHMARK_PRESSURE_PINNED_EVIDENCE_NAMES=()
  local -A BENCHMARK_PRESSURE_PINNED_EVIDENCE_IDENTITIES=()
  local -A BENCHMARK_PRESSURE_PINNED_EVIDENCE_SHA256S=()

  if [[ -n "$supplied_manifest_dir" ]]; then
    [[ "$manifest_input" =~ ^/proc/self/fd/[1-9][0-9]*$ ]] || return 1
    manifest_leaf=private-manifest.json
    manifest_dir_lexical="$supplied_manifest_dir"
    manifest_lexical_input="$supplied_manifest_dir/$manifest_leaf"
  fi
  [[ "$expected_cycle" =~ ^([1-9]|10)$ &&
    ( "$manifest_leaf" == private-manifest.json ||
      "$manifest_leaf" =~ ^\.private-manifest\.[A-Za-z0-9]+$ ) &&
    -f "$manifest_input" && ! -L "$manifest_lexical_input" ]] || return 1
  bounded_evidence_file "$manifest_input" "$BENCHMARK_PRESSURE_MANIFEST_MAX_BYTES" 1 ||
    return $?
  manifest_input_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
    "$manifest_input")" || return $?
  [[ "$manifest_input_identity" =~ \
    ^[0-9]+:[1-9][0-9]*:$EUID:600:(0|1):[1-9][0-9]*$ ]] || return 1
  printf -v expected_cycle_name 'cycle-%02d' "$expected_cycle"
  if [[ -n "$supplied_private_root" ]]; then
    private_root_lexical="$supplied_private_root"
  else
    [[ "${manifest_dir_lexical##*/}" == "$expected_cycle_name" ]] || return 1
    private_root_lexical="${manifest_dir_lexical%/*}"
  fi
  [[ -d "$private_root_lexical" && ! -L "$private_root_lexical" ]] || return 1
  exec {private_root_fd}<"$private_root_lexical" || return $?
  private_root="/proc/self/fd/$private_root_fd/."
  private_root_identity="$(stat -Lc '%d:%i:%u:%a' -- "$private_root")" ||
    return $?
  lexical_private_root_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$private_root_lexical")" || return $?
  [[ "$lexical_private_root_identity" == "$private_root_identity" &&
    "$private_root_lexical" -ef "$private_root" &&
    -d "$private_root/$expected_cycle_name" &&
    ! -L "$private_root/$expected_cycle_name" ]] || return 1
  exec {manifest_dir_fd}<"$private_root/$expected_cycle_name" || return $?
  manifest_dir="/proc/self/fd/$manifest_dir_fd/."
  manifest_path="$manifest_dir/$manifest_leaf"
  manifest_dir_identity="$(stat -Lc '%d:%i:%u:%a' -- "$manifest_dir")" ||
    return $?
  lexical_manifest_dir_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$manifest_dir_lexical")" || return $?
  [[ "$private_root_identity" =~ ^[0-9]+:[1-9][0-9]*:$EUID:700$ &&
    "$manifest_dir_identity" =~ ^[0-9]+:[1-9][0-9]*:$EUID:700$ &&
    "$lexical_manifest_dir_identity" == "$manifest_dir_identity" &&
    "$manifest_dir_lexical" -ef "$manifest_dir" &&
    "$manifest_lexical_input" -ef "$manifest_path" &&
    -f "$manifest_path" && ! -L "$manifest_path" ]] || return 1
  campaign_key="$expected_cycle"
  if declare -p BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_PATHS \
      BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_PATHS \
      BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_IDENTITIES \
      BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_SHA256S >/dev/null 2>&1 &&
    [[ -n "${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_PATHS[$campaign_key]:-}" &&
      "$manifest_input" == \
        "${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_PATHS[$campaign_key]}" ]]; then
    campaign_snapshot=true
    manifest_original="${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_PATHS[$campaign_key]}"
  else
    exec {manifest_fd}<"$manifest_path" || return $?
    manifest_original="/proc/self/fd/$manifest_fd"
  fi
  manifest_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- "$manifest_original")" ||
    return $?
  lexical_manifest_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- \
    "$manifest_path")" || return $?
  [[ "$manifest_identity" =~ ^[0-9]+:[1-9][0-9]*:$EUID:600:1$ &&
    "$lexical_manifest_identity" == "$manifest_identity" &&
    "$manifest_path" -ef "$manifest_original" ]] || return 1
  manifest_sha256="$(sha256sum -- "$manifest_original")" || return $?
  manifest_sha256="${manifest_sha256%% *}"
  if [[ "$campaign_snapshot" == true ]]; then
    manifest="$manifest_input"
    manifest_snapshot_source_identity="$manifest_input_identity"
    manifest_snapshot_sha256="${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_SHA256S[$campaign_key]}"
    manifest_snapshot_size="$(stat -Lc '%s' -- "$manifest")" || return $?
    [[ "$manifest_original" == \
        "${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_PATHS[$campaign_key]}" &&
      "$manifest_identity:$(stat -Lc '%s' -- "$manifest_original")" == \
        "${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_IDENTITIES[$campaign_key]}" ]] ||
      return 1
  else
    benchmark_pressure_hold_file_snapshot \
      "$manifest_input" "$BENCHMARK_PRESSURE_MANIFEST_MAX_BYTES" \
      manifest_snapshot_fd manifest_snapshot_source_identity \
      manifest_snapshot_sha256 manifest_snapshot_size || return $?
    manifest="/proc/self/fd/$manifest_snapshot_fd"
  fi
  [[ "$manifest_snapshot_source_identity" == "$manifest_input_identity" &&
    "$manifest_snapshot_sha256" == "$manifest_sha256" &&
    "$manifest_snapshot_size" == "$(stat -Lc '%s' -- "$manifest_original")" ]] ||
    return 1
  benchmark_pressure_json_has_unique_object_keys \
    "$manifest" "$BENCHMARK_PRESSURE_MANIFEST_MAX_BYTES" || return $?
  jq -e \
    --argjson cycle "$expected_cycle" \
    --argjson cycle_count "$BENCHMARK_PRESSURE_CYCLE_COUNT" \
    --argjson load_seconds "$BENCHMARK_PRESSURE_LOAD_SECONDS" \
    --argjson idle_seconds "$BENCHMARK_PRESSURE_IDLE_SECONDS" \
    --argjson capacity "$PRESSURE_EXPECTED_MAP_CAPACITY" \
    --argjson maximum_successful_requests "$BENCHMARK_PRESSURE_MAX_SUCCESSFUL_REQUESTS" \
    --argjson trace_max_spans "$BENCHMARK_PRESSURE_TRACE_MAX_SPANS" \
    --argjson trace_max_retained_bytes "$BENCHMARK_PRESSURE_TRACE_MAX_RETAINED_BYTES" \
    --argjson trace_spans_per_request "$BENCHMARK_PRESSURE_TRACE_SPANS_PER_REQUEST" \
    --arg histogram_encoding "$BENCHMARK_PRESSURE_HISTOGRAM_ENCODING" \
    --arg marker_encoding "$BENCHMARK_PRESSURE_MARKER_ENCODING" '
      def integer: type == "number" and floor == .;
      def digest: type == "string" and test("^[0-9a-f]{64}$");
      def expected_names:
        {admission:"admission-receipt.json",
         barrier:"barrier-receipt.json",benchmark:"benchmark-result.json",
         benchmark_stderr:"benchmark.stderr.log",
         benchmark_client_commit:"benchmark-client-commit.json",
         prepare:"map-prepare.json",
         fill:"map-fill.json",verify:"map-verify.json",cleanup:"map-cleanup.json",
         bridge_reconciliation:"bridge-reconciliation.json",
         cleanup_recovery:"map-recovered.prom",idle_before:"idle-before.prom",
         idle_after:"idle-after.prom",
         java_after:"java-diagnostics-after.txt",
         java_after_stderr:"java-diagnostics-after.stderr",
         java_before:"java-diagnostics-before.txt",
         java_before_stderr:"java-diagnostics-before.stderr",
         java_delta:"java-diagnostics.delta",
         metrics_after:"obi-metrics-after.prom",
         metrics_before:"obi-metrics-before.prom",
         metrics_delta:"obi-metrics.delta",
         resources_baseline:"resources-baseline.json",
         resources_postload:"resources-postload.json",
         resources_postidle:"resources-postidle.json",
         stack_identity:"stack-identity.json",map_baseline:"map-baseline.prom",
         phase_boundaries:"phase-boundaries.json",
         trace_projection:"trace-projection.json",
         trace_reset:"trace-reset.json",trace_snapshot:"trace-snapshot.json",
         recovery_1:"recovery-01.prom",
         recovery_2:"recovery-02.prom"};
      . as $document |
      keys == ["acceptance_eligible","attribution","cycle","files","identity",
        "load","map","marker","phases","recovery","requested","schema",
        "status","timing"] and
      .schema == "obi-benchmark-pressure-private-manifest-v2" and
      .status == "passed" and .acceptance_eligible == false and .cycle == $cycle and
      .requested == {cycle_count:$cycle_count,load_seconds:$load_seconds,
        idle_seconds:$idle_seconds} and
      (.timing | keys) == ["idle_elapsed_centiseconds",
        "load_elapsed_centiseconds"] and
      (.timing.load_elapsed_centiseconds | integer and
        . >= ($load_seconds * 100) and
        . < (($load_seconds + 1) * 100)) and
      (.timing.idle_elapsed_centiseconds | integer and
        . >= ($idle_seconds * 100) and
        . < (($idle_seconds + 1) * 100)) and
      (.identity | keys) == ["process_map_id","process_namespace",
        "process_pid","stack_identity_sha256"] and
      (.identity.stack_identity_sha256 | digest) and
      (.identity.process_map_id | test("^[1-9][0-9]*$")) and
      (.identity.process_pid | test("^[1-9][0-9]*$")) and
      (.identity.process_namespace | test("^[1-9][0-9]*$")) and
      (.load | keys) == ["failed_requests","histogram_encoding",
        "requested_duration_nanos","successful_requests","traffic_elapsed_nanos"] and
      .load.histogram_encoding == $histogram_encoding and
      .load.requested_duration_nanos == ($load_seconds * 1000000000) and
      (.load.successful_requests | integer and . > 0 and
        . <= $maximum_successful_requests) and
      .load.failed_requests == 0 and
      (.load.traffic_elapsed_nanos | integer and
        . >= ($load_seconds * 1000000000) and
        . < (($load_seconds + 1) * 1000000000)) and
      (.marker | keys) == ["admitted_requests","encoding",
        "first_request_ordinal","last_request_ordinal","prefix"] and
      (.marker.prefix | test("^pressure-[0-9a-f]{32}-cycle-(0[1-9]|10)$")) and
      .marker.encoding == $marker_encoding and
      .marker.admitted_requests == .load.successful_requests and
      .marker.first_request_ordinal == 1 and
      .marker.last_request_ordinal == .load.successful_requests and
      (.attribution | keys) == ["admission_receipt_sha256","ambiguous",
        "exact_hit_count","explicit_root_count","overload","received_batches",
        "received_spans","retained_bytes","retained_span_count",
        "unexpected_evictions"] and
      (.attribution.admission_receipt_sha256 | digest) and
      .attribution.ambiguous == 0 and .attribution.unexpected_evictions == 0 and
      (.attribution.overload | integer and . >= 1) and
      (.attribution.received_batches | integer and . >= 1) and
      (.attribution.received_spans | integer and . >= 1 and
        . <= $trace_max_spans) and
      .attribution.received_batches <= .attribution.received_spans and
      .attribution.received_spans == .attribution.retained_span_count and
      .attribution.received_spans ==
        (.load.successful_requests * $trace_spans_per_request) and
      (.attribution.retained_bytes | integer and . >= 1 and
        . <= $trace_max_retained_bytes) and
      (.attribution.exact_hit_count | integer and . >= 0) and
      (.attribution.explicit_root_count | integer and . >= 1) and
      (.attribution.exact_hit_count + .attribution.explicit_root_count) ==
        .load.successful_requests and
      (.map | keys) == ["baseline_entries","capacity_rejected_entries",
        "cleanup_entries","content_sha256","filled_entries","map_id",
        "max_entries","postload_content_sha256"] and
      .map.baseline_entries == 0 and .map.max_entries == $capacity and
      .map.filled_entries == $capacity and .map.capacity_rejected_entries == 1 and
      .map.cleanup_entries == 0 and (.map.map_id | test("^[1-9][0-9]*$")) and
      (.map.content_sha256 | digest) and
      .map.postload_content_sha256 == .map.content_sha256 and
      (.phases | type == "array" and length == 13) and
      (.phases | map(.name)) == ["baseline_resources_captured",
        "prepare_started","capacity_ready","load_started","load_finished",
        "release_published","content_verified","postload_resources_captured",
        "attribution_reconciled","cleanup_absent","idle_started","idle_finished",
        "postidle_resources_captured"] and
      all(.phases[];
        keys == ["evidence_sha256","monotonic_centiseconds","name"] and
        (.evidence_sha256 | digest) and
        (.monotonic_centiseconds | integer and . >= 0)) and
      all(range(1;13);
        $document.phases[. - 1].monotonic_centiseconds <=
          $document.phases[.].monotonic_centiseconds) and
      (.phases[4].monotonic_centiseconds -
        .phases[3].monotonic_centiseconds) ==
          .timing.load_elapsed_centiseconds and
      .load.traffic_elapsed_nanos <
        ((.timing.load_elapsed_centiseconds + 1) * 10000000) and
      (.phases[11].monotonic_centiseconds -
        .phases[10].monotonic_centiseconds) == .timing.idle_elapsed_centiseconds and
      (.files | type == "array" and
        length == (if $cycle == 10 then 32 else 30 end)) and
      ([.files[].role] | length == (unique | length)) and
      ([.files[].name] | length == (unique | length)) and
      all(.files[];
        keys == ["name","role","sha256","size_bytes"] and
        (.role | type == "string") and .name == expected_names[.role] and
        (.name | test("^[a-z0-9][a-z0-9.-]*$")) and
        (.sha256 | digest) and
        (.size_bytes | integer and . >= 0 and . <= 100663296)) and
      ([.files[].role] | sort) ==
        ((["admission","barrier","benchmark","benchmark_stderr",
          "benchmark_client_commit",
          "bridge_reconciliation","cleanup","cleanup_recovery","fill",
          "idle_after","idle_before","java_after","java_after_stderr",
          "java_before","java_before_stderr","java_delta","metrics_after",
          "metrics_before","metrics_delta","prepare","map_baseline",
          "phase_boundaries","resources_baseline",
          "resources_postidle","resources_postload","stack_identity","verify"] +
          ["trace_projection","trace_reset","trace_snapshot"] +
          (if $cycle == 10 then ["recovery_1","recovery_2"] else [] end)) | sort) and
      (.recovery | keys) == ["captured_monotonic_centiseconds","consecutive",
        "map_entries","required_samples","sample_sha256s"] and
      if $cycle == 10 then
        .recovery.required_samples == 2 and .recovery.consecutive == true and
        .recovery.map_entries == [0,0] and
        (.recovery.sample_sha256s | length == 2 and all(.[]; digest)) and
        (.recovery.captured_monotonic_centiseconds | length == 2 and
          all(.[]; integer and . >= 0)) and
        .recovery.captured_monotonic_centiseconds[0] <=
          .recovery.captured_monotonic_centiseconds[1] and
        .recovery.captured_monotonic_centiseconds[0] >=
          $document.phases[11].monotonic_centiseconds and
        .recovery.captured_monotonic_centiseconds[1] <=
          $document.phases[12].monotonic_centiseconds
      else
        .recovery == {captured_monotonic_centiseconds:[],consecutive:false,
          map_entries:[],required_samples:0,sample_sha256s:[]}
      end
  ' "$manifest" >/dev/null || return $?
  expected_rows="$(jq -er '.files | length' "$manifest")" || return $?
  [[ "$expected_rows" =~ ^[1-9][0-9]*$ ]] || return 1
  benchmark_pressure_cycle_directory_roster_matches \
    "$manifest" "$expected_rows" "$manifest_dir" "$manifest_leaf" || return $?
  roster="$(mktemp -p /tmp obi-pressure-manifest-roster.XXXXXX)" || return $?
  trap 'rm -f -- "$roster"' EXIT
  chmod 0600 -- "$roster" || return $?
  jq -er '.files[] | [.role,.name,.sha256,.size_bytes] | @tsv' \
    "$manifest" >"$roster" || return $?
  bounded_evidence_file "$roster" 65536 32 || return $?
  while IFS=$'\t' read -r role name expected_sha256 expected_size extra; do
    ((observed_rows += 1))
    [[ -z "$extra" && "$role" =~ ^[a-z0-9_]+$ &&
      "$name" =~ ^[a-z0-9][a-z0-9.-]*$ &&
      "$expected_sha256" =~ ^[0-9a-f]{64}$ &&
      "$expected_size" =~ ^(0|[1-9][0-9]*)$ ]] || return 1
    path="$manifest_dir/$name"
    campaign_key="$expected_cycle:$role"
    if [[ "$campaign_snapshot" == true ]]; then
      declare -p BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS \
        BENCHMARK_PRESSURE_CAMPAIGN_LEAF_ORIGINAL_PATHS \
        BENCHMARK_PRESSURE_CAMPAIGN_LEAF_NAMES \
        BENCHMARK_PRESSURE_CAMPAIGN_LEAF_IDENTITIES \
        BENCHMARK_PRESSURE_CAMPAIGN_LEAF_SHA256S >/dev/null 2>&1 || return 1
      pinned_path="${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS[$campaign_key]:-}"
      original_pinned_path="${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_ORIGINAL_PATHS[$campaign_key]:-}"
      pinned_identity="${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_IDENTITIES[$campaign_key]:-}"
      observed_sha256="${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_SHA256S[$campaign_key]:-}"
      [[ -n "$pinned_path" && -n "$original_pinned_path" &&
        "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_NAMES[$campaign_key]:-}" == "$name" &&
        "$path" -ef "$original_pinned_path" &&
        "$pinned_identity" =~ \
          ^[0-9]+:[1-9][0-9]*:$EUID:600:1:$expected_size$ &&
        "$observed_sha256" == "$expected_sha256" ]] || return 1
    else
      [[ -f "$path" && ! -L "$path" ]] || return 1
      unset leaf_fd
      exec {leaf_fd}<"$path" || return $?
      original_pinned_path="/proc/self/fd/$leaf_fd"
      pinned_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
        "$original_pinned_path")" ||
        return $?
      [[ "$path" -ef "$original_pinned_path" &&
        "$pinned_identity" =~ \
          ^[0-9]+:[1-9][0-9]*:$EUID:600:1:$expected_size$ ]] || return 1
    fi
    limits="$(benchmark_pressure_role_limits "$role")" || return $?
    IFS=' ' read -r maximum_bytes maximum_lines extra <<<"$limits" || return $?
    [[ -z "$extra" && "$maximum_bytes" =~ ^[1-9][0-9]*$ &&
      "$maximum_lines" =~ ^[1-9][0-9]*$ ]] || return 1
    if [[ "$campaign_snapshot" == true ]]; then
      bounded_evidence_file \
        "$pinned_path" "$maximum_bytes" "$maximum_lines" || return $?
      snapshot_source_identity="$pinned_identity"
      snapshot_sha256="$(sha256sum -- "$pinned_path")" || return $?
      snapshot_sha256="${snapshot_sha256%% *}"
      snapshot_size="$(stat -Lc '%s' -- "$pinned_path")" || return $?
    else
      bounded_evidence_file \
        "$original_pinned_path" "$maximum_bytes" "$maximum_lines" ||
        return $?
      observed_sha256="$(sha256sum -- "$original_pinned_path")" || return $?
      observed_sha256="${observed_sha256%% *}"
      [[ "$observed_sha256" == "$expected_sha256" ]] || return 1
      unset snapshot_fd
      benchmark_pressure_hold_file_snapshot \
        "$original_pinned_path" "$maximum_bytes" snapshot_fd \
        snapshot_source_identity snapshot_sha256 snapshot_size || return $?
      pinned_path="/proc/self/fd/$snapshot_fd"
      BENCHMARK_PRESSURE_PINNED_EVIDENCE_FDS+=("$leaf_fd")
      BENCHMARK_PRESSURE_SNAPSHOT_EVIDENCE_FDS+=("$snapshot_fd")
    fi
    [[ "${snapshot_source_identity%:*}" == "${pinned_identity%:*}" &&
      "$snapshot_size" == "$expected_size" &&
      "$snapshot_sha256" == "$expected_sha256" ]] || return 1
    BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS["$role"]="$pinned_path"
    BENCHMARK_PRESSURE_ORIGINAL_EVIDENCE_PATHS["$role"]="$original_pinned_path"
    BENCHMARK_PRESSURE_PINNED_EVIDENCE_NAMES["$role"]="$name"
    BENCHMARK_PRESSURE_PINNED_EVIDENCE_IDENTITIES["$role"]="$pinned_identity"
    BENCHMARK_PRESSURE_PINNED_EVIDENCE_SHA256S["$role"]="$observed_sha256"
  done <"$roster"
  ((observed_rows == expected_rows)) || return 1
  benchmark_pressure_validate_client_commit_images success_pair \
    "$expected_cycle" "$manifest_dir_identity" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[benchmark_client_commit]}" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[benchmark]}" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[benchmark_stderr]}" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_IDENTITIES[benchmark]}" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_IDENTITIES[benchmark_stderr]}" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_IDENTITIES[benchmark_client_commit]}" ||
    return $?
  local BENCHMARK_PRESSURE_CLIENT_BUNDLE_VALIDATED=true

  validate_benchmark_pressure_result \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[benchmark]}" \
    "$(jq -er '.marker.prefix' "$manifest")" || return $?
  validate_benchmark_pressure_barrier_receipt \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[barrier]}" "$expected_cycle" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[fill]}" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[verify]}" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[benchmark]}" || return $?
  validate_benchmark_pressure_admission_receipt \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[admission]}" \
    "$expected_cycle" "$manifest_dir" ||
    return $?
  pressure_result_has_contract \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[prepare]}" prepare || return $?
  pressure_result_has_contract \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[cleanup]}" cleanup || return $?
  for role in map_id max_entries process_map_id process_pid process_namespace \
    token_base; do
    prepare_value="$(pressure_result_uint \
      "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[prepare]}" "$role")" || return $?
    fill_value="$(pressure_result_uint \
      "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[fill]}" "$role")" || return $?
    verify_value="$(pressure_result_uint \
      "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[verify]}" "$role")" || return $?
    [[ "$prepare_value" == "$fill_value" &&
      "$fill_value" == "$verify_value" ]] || return 1
    case "$role" in
      map_id|max_entries|process_pid|process_namespace|token_base)
        cleanup_value="$(pressure_result_uint \
          "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[cleanup]}" "$role")" ||
          return $?
        [[ "$cleanup_value" == "$fill_value" ]] || return 1
        ;;
    esac
  done
  for role in process_map_id process_pid process_namespace; do
    manifest_value="$(jq -er --arg role "$role" '.identity[$role]' \
      "$manifest")" || return $?
    fill_value="$(pressure_result_uint \
      "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[fill]}" "$role")" || return $?
    [[ "$manifest_value" == "$fill_value" ]] || return 1
  done
  validate_benchmark_pressure_stack_identity_file \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[stack_identity]}" || return $?
  for role in resources_baseline resources_postload resources_postidle; do
    validate_benchmark_pressure_resources \
      "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[$role]}" \
      "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[stack_identity]}" || return $?
  done
  validate_benchmark_pressure_phase_boundaries \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[phase_boundaries]}" \
    "$expected_cycle" \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[benchmark]}" || return $?
  jq -e --slurpfile boundaries \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[phase_boundaries]}" '
    ($boundaries | length) == 1 and
    .phases == $boundaries[0].phases and
    .timing.load_elapsed_centiseconds ==
      $boundaries[0].load_elapsed_centiseconds and
    .timing.idle_elapsed_centiseconds ==
      $boundaries[0].idle_elapsed_centiseconds
  ' "$manifest" >/dev/null || return $?
  jq -e \
    --slurpfile baseline "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[resources_baseline]}" \
    --slurpfile postload "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[resources_postload]}" \
    --slurpfile postidle "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[resources_postidle]}" '
      ($baseline | length) == 1 and ($postload | length) == 1 and
      ($postidle | length) == 1 and
      ($baseline[0].stack == $postload[0].stack and
        $postload[0].stack == $postidle[0].stack) and
      (.phases[] | select(.name == "baseline_resources_captured") |
        .monotonic_centiseconds) ==
          $baseline[0].captured_monotonic_centiseconds and
      (.phases[] | select(.name == "postload_resources_captured") |
        .monotonic_centiseconds) ==
          $postload[0].captured_monotonic_centiseconds and
      (.phases[] | select(.name == "postidle_resources_captured") |
        .monotonic_centiseconds) ==
          $postidle[0].captured_monotonic_centiseconds and
      $baseline[0].captured_monotonic_centiseconds <=
        $postload[0].captured_monotonic_centiseconds and
      $postload[0].captured_monotonic_centiseconds <=
        $postidle[0].captured_monotonic_centiseconds
  ' "$manifest" >/dev/null || return $?
  jq -e \
    --slurpfile result "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[benchmark]}" \
    --slurpfile barrier "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[barrier]}" \
    --slurpfile admission "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[admission]}" '
      ($result | length) == 1 and ($barrier | length) == 1 and
      ($admission | length) == 1 and
      .load == {
        failed_requests:$result[0].failed_requests,
        histogram_encoding:$result[0].latency.histogram_encoding,
        requested_duration_nanos:$result[0].requested_duration_nanos,
        successful_requests:$result[0].successful_requests,
        traffic_elapsed_nanos:$result[0].traffic_elapsed_nanos
      } and
      .marker == {admitted_requests:$result[0].admitted_requests,
        encoding:$result[0].marker_encoding,
        first_request_ordinal:$result[0].first_request_ordinal,
        last_request_ordinal:$result[0].last_request_ordinal,
        prefix:$result[0].marker_prefix} and
      .attribution == {
        admission_receipt_sha256:(.files[] |
          select(.role == "admission") | .sha256),
        ambiguous:$admission[0].admission.ambiguous,
        exact_hit_count:$admission[0].trace.exact_hit_count,
        explicit_root_count:$admission[0].trace.explicit_root_count,
        overload:$admission[0].admission.overload,
        received_batches:$admission[0].trace.received_batches,
        received_spans:$admission[0].trace.received_spans,
        retained_bytes:$admission[0].trace.retained_bytes,
        retained_span_count:$admission[0].trace.retained_span_count,
        unexpected_evictions:$admission[0].admission.unexpected_evictions} and
      .map.map_id == $barrier[0].map.map_id and
      .map.max_entries == ($barrier[0].map.max_entries | tonumber) and
      .map.content_sha256 == $barrier[0].map.content_sha256 and
      .map.postload_content_sha256 == $barrier[0].map.content_sha256
  ' "$manifest" >/dev/null || return $?
  stack_sha256="$(sha256sum -- \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[stack_identity]}")" || return $?
  stack_sha256="${stack_sha256%% *}"
  manifest_stack_sha256="$(jq -er \
    '.identity.stack_identity_sha256' "$manifest")" || return $?
  [[ "$stack_sha256" == "$manifest_stack_sha256" ]] || return 1

  map_id="$(jq -er '.map.map_id' "$manifest")" || return $?
  for role in map_baseline cleanup_recovery idle_before idle_after; do
    path="${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[$role]}"
    resolved="$(pressure_map_metric \
      "$path" obi_bpf_map_entries_total "$map_id")" || return $?
    [[ "${resolved%% *}" == "$map_id" ]] || return 1
    map_entries="${resolved#* }"
    [[ "$map_entries" == 0 ]] || return 1
  done
  if ((expected_cycle == BENCHMARK_PRESSURE_CYCLE_COUNT)); then
    for role in recovery_1 recovery_2; do
      path="${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[$role]}"
      resolved="$(pressure_map_metric \
        "$path" obi_bpf_map_entries_total "$map_id")" || return $?
      [[ "${resolved%% *}" == "$map_id" && "${resolved#* }" == 0 ]] || return 1
    done
    recovery_one_sha256="$(sha256sum -- \
      "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[recovery_1]}")" || return $?
    recovery_one_sha256="${recovery_one_sha256%% *}"
    recovery_two_sha256="$(sha256sum -- \
      "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[recovery_2]}")" || return $?
    recovery_two_sha256="${recovery_two_sha256%% *}"
    jq -e --arg first "$recovery_one_sha256" \
      --arg second "$recovery_two_sha256" '
        .recovery.sample_sha256s == [$first,$second]
      ' "$manifest" >/dev/null || return $?
  fi
  jq -e --slurpfile cleanup \
    "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[cleanup]}" '
    ($cleanup | length) == 1 and
    $cleanup[0].cleanup_verified == true and
    $cleanup[0].process_map_id == 0 and
    $cleanup[0].touched == .map.max_entries and
    $cleanup[0].verified_absent_entries == (.map.max_entries + 1) and
    ($cleanup[0].map_id | tostring) == .map.map_id
  ' "$manifest" >/dev/null || return $?

  for role in resources_baseline stack_identity fill benchmark verify \
    resources_postload admission cleanup idle_before idle_after resources_postidle; do
    expected_phase_sha256="$(jq -er --arg role "$role" \
      '.files[] | select(.role == $role) | .sha256' "$manifest")" || return $?
    case "$role" in
      resources_baseline) name=baseline_resources_captured ;;
      stack_identity) name=prepare_started ;;
      fill) name=capacity_ready ;;
      benchmark) name=load_finished ;;
      verify) name=content_verified ;;
      resources_postload) name=postload_resources_captured ;;
      admission) name=attribution_reconciled ;;
      cleanup) name=cleanup_absent ;;
      idle_before) name=idle_started ;;
      idle_after) name=idle_finished ;;
      resources_postidle) name=postidle_resources_captured ;;
      *) return 1 ;;
    esac
    phase_sha256="$(jq -er --arg name "$name" \
      '.phases[] | select(.name == $name) | .evidence_sha256' "$manifest")" ||
      return $?
    [[ "$phase_sha256" == "$expected_phase_sha256" ]] || return 1
  done
  load_started_sha256="$(jq -er \
    '.phases[] | select(.name == "load_started") | .evidence_sha256' \
    "$manifest")" || return $?
  ready_sha256="$(jq -er \
    '.ready.sha256' "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[barrier]}")" ||
    return $?
  release_published_sha256="$(jq -er \
    '.phases[] | select(.name == "release_published") | .evidence_sha256' \
    "$manifest")" || return $?
  release_sha256="$(jq -er \
    '.release.sha256' "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[barrier]}")" ||
    return $?
  [[ "$load_started_sha256" == "$ready_sha256" &&
    "$release_published_sha256" == "$release_sha256" ]] || return 1
  for pinned_key in "${!BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[@]}"; do
    pinned_path="${BENCHMARK_PRESSURE_PINNED_EVIDENCE_PATHS[$pinned_key]}"
    original_pinned_path="${BENCHMARK_PRESSURE_ORIGINAL_EVIDENCE_PATHS[$pinned_key]}"
    path="$manifest_dir/${BENCHMARK_PRESSURE_PINNED_EVIDENCE_NAMES[$pinned_key]}"
    pinned_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
      "$original_pinned_path")" ||
      return $?
    pinned_sha256="$(sha256sum -- "$pinned_path")" || return $?
    pinned_sha256="${pinned_sha256%% *}"
    observed_sha256="$(sha256sum -- "$original_pinned_path")" || return $?
    observed_sha256="${observed_sha256%% *}"
    [[ "$pinned_identity" == \
        "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_IDENTITIES[$pinned_key]}" &&
      "$pinned_sha256" == \
        "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_SHA256S[$pinned_key]}" &&
      "$observed_sha256" == \
        "${BENCHMARK_PRESSURE_PINNED_EVIDENCE_SHA256S[$pinned_key]}" &&
      -f "$path" && ! -L "$path" &&
      "$path" -ef "$original_pinned_path" ]] || return 1
  done
  rm -- "$roster" || return $?
  roster=""
  observed_private_root_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$private_root")" || return $?
  observed_manifest_dir_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$manifest_dir")" || return $?
  lexical_private_root_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$private_root_lexical")" || return $?
  lexical_manifest_dir_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$manifest_dir_lexical")" || return $?
  observed_manifest_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- \
    "$manifest_original")" || return $?
  observed_manifest_sha256="$(sha256sum -- "$manifest_original")" || return $?
  observed_manifest_sha256="${observed_manifest_sha256%% *}"
  lexical_manifest_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- \
    "$manifest_path")" || return $?
  [[ "$observed_private_root_identity" == "$private_root_identity" &&
    "$observed_manifest_dir_identity" == "$manifest_dir_identity" &&
    "$lexical_private_root_identity" == "$private_root_identity" &&
    "$lexical_manifest_dir_identity" == "$manifest_dir_identity" &&
    "$observed_manifest_identity" == "$manifest_identity" &&
    "$observed_manifest_sha256" == "$manifest_sha256" &&
    "$lexical_manifest_identity" == "$manifest_identity" &&
    "$private_root_lexical" -ef "$private_root" &&
    "$manifest_dir_lexical" -ef "$manifest_dir" &&
    "$manifest_path" -ef "$manifest_original" ]] || return 1
  benchmark_pressure_cycle_directory_roster_matches \
    "$manifest" "$expected_rows" "$manifest_dir" "$manifest_leaf"
)

write_benchmark_pressure_private_manifest() {
  local -r cycle="$1"
  local -r cycle_dir="$2"
  local -r phases_json="$3"
  local -r idle_elapsed_centiseconds="$4"
  local -r recovery_one_tick="${5:-}"
  local -r recovery_two_tick="${6:-}"
  local target="$cycle_dir/private-manifest.json"
  local candidate=""
  local files='[]'
  local recovery='{"captured_monotonic_centiseconds":[],"consecutive":false,"map_entries":[],"required_samples":0,"sample_sha256s":[]}'
  local role=""
  local name=""
  local path=""
  local sha256=""
  local size=""
  local entry=""
  local stack_sha256=""
  local content_sha256=""
  local successful_requests=""
  local failed_requests=""
  local requested_duration_nanos=""
  local traffic_elapsed_nanos=""
  local recovery_one_sha256=""
  local recovery_two_sha256=""
  local admission_sha256=""
  local marker_prefix=""
  local marker_encoding=""
  local admitted_requests=""
  local first_request_ordinal=""
  local last_request_ordinal=""
  local attribution=""
  local phase_candidate=""
  local load_elapsed_centiseconds=""
  local committed_result=""
  local committed_stderr=""
  local committed_receipt=""
  local -a roles=(admission barrier benchmark benchmark_stderr
    benchmark_client_commit bridge_reconciliation prepare fill verify cleanup \
    cleanup_recovery idle_before
    idle_after java_after java_after_stderr java_before java_before_stderr
    java_delta metrics_after metrics_before metrics_delta resources_baseline
    resources_postload resources_postidle stack_identity map_baseline
    phase_boundaries trace_projection trace_reset trace_snapshot)
  local -a names=(admission-receipt.json barrier-receipt.json benchmark-result.json
    benchmark.stderr.log benchmark-client-commit.json \
    bridge-reconciliation.json map-prepare.json map-fill.json
    map-verify.json map-cleanup.json map-recovered.prom idle-before.prom
    idle-after.prom java-diagnostics-after.txt java-diagnostics-after.stderr
    java-diagnostics-before.txt java-diagnostics-before.stderr
    java-diagnostics.delta obi-metrics-after.prom obi-metrics-before.prom
    obi-metrics.delta resources-baseline.json resources-postload.json
    resources-postidle.json stack-identity.json map-baseline.prom
    phase-boundaries.json trace-projection.json trace-reset.json
    trace-snapshot.json)
  local index=0

  [[ "$cycle" =~ ^([1-9]|10)$ && "$idle_elapsed_centiseconds" =~ ^[0-9]+$ &&
    "$idle_elapsed_centiseconds" -ge "$((BENCHMARK_PRESSURE_IDLE_SECONDS * 100))" &&
    "$idle_elapsed_centiseconds" -lt "$(((BENCHMARK_PRESSURE_IDLE_SECONDS + 1) * 100))" &&
    ! -e "$target" && ! -L "$target" ]] || return 1
  benchmark_pressure_client_bundle_images_for_consumer \
    "$cycle_dir/benchmark-result.json" "$cycle" committed_result \
    committed_stderr committed_receipt || return $?
  load_elapsed_centiseconds="$(jq -er '
    ([.[] | select(.name == "load_started") |
      .monotonic_centiseconds] | if length == 1 then .[0] else error("load start") end) as $start |
    ([.[] | select(.name == "load_finished") |
      .monotonic_centiseconds] | if length == 1 then .[0] else error("load finish") end) as $finish |
    select($finish >= $start) | $finish - $start
  ' <<<"$phases_json")" || return $?
  [[ "$load_elapsed_centiseconds" =~ ^[0-9]+$ &&
    "$load_elapsed_centiseconds" -ge \
      "$((BENCHMARK_PRESSURE_LOAD_SECONDS * 100))" &&
    "$load_elapsed_centiseconds" -lt \
      "$(((BENCHMARK_PRESSURE_LOAD_SECONDS + 1) * 100))" ]] || return 1
  phase_candidate="$(mktemp "$cycle_dir/.phase-boundaries.XXXXXX")" || return $?
  jq -cS -n --argjson cycle "$cycle" \
    --argjson load_requested_seconds "$BENCHMARK_PRESSURE_LOAD_SECONDS" \
    --argjson load_elapsed_centiseconds "$load_elapsed_centiseconds" \
    --argjson idle_requested_seconds "$BENCHMARK_PRESSURE_IDLE_SECONDS" \
    --argjson idle_elapsed_centiseconds "$idle_elapsed_centiseconds" \
    --argjson phases "$phases_json" '
      {schema:"obi-benchmark-pressure-phase-boundaries-v1",cycle:$cycle,
       load_requested_seconds:$load_requested_seconds,
       load_elapsed_centiseconds:$load_elapsed_centiseconds,
       idle_requested_seconds:$idle_requested_seconds,
       idle_elapsed_centiseconds:$idle_elapsed_centiseconds,phases:$phases}
  ' >"$phase_candidate" || return $?
  chmod 0600 -- "$phase_candidate" || return $?
  benchmark_pressure_publish_validated_file \
    "$phase_candidate" "$cycle_dir/phase-boundaries.json" 600 \
    validate_benchmark_pressure_phase_boundaries "$cycle" \
    "$cycle_dir/benchmark-result.json" || return $?
  if ((cycle == BENCHMARK_PRESSURE_CYCLE_COUNT)); then
    [[ "$recovery_one_tick" =~ ^[0-9]+$ &&
      "$recovery_two_tick" =~ ^[0-9]+$ &&
      "$recovery_one_tick" -le "$recovery_two_tick" ]] || return 1
    roles+=(recovery_1 recovery_2)
    names+=(recovery-01.prom recovery-02.prom)
  fi
  for ((index = 0; index < ${#roles[@]}; index++)); do
    role="${roles[$index]}"
    name="${names[$index]}"
    case "$role" in
      benchmark) path="$committed_result" ;;
      benchmark_stderr) path="$committed_stderr" ;;
      benchmark_client_commit) path="$committed_receipt" ;;
      *) path="$cycle_dir/$name" ;;
    esac
    benchmark_pressure_trusted_regular_path "$path" || return $?
    if [[ "$path" =~ ^/proc/self/fd/[1-9][0-9]*$ ]]; then
      [[ "$(stat -Lc '%u:%a:%h' -- "$path")" == "$EUID:600:0" ]] || return 1
    else
      [[ "$(stat -Lc '%u:%a:%h' -- "$path")" == "$EUID:600:1" ]] || return 1
    fi
    sha256="$(sha256sum -- "$path")" || return $?
    sha256="${sha256%% *}"
    size="$(stat -Lc '%s' -- "$path")" || return $?
    entry="$(jq -cS -n --arg role "$role" --arg name "$name" \
      --arg sha256 "$sha256" --argjson size_bytes "$size" \
      '{role:$role,name:$name,sha256:$sha256,size_bytes:$size_bytes}')" || return $?
    files="$(jq -cS --argjson entry "$entry" '. + [$entry]' <<<"$files")" || return $?
  done
  stack_sha256="$(sha256sum -- "$cycle_dir/stack-identity.json")" || return $?
  stack_sha256="${stack_sha256%% *}"
  content_sha256="$(jq -er '.map.content_sha256' "$cycle_dir/barrier-receipt.json")" ||
    return $?
  successful_requests="$(jq -er '.successful_requests' \
    "$committed_result")" || return $?
  failed_requests="$(jq -er '.failed_requests' \
    "$committed_result")" || return $?
  requested_duration_nanos="$(jq -er '.requested_duration_nanos' \
    "$committed_result")" || return $?
  traffic_elapsed_nanos="$(jq -er '.traffic_elapsed_nanos' \
    "$committed_result")" || return $?
  marker_prefix="$(jq -er '.marker_prefix' \
    "$committed_result")" || return $?
  marker_encoding="$(jq -er '.marker_encoding' \
    "$committed_result")" || return $?
  admitted_requests="$(jq -er '.admitted_requests' \
    "$committed_result")" || return $?
  first_request_ordinal="$(jq -er '.first_request_ordinal' \
    "$committed_result")" || return $?
  last_request_ordinal="$(jq -er '.last_request_ordinal' \
    "$committed_result")" || return $?
  admission_sha256="$(sha256sum -- "$cycle_dir/admission-receipt.json")" ||
    return $?
  admission_sha256="${admission_sha256%% *}"
  attribution="$(jq -cS --arg admission_sha256 "$admission_sha256" '
    {admission_receipt_sha256:$admission_sha256,
     overload:.admission.overload,ambiguous:.admission.ambiguous,
     unexpected_evictions:.admission.unexpected_evictions,
     received_batches:.trace.received_batches,
     received_spans:.trace.received_spans,
     retained_bytes:.trace.retained_bytes,
     retained_span_count:.trace.retained_span_count,
     exact_hit_count:.trace.exact_hit_count,
     explicit_root_count:.trace.explicit_root_count}
  ' "$cycle_dir/admission-receipt.json")" || return $?
  if ((cycle == BENCHMARK_PRESSURE_CYCLE_COUNT)); then
    recovery_one_sha256="$(sha256sum -- "$cycle_dir/recovery-01.prom")" || return $?
    recovery_one_sha256="${recovery_one_sha256%% *}"
    recovery_two_sha256="$(sha256sum -- "$cycle_dir/recovery-02.prom")" || return $?
    recovery_two_sha256="${recovery_two_sha256%% *}"
    recovery="$(jq -cS -n --arg first "$recovery_one_sha256" \
      --arg second "$recovery_two_sha256" \
      --argjson first_tick "$recovery_one_tick" \
      --argjson second_tick "$recovery_two_tick" '
        {captured_monotonic_centiseconds:[$first_tick,$second_tick],
         consecutive:true,map_entries:[0,0],required_samples:2,
         sample_sha256s:[$first,$second]}
      ')" || return $?
  else
    [[ -z "$recovery_one_tick" && -z "$recovery_two_tick" ]] || return 1
  fi
  candidate="$(mktemp "$cycle_dir/.private-manifest.XXXXXX")" || return $?
  jq -cS -n \
    --argjson cycle "$cycle" \
    --argjson cycle_count "$BENCHMARK_PRESSURE_CYCLE_COUNT" \
    --argjson load_seconds "$BENCHMARK_PRESSURE_LOAD_SECONDS" \
    --argjson idle_seconds "$BENCHMARK_PRESSURE_IDLE_SECONDS" \
    --arg stack_sha256 "$stack_sha256" \
    --arg process_map_id "$PRESSURE_PROCESS_MAP_ID" \
    --arg process_pid "$PRESSURE_PROCESS_PID" \
    --arg process_namespace "$PRESSURE_PROCESS_NAMESPACE" \
    --argjson successful_requests "$successful_requests" \
    --argjson failed_requests "$failed_requests" \
    --argjson requested_duration_nanos "$requested_duration_nanos" \
    --argjson traffic_elapsed_nanos "$traffic_elapsed_nanos" \
    --argjson load_elapsed_centiseconds "$load_elapsed_centiseconds" \
    --arg histogram_encoding "$BENCHMARK_PRESSURE_HISTOGRAM_ENCODING" \
    --arg marker_prefix "$marker_prefix" \
    --arg marker_encoding "$marker_encoding" \
    --argjson admitted_requests "$admitted_requests" \
    --argjson first_request_ordinal "$first_request_ordinal" \
    --argjson last_request_ordinal "$last_request_ordinal" \
    --argjson attribution "$attribution" \
    --arg map_id "$PRESSURE_MAP_ID" \
    --argjson capacity "$PRESSURE_MAP_MAX_ENTRIES" \
    --arg content_sha256 "$content_sha256" \
    --argjson idle_elapsed_centiseconds "$idle_elapsed_centiseconds" \
    --argjson phases "$phases_json" \
    --argjson files "$files" \
    --argjson recovery "$recovery" '
      {schema:"obi-benchmark-pressure-private-manifest-v2",status:"passed",
       acceptance_eligible:false,cycle:$cycle,
       requested:{cycle_count:$cycle_count,load_seconds:$load_seconds,
         idle_seconds:$idle_seconds},
       timing:{load_elapsed_centiseconds:$load_elapsed_centiseconds,
         idle_elapsed_centiseconds:$idle_elapsed_centiseconds},
       identity:{stack_identity_sha256:$stack_sha256,
         process_map_id:$process_map_id,process_pid:$process_pid,
         process_namespace:$process_namespace},
       load:{requested_duration_nanos:$requested_duration_nanos,
         traffic_elapsed_nanos:$traffic_elapsed_nanos,
         successful_requests:$successful_requests,failed_requests:$failed_requests,
         histogram_encoding:$histogram_encoding},
       marker:{prefix:$marker_prefix,encoding:$marker_encoding,
         admitted_requests:$admitted_requests,
         first_request_ordinal:$first_request_ordinal,
         last_request_ordinal:$last_request_ordinal},
       attribution:$attribution,
       map:{map_id:$map_id,baseline_entries:0,max_entries:$capacity,
         filled_entries:$capacity,capacity_rejected_entries:1,
         content_sha256:$content_sha256,postload_content_sha256:$content_sha256,
         cleanup_entries:0},phases:$phases,files:$files,recovery:$recovery}
    ' >"$candidate" || return $?
  chmod 0600 -- "$candidate" || return $?
  benchmark_pressure_publish_validated_file \
    "$candidate" "$target" 600 \
    validate_benchmark_pressure_private_manifest "$cycle" "${cycle_dir%/*}"
}

validate_benchmark_pressure_aggregate() (
  local -r aggregate_input="$1"
  local -r private_root_lexical="${2:-}"
  local aggregate=""
  local aggregate_original=""
  local aggregate_fd=""
  local aggregate_snapshot_fd=""
  local aggregate_source_identity=""
  local aggregate_snapshot_sha256=""
  local aggregate_snapshot_size=""
  local aggregate_identity=""
  local aggregate_sha256=""
  local lexical_aggregate_identity=""
  local observed_aggregate_identity=""
  local observed_aggregate_sha256=""
  local aggregate_snapshot_terminal_sha256=""
  local aggregate_parent=""
  local aggregate_leaf=""
  local aggregate_parent_fd=""
  local aggregate_parent_identity=""
  local aggregate_parent_lexical_identity=""
  local aggregate_is_exact_descriptor=false
  local private_root=""
  local private_root_fd=""
  local private_root_identity=""
  local lexical_private_root_identity=""
  local observed_private_root_identity=""
  local cycle_dir=""
  local cycle_dir_fd=""
  local cycle_dir_identity=""
  local observed_cycle_dir_identity=""
  local cycle_manifest_fd=""
  local cycle_manifest_snapshot_fd=""
  local cycle_manifest_path=""
  local lexical_cycle_manifest_path=""
  local cycle_manifest_original=""
  local cycle_manifest_identity=""
  local cycle_manifest_source_identity=""
  local cycle_manifest_snapshot_sha256=""
  local cycle_manifest_snapshot_size=""
  local observed_cycle_manifest_identity=""
  local cycle=""
  local tag=""
  local manifest=""
  local expected_sha256=""
  local expected_size=""
  local expected_count=""
  local observed_sha256=""
  local observed_snapshot_sha256=""
  local observed_size=""
  local observed_count=""
  local expected_barrier_sha256=""
  local expected_admission_sha256=""
  local expected_result_sha256=""
  local baseline_private_identity=""
  local observed_private_identity=""
  local baseline_map_id=""
  local observed_map_id=""
  local marker_prefix=""
  local marker_prefixes=$'\n'
  local receiver_instance_id=""
  local baseline_receiver_instance_id=""
  local reset_generation=""
  local previous_reset_generation=""
  local final_recovery=""
  local private_entries=""
  local observed_private_entries=""
  local expected_private_entries=""
  local roster_text=""
  local role=""
  local name=""
  local extra=""
  local limits=""
  local maximum_bytes=""
  local maximum_lines=""
  local leaf_fd=""
  local leaf_snapshot_fd=""
  local leaf_path=""
  local lexical_leaf_path=""
  local leaf_original_path=""
  local leaf_identity=""
  local leaf_source_identity=""
  local leaf_snapshot_sha256=""
  local leaf_snapshot_size=""
  local leaf_sha256=""
  local leaf_key=""
  local expected_leaf_sha256=""
  local expected_leaf_size=""
  local leaf_rows=0
  local coherent_specification=$'V\t1\n'
  local -a aggregate_snapshot_fds=()
  local -A aggregate_cycle_dirs=()
  local -A aggregate_cycle_dir_fds=()
  local -A aggregate_cycle_dir_identities=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_PATHS=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_PATHS=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_FDS=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_IDENTITIES=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_SHA256S=()
  local -A aggregate_manifest_identities=()
  local -A aggregate_manifest_sha256s=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_LEAF_ORIGINAL_PATHS=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_LEAF_ORIGINAL_FDS=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_LEAF_NAMES=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_LEAF_IDENTITIES=()
  local -A BENCHMARK_PRESSURE_CAMPAIGN_LEAF_SHA256S=()

  if [[ "$aggregate_input" =~ ^/proc/self/fd/[1-9][0-9]*$ ]]; then
    aggregate_is_exact_descriptor=true
  elif [[ -n "$private_root_lexical" ]]; then
    [[ "$aggregate_input" == /* && "${aggregate_input##*/}" =~ \
      ^[A-Za-z0-9._-]+$ ]] || return 1
    aggregate_parent="${aggregate_input%/*}"
    [[ -n "$aggregate_parent" ]] || aggregate_parent=/
    aggregate_leaf="${aggregate_input##*/}"
    [[ -d "$aggregate_parent" && ! -L "$aggregate_parent" ]] || return 1
    exec {aggregate_parent_fd}<"$aggregate_parent" || return $?
    aggregate_parent_identity="$(stat -Lc '%d:%i:%u:%a' -- \
      "/proc/self/fd/$aggregate_parent_fd")" || return $?
    aggregate_parent_lexical_identity="$(stat -Lc '%d:%i:%u:%a' -- \
      "$aggregate_parent")" || return $?
    [[ "$aggregate_parent_identity" == "$aggregate_parent_lexical_identity" &&
      "$aggregate_parent_identity" =~ \
        ^[0-9]+:[1-9][0-9]*:$EUID:[0-7]{3,4}$ &&
      "$aggregate_parent" -ef "/proc/self/fd/$aggregate_parent_fd" ]] || return 1
  fi
  benchmark_pressure_trusted_regular_path "$aggregate_input" || return $?
  bounded_evidence_file "$aggregate_input" \
    "$BENCHMARK_PRESSURE_AGGREGATE_MAX_BYTES" 1 || return $?
  benchmark_pressure_trusted_regular_path "$aggregate_input" || return $?
  exec {aggregate_fd}<"$aggregate_input" || return $?
  aggregate_original="/proc/self/fd/$aggregate_fd"
  aggregate_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- "$aggregate_original")" ||
    return $?
  lexical_aggregate_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- \
    "$aggregate_input")" || return $?
  benchmark_pressure_trusted_regular_path "$aggregate_input" || return $?
  [[ "$aggregate_identity" =~ \
      ^[0-9]+:[1-9][0-9]*:$EUID:(600|644):(0|1)$ &&
    "$lexical_aggregate_identity" == "$aggregate_identity" &&
    "$aggregate_input" -ef "$aggregate_original" ]] || return 1
  benchmark_pressure_hold_file_snapshot \
    "$aggregate_original" "$BENCHMARK_PRESSURE_AGGREGATE_MAX_BYTES" \
    aggregate_snapshot_fd aggregate_source_identity aggregate_snapshot_sha256 \
    aggregate_snapshot_size || return $?
  aggregate="/proc/self/fd/$aggregate_snapshot_fd"
  aggregate_sha256="$(sha256sum -- "$aggregate_original")" || return $?
  aggregate_sha256="${aggregate_sha256%% *}"
  benchmark_pressure_trusted_regular_path "$aggregate_input" || return $?
  [[ "${aggregate_source_identity%:*}" == "$aggregate_identity" &&
    "$aggregate_snapshot_sha256" == "$aggregate_sha256" &&
    "$aggregate_snapshot_size" == "$(stat -Lc '%s' -- "$aggregate_original")" &&
    "$aggregate_input" -ef "$aggregate_original" ]] ||
    return 1
  benchmark_pressure_json_has_unique_object_keys \
    "$aggregate" "$BENCHMARK_PRESSURE_AGGREGATE_MAX_BYTES" || return $?
  jq -e \
    --argjson cycle_count "$BENCHMARK_PRESSURE_CYCLE_COUNT" \
    --argjson load_seconds "$BENCHMARK_PRESSURE_LOAD_SECONDS" \
    --argjson idle_seconds "$BENCHMARK_PRESSURE_IDLE_SECONDS" \
    --argjson recovery_samples "$BENCHMARK_PRESSURE_RECOVERY_SAMPLES" \
    --argjson maximum_successful_requests "$BENCHMARK_PRESSURE_MAX_SUCCESSFUL_REQUESTS" \
    --arg histogram_encoding "$BENCHMARK_PRESSURE_HISTOGRAM_ENCODING" '
      def integer: type == "number" and floor == .;
      def digest: type == "string" and test("^[0-9a-f]{64}$");
      . as $aggregate |
      keys == ["acceptance_eligible","cycle_count","cycles","evidence_class",
        "histograms","idle_seconds_per_cycle","load_seconds_per_cycle",
        "recovery","schema","status"] and
      .schema == "obi-benchmark-pressure-cycles-v2" and
      .status == "non_acceptance" and .acceptance_eligible == false and
      .evidence_class == "targeted_pressure_cycle_campaign" and
      .cycle_count == $cycle_count and
      .load_seconds_per_cycle == $load_seconds and
      .idle_seconds_per_cycle == $idle_seconds and
      .histograms == "linked_not_pooled" and
      (.cycles | type == "array" and length == $cycle_count) and
      all(range(0;$cycle_count);
        $aggregate.cycles[.].cycle == (. + 1)) and
      all(.cycles[];
        keys == ["admission_receipt_sha256","barrier_receipt_sha256","cycle",
          "histogram_encoding",
          "idle_elapsed_centiseconds","idle_requested_seconds",
          "load_elapsed_nanos","load_requested_seconds",
          "private_file_count","private_manifest_bytes",
          "private_manifest_sha256","rle_result_sha256",
          "stack_identity_sha256","status","successful_requests",
          "unexpected_evictions"] and
        .status == "passed" and
        .histogram_encoding == $histogram_encoding and
        .load_requested_seconds == $load_seconds and
        .idle_requested_seconds == $idle_seconds and
        (.idle_elapsed_centiseconds | integer and
          . >= ($idle_seconds * 100) and
          . < (($idle_seconds + 1) * 100)) and
        (.load_elapsed_nanos | integer and . >= ($load_seconds * 1000000000) and
          . < (($load_seconds + 1) * 1000000000)) and
        (.successful_requests | integer and . > 0 and
          . <= $maximum_successful_requests) and
        (.private_file_count | integer) and
        .private_file_count ==
          (if .cycle == $cycle_count then 32 else 30 end) and
        (.private_manifest_bytes | integer and . > 0 and . <= 1048576) and
        (.private_manifest_sha256 | digest) and
        (.admission_receipt_sha256 | digest) and
        (.barrier_receipt_sha256 | digest) and
        (.rle_result_sha256 | digest) and
        (.stack_identity_sha256 | digest) and .unexpected_evictions == 0) and
      ([.cycles[].stack_identity_sha256] | unique | length) == 1 and
      (.recovery | keys) == ["captured_monotonic_centiseconds","consecutive",
        "map_entries","required_samples","sample_sha256s"] and
      .recovery.required_samples == $recovery_samples and
      .recovery.consecutive == true and .recovery.map_entries == [0,0] and
      (.recovery.sample_sha256s | length == $recovery_samples and
        all(.[]; digest)) and
      (.recovery.captured_monotonic_centiseconds |
        length == $recovery_samples and all(.[]; integer and . >= 0)) and
      .recovery.captured_monotonic_centiseconds[0] <=
        .recovery.captured_monotonic_centiseconds[1] and
      ([paths(objects) as $path | getpath($path) | keys[]] |
        any(. == "histogram" or . == "pooled_histogram")) == false and
      ([.. | strings] | any(test("benchmark-pressure-cycles-raw|barrier-receipt\\.json|benchmark-result\\.json|pressure-control|/"))) == false
  ' "$aggregate" >/dev/null || return $?
  if [[ -z "$private_root_lexical" ]]; then
    benchmark_pressure_trusted_regular_path "$aggregate_input" || return $?
    observed_aggregate_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- \
      "$aggregate_original")" || return $?
    observed_aggregate_sha256="$(sha256sum -- "$aggregate_original")" || return $?
    observed_aggregate_sha256="${observed_aggregate_sha256%% *}"
    lexical_aggregate_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- \
      "$aggregate_input")" || return $?
    benchmark_pressure_trusted_regular_path "$aggregate_input" || return $?
    [[ "$observed_aggregate_identity" == "$aggregate_identity" &&
      "$observed_aggregate_sha256" == "$aggregate_sha256" &&
      "$lexical_aggregate_identity" == "$aggregate_identity" &&
      "$aggregate_input" -ef "$aggregate_original" ]]
    return
  fi
  [[ -d "$private_root_lexical" && ! -L "$private_root_lexical" ]] || return 1
  exec {private_root_fd}<"$private_root_lexical" || return $?
  private_root="/proc/self/fd/$private_root_fd/."
  private_root_identity="$(stat -Lc '%d:%i:%u:%a' -- "$private_root")" ||
    return $?
  lexical_private_root_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$private_root_lexical")" || return $?
  [[ "$private_root_identity" =~ ^[0-9]+:[1-9][0-9]*:$EUID:700$ &&
    "$lexical_private_root_identity" == "$private_root_identity" &&
    "$private_root_lexical" -ef "$private_root" ]] || return 1
  benchmark_pressure_bounded_directory_roster \
    "$private_root" private_entries || return $?
  ((${#private_entries} <= 256)) || return 1
  for ((cycle = 1; cycle <= BENCHMARK_PRESSURE_CYCLE_COUNT; cycle++)); do
    printf -v tag '%02d' "$cycle"
    expected_private_entries+="cycle-$tag:d"$'\n'
  done
  expected_private_entries="${expected_private_entries%$'\n'}"
  [[ "$private_entries" == "$expected_private_entries" ]] || return 1

  # Establish one campaign-wide snapshot before validating any cycle.  Every
  # cycle directory, manifest, and manifest-listed leaf remains open until the
  # aggregate's terminal identity/digest/roster seal below.
  for ((cycle = 1; cycle <= BENCHMARK_PRESSURE_CYCLE_COUNT; cycle++)); do
    printf -v tag '%02d' "$cycle"
    [[ -d "$private_root/cycle-$tag" &&
      ! -L "$private_root/cycle-$tag" ]] || return 1
    unset cycle_dir_fd
    exec {cycle_dir_fd}<"$private_root/cycle-$tag" || return $?
    aggregate_snapshot_fds+=("$cycle_dir_fd")
    cycle_dir="/proc/self/fd/$cycle_dir_fd/."
    cycle_dir_identity="$(stat -Lc '%d:%i:%u:%a' -- "$cycle_dir")" ||
      return $?
    [[ "$cycle_dir_identity" =~ ^[0-9]+:[1-9][0-9]*:$EUID:700$ &&
      "$private_root/cycle-$tag" -ef "$cycle_dir" ]] || return 1
    aggregate_cycle_dirs["$cycle"]="$cycle_dir"
    aggregate_cycle_dir_fds["$cycle"]="$cycle_dir_fd"
    aggregate_cycle_dir_identities["$cycle"]="$cycle_dir_identity"

    cycle_manifest_path="$cycle_dir/private-manifest.json"
    lexical_cycle_manifest_path="$private_root_lexical/cycle-$tag/private-manifest.json"
    [[ ! -L "$cycle_manifest_path" && -f "$cycle_manifest_path" &&
      ! -L "$lexical_cycle_manifest_path" &&
      -f "$lexical_cycle_manifest_path" ]] || return 1
    unset cycle_manifest_fd
    exec {cycle_manifest_fd}<"$cycle_manifest_path" || return $?
    aggregate_snapshot_fds+=("$cycle_manifest_fd")
    cycle_manifest_original="/proc/self/fd/$cycle_manifest_fd"
    cycle_manifest_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
      "$cycle_manifest_original")" || return $?
    [[ ! -L "$cycle_manifest_path" && -f "$cycle_manifest_path" &&
      ! -L "$lexical_cycle_manifest_path" &&
      -f "$lexical_cycle_manifest_path" &&
      "$cycle_manifest_identity" =~ \
      ^[0-9]+:[1-9][0-9]*:$EUID:600:1:[1-9][0-9]*$ &&
      "$cycle_manifest_path" -ef "$cycle_manifest_original" &&
      "$lexical_cycle_manifest_path" -ef "$cycle_manifest_original" ]] || return 1
    unset cycle_manifest_snapshot_fd
    benchmark_pressure_hold_file_snapshot \
      "$cycle_manifest_original" "$BENCHMARK_PRESSURE_MANIFEST_MAX_BYTES" \
      cycle_manifest_snapshot_fd cycle_manifest_source_identity \
      cycle_manifest_snapshot_sha256 cycle_manifest_snapshot_size || return $?
    aggregate_snapshot_fds+=("$cycle_manifest_snapshot_fd")
    manifest="/proc/self/fd/$cycle_manifest_snapshot_fd"
    [[ "$cycle_manifest_source_identity" == "$cycle_manifest_identity" &&
      "$cycle_manifest_snapshot_size" == "${cycle_manifest_identity##*:}" ]] ||
      return 1
    bounded_evidence_file "$manifest" \
      "$BENCHMARK_PRESSURE_MANIFEST_MAX_BYTES" 1 || return $?
    benchmark_pressure_json_has_unique_object_keys \
      "$manifest" "$BENCHMARK_PRESSURE_MANIFEST_MAX_BYTES" || return $?
    observed_sha256="$(sha256sum -- "$cycle_manifest_original")" || return $?
    observed_sha256="${observed_sha256%% *}"
    [[ ! -L "$cycle_manifest_path" && -f "$cycle_manifest_path" &&
      ! -L "$lexical_cycle_manifest_path" &&
      -f "$lexical_cycle_manifest_path" &&
      "$observed_sha256" == "$cycle_manifest_snapshot_sha256" &&
      "$cycle_manifest_path" -ef "$cycle_manifest_original" &&
      "$lexical_cycle_manifest_path" -ef "$cycle_manifest_original" ]] ||
      return 1
    BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_PATHS["$cycle"]="$manifest"
    BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_PATHS["$cycle"]="$cycle_manifest_original"
    BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_FDS["$cycle"]="$cycle_manifest_fd"
    BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_IDENTITIES["$cycle"]="$cycle_manifest_identity"
    BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_SHA256S["$cycle"]="$observed_sha256"
    aggregate_manifest_identities["$cycle"]="$cycle_manifest_identity"
    aggregate_manifest_sha256s["$cycle"]="$observed_sha256"

    expected_count="$(jq -er '.files | length' "$manifest")" || return $?
    [[ "$expected_count" == \
      "$((cycle == BENCHMARK_PRESSURE_CYCLE_COUNT ? 32 : 30))" ]] || return 1
    benchmark_pressure_cycle_directory_roster_matches \
      "$manifest" "$expected_count" "$cycle_dir" private-manifest.json || return $?
    roster_text="$(jq -er \
      '.files[] | [.role,.name,.sha256,.size_bytes] | @tsv' \
      "$manifest")" || return $?
    ((${#roster_text} <= 65536)) || return 1
    leaf_rows=0
    while IFS=$'\t' read -r role name expected_leaf_sha256 \
      expected_leaf_size extra; do
      ((leaf_rows += 1))
      [[ -z "$extra" && "$role" =~ ^[a-z0-9_]+$ &&
        "$name" =~ ^[a-z0-9][a-z0-9.-]*$ &&
        "$expected_leaf_sha256" =~ ^[0-9a-f]{64}$ &&
        "$expected_leaf_size" =~ ^(0|[1-9][0-9]*)$ ]] || return 1
      leaf_key="$cycle:$role"
      [[ -z "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS[$leaf_key]+present}" ]] ||
        return 1
      leaf_path="$cycle_dir/$name"
      lexical_leaf_path="$private_root_lexical/cycle-$tag/$name"
      [[ ! -L "$leaf_path" && -f "$leaf_path" &&
        ! -L "$lexical_leaf_path" && -f "$lexical_leaf_path" ]] || return 1
      unset leaf_fd
      exec {leaf_fd}<"$leaf_path" || return $?
      aggregate_snapshot_fds+=("$leaf_fd")
      leaf_original_path="/proc/self/fd/$leaf_fd"
      leaf_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
        "$leaf_original_path")" ||
        return $?
      [[ ! -L "$leaf_path" && -f "$leaf_path" &&
        ! -L "$lexical_leaf_path" && -f "$lexical_leaf_path" &&
        "$leaf_identity" =~ \
          ^[0-9]+:[1-9][0-9]*:$EUID:600:1:$expected_leaf_size$ &&
        "$leaf_path" -ef "$leaf_original_path" &&
        "$lexical_leaf_path" -ef "$leaf_original_path" ]] || return 1
      limits="$(benchmark_pressure_role_limits "$role")" || return $?
      IFS=' ' read -r maximum_bytes maximum_lines extra <<<"$limits" || return $?
      [[ -z "$extra" ]] || return 1
      unset leaf_snapshot_fd
      benchmark_pressure_hold_file_snapshot \
        "$leaf_original_path" "$maximum_bytes" leaf_snapshot_fd \
        leaf_source_identity leaf_snapshot_sha256 leaf_snapshot_size || return $?
      aggregate_snapshot_fds+=("$leaf_snapshot_fd")
      leaf_path="/proc/self/fd/$leaf_snapshot_fd"
      [[ "$leaf_source_identity" == "$leaf_identity" &&
        "$leaf_snapshot_size" == "$expected_leaf_size" ]] || return 1
      bounded_evidence_file "$leaf_path" "$maximum_bytes" "$maximum_lines" ||
        return $?
      leaf_sha256="$(sha256sum -- "$leaf_original_path")" || return $?
      leaf_sha256="${leaf_sha256%% *}"
      [[ ! -L "$cycle_dir/$name" && -f "$cycle_dir/$name" &&
        ! -L "$lexical_leaf_path" && -f "$lexical_leaf_path" &&
        "$leaf_sha256" == "$expected_leaf_sha256" &&
        "$leaf_snapshot_sha256" == "$expected_leaf_sha256" &&
        "$cycle_dir/$name" -ef "$leaf_original_path" &&
        "$lexical_leaf_path" -ef "$leaf_original_path" ]] || return 1
      BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS["$leaf_key"]="$leaf_path"
      BENCHMARK_PRESSURE_CAMPAIGN_LEAF_ORIGINAL_PATHS["$leaf_key"]="$leaf_original_path"
      BENCHMARK_PRESSURE_CAMPAIGN_LEAF_ORIGINAL_FDS["$leaf_key"]="$leaf_fd"
      BENCHMARK_PRESSURE_CAMPAIGN_LEAF_NAMES["$leaf_key"]="$name"
      BENCHMARK_PRESSURE_CAMPAIGN_LEAF_IDENTITIES["$leaf_key"]="$leaf_identity"
      BENCHMARK_PRESSURE_CAMPAIGN_LEAF_SHA256S["$leaf_key"]="$leaf_sha256"
    done <<<"$roster_text"
    ((leaf_rows == expected_count)) || return 1
  done

  for ((cycle = 1; cycle <= BENCHMARK_PRESSURE_CYCLE_COUNT; cycle++)); do
    printf -v tag '%02d' "$cycle"
    cycle_dir="${aggregate_cycle_dirs[$cycle]}"
    cycle_dir_identity="${aggregate_cycle_dir_identities[$cycle]}"
    cycle_manifest_path="$cycle_dir/private-manifest.json"
    lexical_cycle_manifest_path="$private_root_lexical/cycle-$tag/private-manifest.json"
    manifest="${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_PATHS[$cycle]}"
    cycle_manifest_identity="${aggregate_manifest_identities[$cycle]}"
    [[ ! -L "$cycle_manifest_path" && -f "$cycle_manifest_path" &&
      ! -L "$lexical_cycle_manifest_path" &&
      -f "$lexical_cycle_manifest_path" ]] || return 1
    validate_benchmark_pressure_private_manifest \
      "$manifest" "$cycle" "$private_root" "$cycle_dir" || return $?
    expected_sha256="$(jq -er --argjson cycle "$cycle" \
      '.cycles[] | select(.cycle == $cycle) | .private_manifest_sha256' \
      "$aggregate")" || return $?
    expected_size="$(jq -er --argjson cycle "$cycle" \
      '.cycles[] | select(.cycle == $cycle) | .private_manifest_bytes' \
      "$aggregate")" || return $?
    expected_count="$(jq -er --argjson cycle "$cycle" \
      '.cycles[] | select(.cycle == $cycle) | .private_file_count' \
      "$aggregate")" || return $?
    observed_sha256="$(sha256sum -- "$manifest")" || return $?
    observed_sha256="${observed_sha256%% *}"
    observed_size="$(stat -Lc '%s' -- "$manifest")" || return $?
    observed_count="$(jq -er '.files | length' "$manifest")" || return $?
    [[ "$observed_sha256" == "$expected_sha256" &&
      "$observed_size" == "$expected_size" &&
      "$observed_count" == "$expected_count" ]] || return 1
    expected_barrier_sha256="$(jq -er '.files[] | select(.role == "barrier") | .sha256' \
      "$manifest")" || return $?
    expected_admission_sha256="$(jq -er \
      '.files[] | select(.role == "admission") | .sha256' \
      "$manifest")" || return $?
    expected_result_sha256="$(jq -er '.files[] | select(.role == "benchmark") | .sha256' \
      "$manifest")" || return $?
    jq -e --argjson cycle "$cycle" \
      --arg barrier "$expected_barrier_sha256" \
      --arg admission "$expected_admission_sha256" \
      --arg result "$expected_result_sha256" \
      --slurpfile manifest "$manifest" '
        .cycles[] | select(.cycle == $cycle) |
        ($manifest | length) == 1 and
        .status == $manifest[0].status and
        .load_requested_seconds == $manifest[0].requested.load_seconds and
        .idle_requested_seconds == $manifest[0].requested.idle_seconds and
        .load_elapsed_nanos == $manifest[0].load.traffic_elapsed_nanos and
        .idle_elapsed_centiseconds ==
          $manifest[0].timing.idle_elapsed_centiseconds and
        .successful_requests == $manifest[0].load.successful_requests and
        .histogram_encoding == $manifest[0].load.histogram_encoding and
        .stack_identity_sha256 ==
          $manifest[0].identity.stack_identity_sha256 and
        .admission_receipt_sha256 == $admission and
        .unexpected_evictions == 0 and
        .barrier_receipt_sha256 == $barrier and .rle_result_sha256 == $result
      ' "$aggregate" >/dev/null || return $?
    marker_prefix="$(jq -er '.marker.prefix' "$manifest")" || return $?
    [[ "$marker_prefix" =~ ^pressure-[0-9a-f]{32}-cycle-$tag$ &&
      "$marker_prefixes" != *$'\n'"$marker_prefix"$'\n'* ]] || return 1
    marker_prefixes+="$marker_prefix"$'\n'
    receiver_instance_id="$(jq -er \
      '.trace.receiver_instance_id' \
      "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS["$cycle:admission"]}")" ||
      return $?
    reset_generation="$(jq -er \
      '.trace.reset_generation' \
      "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS["$cycle:admission"]}")" ||
      return $?
    if [[ -z "$baseline_receiver_instance_id" ]]; then
      baseline_receiver_instance_id="$receiver_instance_id"
    else
      [[ "$receiver_instance_id" == "$baseline_receiver_instance_id" &&
        "$reset_generation" == "$((previous_reset_generation + 1))" ]] || return 1
    fi
    previous_reset_generation="$reset_generation"
    observed_private_identity="$(jq -cS '.identity' "$manifest")" || return $?
    observed_map_id="$(jq -er '.map.map_id' "$manifest")" || return $?
    if [[ -z "$baseline_private_identity" ]]; then
      baseline_private_identity="$observed_private_identity"
      baseline_map_id="$observed_map_id"
    else
      [[ "$observed_private_identity" == "$baseline_private_identity" &&
        "$observed_map_id" == "$baseline_map_id" ]] || return 1
    fi
    if ((cycle == BENCHMARK_PRESSURE_CYCLE_COUNT)); then
      final_recovery="$(jq -cS '.recovery' "$manifest")" || return $?
    fi
    observed_cycle_dir_identity="$(stat -Lc '%d:%i:%u:%a' -- \
      "$cycle_dir")" || return $?
    cycle_manifest_original="${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_PATHS[$cycle]}"
    observed_cycle_manifest_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
      "$cycle_manifest_original")" || return $?
    observed_sha256="$(sha256sum -- "$cycle_manifest_original")" || return $?
    observed_sha256="${observed_sha256%% *}"
    observed_snapshot_sha256="$(sha256sum -- "$manifest")" || return $?
    observed_snapshot_sha256="${observed_snapshot_sha256%% *}"
    [[ ! -L "$cycle_manifest_path" && -f "$cycle_manifest_path" &&
      ! -L "$lexical_cycle_manifest_path" &&
      -f "$lexical_cycle_manifest_path" &&
      "$observed_cycle_dir_identity" == "$cycle_dir_identity" &&
      "$private_root/cycle-$tag" -ef "$cycle_dir" &&
      "$observed_cycle_manifest_identity" == "$cycle_manifest_identity" &&
      "$observed_sha256" == "${aggregate_manifest_sha256s[$cycle]}" &&
      "$observed_snapshot_sha256" == \
        "${aggregate_manifest_sha256s[$cycle]}" &&
      "$cycle_manifest_path" -ef "$cycle_manifest_original" &&
      "$lexical_cycle_manifest_path" -ef "$cycle_manifest_original" ]] ||
      return 1
  done
  [[ -n "$final_recovery" ]] || return 1
  jq -e --argjson recovery "$final_recovery" \
    '.recovery == $recovery' "$aggregate" >/dev/null || return $?
  for ((cycle = 1; cycle <= BENCHMARK_PRESSURE_CYCLE_COUNT; cycle++)); do
    printf -v tag '%02d' "$cycle"
    cycle_dir="${aggregate_cycle_dirs[$cycle]}"
    manifest="${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_PATHS[$cycle]}"
    cycle_manifest_original="${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_PATHS[$cycle]}"
    cycle_manifest_path="$cycle_dir/private-manifest.json"
    lexical_cycle_manifest_path="$private_root_lexical/cycle-$tag/private-manifest.json"
    [[ ! -L "$cycle_manifest_path" && -f "$cycle_manifest_path" &&
      ! -L "$lexical_cycle_manifest_path" &&
      -f "$lexical_cycle_manifest_path" ]] || return 1
    observed_cycle_dir_identity="$(stat -Lc '%d:%i:%u:%a' -- \
      "$cycle_dir")" || return $?
    observed_cycle_manifest_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
      "$cycle_manifest_original")" || return $?
    observed_sha256="$(sha256sum -- "$cycle_manifest_original")" || return $?
    observed_sha256="${observed_sha256%% *}"
    observed_snapshot_sha256="$(sha256sum -- "$manifest")" || return $?
    observed_snapshot_sha256="${observed_snapshot_sha256%% *}"
    [[ ! -L "$cycle_manifest_path" && -f "$cycle_manifest_path" &&
      ! -L "$lexical_cycle_manifest_path" &&
      -f "$lexical_cycle_manifest_path" &&
      "$observed_cycle_dir_identity" == \
        "${aggregate_cycle_dir_identities[$cycle]}" &&
      "$private_root/cycle-$tag" -ef "$cycle_dir" &&
      "$observed_cycle_manifest_identity" == \
        "${aggregate_manifest_identities[$cycle]}" &&
      "$observed_sha256" == "${aggregate_manifest_sha256s[$cycle]}" &&
      "$observed_snapshot_sha256" == \
        "${aggregate_manifest_sha256s[$cycle]}" &&
      "$cycle_manifest_path" -ef "$cycle_manifest_original" &&
      "$lexical_cycle_manifest_path" -ef "$cycle_manifest_original" ]] ||
      return 1
    expected_count="$(jq -er '.files | length' "$manifest")" || return $?
    benchmark_pressure_cycle_directory_roster_matches \
      "$manifest" "$expected_count" "$cycle_dir" private-manifest.json || return $?
    observed_cycle_manifest_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
      "$cycle_manifest_original")" || return $?
    observed_sha256="$(sha256sum -- "$cycle_manifest_original")" || return $?
    observed_sha256="${observed_sha256%% *}"
    [[ ! -L "$cycle_manifest_path" && -f "$cycle_manifest_path" &&
      ! -L "$lexical_cycle_manifest_path" &&
      -f "$lexical_cycle_manifest_path" &&
      "$observed_cycle_manifest_identity" == \
        "${aggregate_manifest_identities[$cycle]}" &&
      "$observed_sha256" == "${aggregate_manifest_sha256s[$cycle]}" &&
      "$cycle_manifest_path" -ef "$cycle_manifest_original" &&
      "$lexical_cycle_manifest_path" -ef "$cycle_manifest_original" ]] ||
      return 1
  done
  for leaf_key in "${!BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS[@]}"; do
    cycle="${leaf_key%%:*}"
    printf -v tag '%02d' "$cycle"
    leaf_path="${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS[$leaf_key]}"
    leaf_original_path="${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_ORIGINAL_PATHS[$leaf_key]}"
    cycle_dir="${aggregate_cycle_dirs[$cycle]}"
    name="${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_NAMES[$leaf_key]}"
    lexical_leaf_path="$private_root_lexical/cycle-$tag/$name"
    [[ ! -L "$cycle_dir/$name" && -f "$cycle_dir/$name" &&
      ! -L "$lexical_leaf_path" && -f "$lexical_leaf_path" ]] || return 1
    leaf_identity="$(stat -Lc '%d:%i:%u:%a:%h:%s' -- \
      "$leaf_original_path")" ||
      return $?
    leaf_sha256="$(sha256sum -- "$leaf_original_path")" || return $?
    leaf_sha256="${leaf_sha256%% *}"
    observed_snapshot_sha256="$(sha256sum -- "$leaf_path")" || return $?
    observed_snapshot_sha256="${observed_snapshot_sha256%% *}"
    [[ ! -L "$cycle_dir/$name" && -f "$cycle_dir/$name" &&
      ! -L "$lexical_leaf_path" && -f "$lexical_leaf_path" &&
      "$leaf_identity" == \
        "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_IDENTITIES[$leaf_key]}" &&
      "$leaf_sha256" == \
        "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_SHA256S[$leaf_key]}" &&
      "$observed_snapshot_sha256" == \
        "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_SHA256S[$leaf_key]}" &&
      "$cycle_dir/$name" -ef "$leaf_original_path" &&
      "$lexical_leaf_path" -ef "$leaf_original_path" ]] || return 1
  done
  benchmark_pressure_bounded_directory_roster \
    "$private_root" observed_private_entries || return $?
  observed_private_root_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$private_root")" || return $?
  lexical_private_root_identity="$(stat -Lc '%d:%i:%u:%a' -- \
    "$private_root_lexical")" || return $?
  observed_aggregate_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- \
    "$aggregate_original")" || return $?
  observed_aggregate_sha256="$(sha256sum -- "$aggregate_original")" || return $?
  observed_aggregate_sha256="${observed_aggregate_sha256%% *}"
  aggregate_snapshot_terminal_sha256="$(sha256sum -- "$aggregate")" || return $?
  aggregate_snapshot_terminal_sha256="${aggregate_snapshot_terminal_sha256%% *}"
  lexical_aggregate_identity="$(stat -Lc '%d:%i:%u:%a:%h' -- \
    "$aggregate_input")" || return $?
  benchmark_pressure_trusted_regular_path "$aggregate_input" || return $?
  [[ "$observed_private_entries" == "$expected_private_entries" &&
    "$observed_private_root_identity" == "$private_root_identity" &&
    "$lexical_private_root_identity" == "$private_root_identity" &&
    "$private_root_lexical" -ef "$private_root" &&
    "$observed_aggregate_identity" == "$aggregate_identity" &&
    "$observed_aggregate_sha256" == "$aggregate_sha256" &&
    "$aggregate_snapshot_terminal_sha256" == "$aggregate_sha256" &&
    "$lexical_aggregate_identity" == "$aggregate_identity" &&
    "$aggregate_input" -ef "$aggregate_original" ]] || return 1

  # One broker pass is the campaign-wide linearization point.  The root and
  # every cycle roster are exact; every public leaf is opened relative to its
  # retained directory with O_NOFOLLOW and bound to the original held inode.
  # A descriptor-only aggregate is admitted only as the exact retained regular
  # image supplied by the publication validator.
  printf -v coherent_specification '%sP\t0\t%s\t%s\t%s\texact\n' \
    "$coherent_specification" "$private_root_fd" "$private_root_lexical" \
    "$private_root_identity"
  for ((cycle = 1; cycle <= BENCHMARK_PRESSURE_CYCLE_COUNT; cycle++)); do
    printf -v tag '%02d' "$cycle"
    printf -v coherent_specification '%sD\t0\tcycle-%s\t%s\t%s\n' \
      "$coherent_specification" "$tag" \
      "${aggregate_cycle_dir_fds[$cycle]}" \
      "${aggregate_cycle_dir_identities[$cycle]}"
    printf -v coherent_specification '%sP\t%s\t%s\t%s\t%s\texact\n' \
      "$coherent_specification" "$cycle" \
      "${aggregate_cycle_dir_fds[$cycle]}" \
      "$private_root_lexical/cycle-$tag" \
      "${aggregate_cycle_dir_identities[$cycle]}"
    printf -v coherent_specification '%sF\t%s\t%s\t%s\t%s\t%s\n' \
      "$coherent_specification" "$cycle" private-manifest.json \
      "${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_ORIGINAL_FDS[$cycle]}" \
      "${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_IDENTITIES[$cycle]}" \
      "${BENCHMARK_PRESSURE_CAMPAIGN_MANIFEST_SHA256S[$cycle]}"
  done
  for leaf_key in "${!BENCHMARK_PRESSURE_CAMPAIGN_LEAF_PATHS[@]}"; do
    cycle="${leaf_key%%:*}"
    printf -v coherent_specification '%sF\t%s\t%s\t%s\t%s\t%s\n' \
      "$coherent_specification" "$cycle" \
      "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_NAMES[$leaf_key]}" \
      "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_ORIGINAL_FDS[$leaf_key]}" \
      "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_IDENTITIES[$leaf_key]}" \
      "${BENCHMARK_PRESSURE_CAMPAIGN_LEAF_SHA256S[$leaf_key]}"
  done
  if [[ "$aggregate_is_exact_descriptor" == true ]]; then
    printf -v coherent_specification '%sX\t%s\t%s\t%s\n' \
      "$coherent_specification" "$aggregate_fd" "$aggregate_source_identity" \
      "$aggregate_sha256"
  else
    printf -v coherent_specification '%sP\t11\t%s\t%s\t%s\trelevant\n' \
      "$coherent_specification" "$aggregate_parent_fd" "$aggregate_parent" \
      "$aggregate_parent_identity"
    printf -v coherent_specification '%sF\t11\t%s\t%s\t%s\t%s\n' \
      "$coherent_specification" "$aggregate_leaf" "$aggregate_fd" \
      "$aggregate_source_identity" "$aggregate_sha256"
  fi
  benchmark_pressure_coherent_file_set verify "$coherent_specification"
)

publish_benchmark_pressure_aggregate() {
  local -r cycles_json="$1"
  local -r recovery_json="$2"
  local -r private_root="$3"
  local target="$RESULT_DIR/benchmark-pressure-cycles.json"
  local candidate=""

  [[ ! -e "$target" && ! -L "$target" ]] || return 1
  candidate="$(mktemp "$RESULT_DIR/.benchmark-pressure-cycles.XXXXXX")" || return $?
  jq -cS -n \
    --argjson cycle_count "$BENCHMARK_PRESSURE_CYCLE_COUNT" \
    --argjson load_seconds "$BENCHMARK_PRESSURE_LOAD_SECONDS" \
    --argjson idle_seconds "$BENCHMARK_PRESSURE_IDLE_SECONDS" \
    --argjson cycles "$cycles_json" \
    --argjson recovery "$recovery_json" '
      {schema:"obi-benchmark-pressure-cycles-v2",status:"non_acceptance",
       acceptance_eligible:false,evidence_class:"targeted_pressure_cycle_campaign",
       cycle_count:$cycle_count,load_seconds_per_cycle:$load_seconds,
       idle_seconds_per_cycle:$idle_seconds,histograms:"linked_not_pooled",
       cycles:$cycles,recovery:$recovery}
    ' >"$candidate" || return $?
  chmod 0644 -- "$candidate" || return $?
  benchmark_pressure_publish_validated_file \
    "$candidate" "$target" 644 \
    validate_benchmark_pressure_aggregate "$private_root"
}

run_benchmark_pressure_cycles() {
  local private_root="$RESULT_DIR/benchmark-pressure-cycles-raw"
  local aggregate_cycles='[]'
  local aggregate_recovery='null'
  local baseline_stack=""
  local current_stack=""
  local cycle_dir=""
  local label=""
  local tag=""
  local candidate=""
  local cycle_deadline=0
  local cleanup_deadline=0
  local cycle=0
  local prepare_tick=""
  local capacity_tick=""
  local load_start_tick=""
  local load_finish_tick=""
  local release_tick=""
  local verify_tick=""
  local cleanup_tick=""
  local idle_start_tick=""
  local idle_finish_tick=""
  local baseline_resource_tick=""
  local postload_resource_tick=""
  local attribution_tick=""
  local postidle_resource_tick=""
  local idle_elapsed_centiseconds=""
  local phases='[]'
  local phase=""
  local phase_name=""
  local phase_tick=""
  local digest=""
  local fill_digest=""
  local benchmark_digest=""
  local verify_digest=""
  local cleanup_digest=""
  local idle_before_digest=""
  local idle_after_digest=""
  local baseline_resource_digest=""
  local postload_resource_digest=""
  local admission_digest=""
  local postidle_resource_digest=""
  local stack_digest=""
  local ready_digest=""
  local release_digest=""
  local committed_result=""
  local committed_stderr=""
  local committed_receipt=""
  local manifest_digest=""
  local manifest_size=""
  local manifest_count=""
  local barrier_digest=""
  local result_digest=""
  local successful_requests=""
  local traffic_elapsed_nanos=""
  local recovery_one_digest=""
  local recovery_two_digest=""
  local recovery_one_tick=""
  local recovery_two_tick=""
  local public_cycle=""
  local observed_cycle_count=""
  local source=""
  local target=""
  local -a copy_sources=()
  local -a copy_targets=()
  local copy_index=0

  [[ "$SCENARIO" == benchmark-pressure-cycles && "$TRANSPORT" == getsockopt &&
    "$SELECTED_TRANSPORT" == getsockopt && "$OBI_RUNNING" == true &&
    "$BRIDGE_RUNNING" == true && "$BENCHMARK_PRESSURE_CYCLE_COUNT" == 10 &&
    "$BENCHMARK_PRESSURE_LOAD_SECONDS" == 60 &&
    "$BENCHMARK_PRESSURE_IDLE_SECONDS" == 30 &&
    "$BENCHMARK_PRESSURE_RECOVERY_SAMPLES" == 2 &&
    ! -e "$private_root" && ! -L "$private_root" ]] || return 1
  if ! benchmark_pressure_broker_executables_are_authenticated \
    >/dev/null; then
    log_error "benchmark pressure evidence brokers require authenticated system executables"
    return 1
  fi
  (umask 077; mkdir -m 0700 -- "$private_root") || return $?
  [[ "$(stat -Lc '%u:%a' -- "$private_root")" == "$EUID:700" ]] ||
    return 1
  baseline_stack="$(benchmark_pressure_stack_identity_json)" || return $?

  for ((cycle = 1; cycle <= BENCHMARK_PRESSURE_CYCLE_COUNT; cycle++)); do
    printf -v tag '%02d' "$cycle"
    label="pressure-run-$tag"
    cycle_dir="$private_root/cycle-$tag"
    [[ ! -e "$cycle_dir" && ! -L "$cycle_dir" ]] || return 1
    (umask 077; mkdir -m 0700 -- "$cycle_dir") || return $?
    [[ "$(stat -Lc '%u:%a' -- "$cycle_dir")" == "$EUID:700" ]] ||
      return 1
    RUN_STAGE="benchmark-pressure-cycle-$tag-identity"
    current_stack="$(benchmark_pressure_stack_identity_json)" || return $?
    [[ "$current_stack" == "$baseline_stack" ]] || {
      log_error "benchmark pressure stack identity drifted before cycle $tag"
      return 1
    }
    candidate="$(mktemp "$cycle_dir/.stack-identity.XXXXXX")" || return $?
    printf '%s\n' "$current_stack" >"$candidate" || return $?
    chmod 0600 -- "$candidate" || return $?
    benchmark_pressure_publish_validated_file \
      "$candidate" "$cycle_dir/stack-identity.json" 600 \
      validate_benchmark_pressure_stack_identity_file || return $?
    stack_digest="$(sha256sum -- "$cycle_dir/stack-identity.json")" || return $?
    stack_digest="${stack_digest%% *}"

    RUN_STAGE="benchmark-pressure-cycle-$tag-baseline"
    fetch_obi_metrics "$cycle_dir/map-baseline.prom" 5 || return $?
    chmod 0600 -- "$cycle_dir/map-baseline.prom" || return $?
    capture_benchmark_pressure_resources \
      "$cycle_dir/stack-identity.json" \
      "$cycle_dir/resources-baseline.json" || return $?
    baseline_resource_tick="$(jq -er \
      '.captured_monotonic_centiseconds' \
      "$cycle_dir/resources-baseline.json")" || return $?
    [[ "$baseline_resource_tick" =~ ^[0-9]+$ ]] || return 1
    prepare_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    cycle_deadline="$((SECONDS + BENCHMARK_PRESSURE_CONTROL_DEADLINE_SECONDS))"
    prepare_pressure_control_runtime \
      "$cycle_deadline" "$((SECONDS + PRESSURE_CONTROL_READY_TIMEOUT_SECONDS))" ||
      return $?
    start_map_pressure "$label" "$cycle_dir/map-baseline.prom" || return $?
    publish_benchmark_pressure_control_file \
      "$PRESSURE_CONTROL_READY_FILE" \
      "$RESULT_DIR/map-pressure-$label-fill.json" || return $?
    capacity_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    ready_digest="$(sha256_file \
      "$PRESSURE_CONTROL_LIVE_DIR/$PRESSURE_CONTROL_READY_FILE" \
      "$PRESSURE_CONTROL_DEADLINE")" || return $?
    prepare_benchmark_pressure_attribution "$cycle" "$cycle_dir" || return $?

    RUN_STAGE="benchmark-pressure-cycle-$tag-load"
    load_start_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    run_benchmark_pressure_client "$cycle" "$cycle_dir" || return $?
    load_finish_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    publish_benchmark_pressure_control_file \
      "$PRESSURE_CONTROL_RELEASE_FILE" "$cycle_dir/benchmark-result.json" \
      "$cycle" ||
      return $?
    release_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    release_digest="$(sha256_file \
      "$PRESSURE_CONTROL_LIVE_DIR/$PRESSURE_CONTROL_RELEASE_FILE" \
      "$PRESSURE_CONTROL_DEADLINE")" || return $?
    verify_map_pressure_after_traffic "$label" || return $?
    verify_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    copy_sources=(
      "$RESULT_DIR/map-pressure-$label-prepare.json"
      "$RESULT_DIR/map-pressure-$label-fill.json"
      "$RESULT_DIR/map-pressure-$label-verify.json"
    )
    copy_targets=(
      "$cycle_dir/map-prepare.json"
      "$cycle_dir/map-fill.json"
      "$cycle_dir/map-verify.json"
    )
    for ((copy_index = 0; copy_index < ${#copy_sources[@]}; copy_index++)); do
      benchmark_pressure_copy_private_evidence \
        "${copy_sources[$copy_index]}" "${copy_targets[$copy_index]}" || return $?
    done
    write_benchmark_pressure_barrier_receipt "$cycle" "$cycle_dir" || return $?
    current_stack="$(benchmark_pressure_stack_identity_json)" || return $?
    [[ "$current_stack" == "$baseline_stack" ]] || {
      log_error "benchmark pressure stack identity drifted after load $tag"
      return 1
    }
    capture_benchmark_pressure_resources \
      "$cycle_dir/stack-identity.json" \
      "$cycle_dir/resources-postload.json" || return $?
    postload_resource_tick="$(jq -er \
      '.captured_monotonic_centiseconds' \
      "$cycle_dir/resources-postload.json")" || return $?
    [[ "$postload_resource_tick" =~ ^[0-9]+$ ]] || return 1
    finish_benchmark_pressure_attribution "$cycle" "$cycle_dir" "$label" ||
      return $?
    attribution_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    admission_digest="$(sha256sum -- "$cycle_dir/admission-receipt.json")" ||
      return $?
    admission_digest="${admission_digest%% *}"

    RUN_STAGE="benchmark-pressure-cycle-$tag-cleanup"
    cleanup_deadline="$((SECONDS + PRESSURE_RUNTIME_CLEANUP_DEADLINE_SECONDS))"
    cleanup_pressure_scenario_runtime_with_retries "$cleanup_deadline" || return $?
    [[ "$PRESSURE_BARRIER_RUNTIME_STATUS" == failed &&
      "$PRESSURE_ACTIVE" == true && -z "$PRESSURE_CONTROL_LIVE_DIR" ]] ||
      return 1
    cleanup_map_pressure_with_retries || return $?
    [[ "$PRESSURE_ACTIVE" == false &&
      "$PRESSURE_BARRIER_RUNTIME_STATUS" == not-run ]] || return 1
    cleanup_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?

    copy_sources=(
      "$RESULT_DIR/map-pressure-$label-cleanup.json"
      "$RESULT_DIR/map-pressure-$label-recovered.prom"
    )
    copy_targets=(
      "$cycle_dir/map-cleanup.json"
      "$cycle_dir/map-recovered.prom"
    )
    for ((copy_index = 0; copy_index < ${#copy_sources[@]}; copy_index++)); do
      benchmark_pressure_copy_private_evidence \
        "${copy_sources[$copy_index]}" "${copy_targets[$copy_index]}" || return $?
    done

    RUN_STAGE="benchmark-pressure-cycle-$tag-idle"
    fetch_obi_metrics "$cycle_dir/idle-before.prom" 5 || return $?
    chmod 0600 -- "$cycle_dir/idle-before.prom" || return $?
    pressure_map_state_snapshot_matches recovered \
      "$cycle_dir/idle-before.prom" "$((SECONDS + 10))" || return $?
    idle_start_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    sleep "$BENCHMARK_PRESSURE_IDLE_SECONDS" || return $?
    idle_finish_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
    idle_elapsed_centiseconds="$((idle_finish_tick - idle_start_tick))"
    ((idle_elapsed_centiseconds >= BENCHMARK_PRESSURE_IDLE_SECONDS * 100 &&
      idle_elapsed_centiseconds < (BENCHMARK_PRESSURE_IDLE_SECONDS + 1) * 100)) ||
      return 1
    fetch_obi_metrics "$cycle_dir/idle-after.prom" 5 || return $?
    chmod 0600 -- "$cycle_dir/idle-after.prom" || return $?
    pressure_map_state_snapshot_matches recovered \
      "$cycle_dir/idle-after.prom" "$((SECONDS + 10))" || return $?
    if ((cycle == BENCHMARK_PRESSURE_CYCLE_COUNT)); then
      # No application traffic or resource probe may occur between these two
      # final post-idle samples; each independently resolves the same map ID.
      fetch_obi_metrics "$cycle_dir/recovery-01.prom" 5 || return $?
      chmod 0600 -- "$cycle_dir/recovery-01.prom" || return $?
      pressure_map_state_snapshot_matches recovered \
        "$cycle_dir/recovery-01.prom" "$((SECONDS + 10))" || return $?
      recovery_one_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
      fetch_obi_metrics "$cycle_dir/recovery-02.prom" 5 || return $?
      chmod 0600 -- "$cycle_dir/recovery-02.prom" || return $?
      pressure_map_state_snapshot_matches recovered \
        "$cycle_dir/recovery-02.prom" "$((SECONDS + 10))" || return $?
      recovery_two_tick="$(benchmark_pressure_monotonic_centiseconds)" || return $?
      [[ "$recovery_one_tick" =~ ^[0-9]+$ &&
        "$recovery_two_tick" =~ ^[0-9]+$ &&
        "$recovery_one_tick" -le "$recovery_two_tick" ]] || return 1
    fi

    RUN_STAGE="benchmark-pressure-cycle-$tag-capture"
    current_stack="$(benchmark_pressure_stack_identity_json)" || return $?
    [[ "$current_stack" == "$baseline_stack" ]] || {
      log_error "benchmark pressure stack identity drifted during cycle $tag"
      return 1
    }
    capture_benchmark_pressure_resources \
      "$cycle_dir/stack-identity.json" \
      "$cycle_dir/resources-postidle.json" || return $?
    postidle_resource_tick="$(jq -er \
      '.captured_monotonic_centiseconds' \
      "$cycle_dir/resources-postidle.json")" || return $?
    [[ "$postidle_resource_tick" =~ ^[0-9]+$ ]] || return 1

    fill_digest="$(sha256sum -- "$cycle_dir/map-fill.json")" || return $?
    fill_digest="${fill_digest%% *}"
    benchmark_pressure_client_bundle_images_for_consumer \
      "$cycle_dir/benchmark-result.json" "$cycle" committed_result \
      committed_stderr committed_receipt || return $?
    benchmark_digest="$(sha256sum -- "$committed_result")" || return $?
    benchmark_digest="${benchmark_digest%% *}"
    verify_digest="$(sha256sum -- "$cycle_dir/map-verify.json")" || return $?
    verify_digest="${verify_digest%% *}"
    cleanup_digest="$(sha256sum -- "$cycle_dir/map-cleanup.json")" || return $?
    cleanup_digest="${cleanup_digest%% *}"
    idle_before_digest="$(sha256sum -- "$cycle_dir/idle-before.prom")" || return $?
    idle_before_digest="${idle_before_digest%% *}"
    idle_after_digest="$(sha256sum -- "$cycle_dir/idle-after.prom")" || return $?
    idle_after_digest="${idle_after_digest%% *}"
    baseline_resource_digest="$(sha256sum -- \
      "$cycle_dir/resources-baseline.json")" || return $?
    baseline_resource_digest="${baseline_resource_digest%% *}"
    postload_resource_digest="$(sha256sum -- \
      "$cycle_dir/resources-postload.json")" || return $?
    postload_resource_digest="${postload_resource_digest%% *}"
    postidle_resource_digest="$(sha256sum -- \
      "$cycle_dir/resources-postidle.json")" || return $?
    postidle_resource_digest="${postidle_resource_digest%% *}"

    phases='[]'
    for source in \
      "baseline_resources_captured|$baseline_resource_tick|$baseline_resource_digest" \
      "prepare_started|$prepare_tick|$stack_digest" \
      "capacity_ready|$capacity_tick|$fill_digest" \
      "load_started|$load_start_tick|$ready_digest" \
      "load_finished|$load_finish_tick|$benchmark_digest" \
      "release_published|$release_tick|$release_digest" \
      "content_verified|$verify_tick|$verify_digest" \
      "postload_resources_captured|$postload_resource_tick|$postload_resource_digest" \
      "attribution_reconciled|$attribution_tick|$admission_digest" \
      "cleanup_absent|$cleanup_tick|$cleanup_digest" \
      "idle_started|$idle_start_tick|$idle_before_digest" \
      "idle_finished|$idle_finish_tick|$idle_after_digest" \
      "postidle_resources_captured|$postidle_resource_tick|$postidle_resource_digest"; do
      IFS='|' read -r phase_name phase_tick digest <<<"$source"
      [[ "$phase_name" =~ ^[a-z_]+$ && "$phase_tick" =~ ^[0-9]+$ &&
        "$digest" =~ ^[0-9a-f]{64}$ ]] || return 1
      phase="$(jq -cS -n --arg name "$phase_name" \
        --argjson monotonic_centiseconds "$phase_tick" \
        --arg evidence_sha256 "$digest" \
        '{name:$name,monotonic_centiseconds:$monotonic_centiseconds,
          evidence_sha256:$evidence_sha256}')" || return $?
      phases="$(jq -cS --argjson phase "$phase" '. + [$phase]' <<<"$phases")" ||
        return $?
    done
    write_benchmark_pressure_private_manifest \
      "$cycle" "$cycle_dir" "$phases" "$idle_elapsed_centiseconds" \
      "$recovery_one_tick" "$recovery_two_tick" || return $?

    manifest_digest="$(sha256sum -- "$cycle_dir/private-manifest.json")" || return $?
    manifest_digest="${manifest_digest%% *}"
    manifest_size="$(stat -Lc '%s' -- "$cycle_dir/private-manifest.json")" || return $?
    manifest_count="$(jq -er '.files | length' \
      "$cycle_dir/private-manifest.json")" || return $?
    barrier_digest="$(jq -er '.files[] | select(.role == "barrier") | .sha256' \
      "$cycle_dir/private-manifest.json")" || return $?
    result_digest="$(jq -er '.files[] | select(.role == "benchmark") | .sha256' \
      "$cycle_dir/private-manifest.json")" || return $?
    successful_requests="$(jq -er '.load.successful_requests' \
      "$cycle_dir/private-manifest.json")" || return $?
    traffic_elapsed_nanos="$(jq -er '.load.traffic_elapsed_nanos' \
      "$cycle_dir/private-manifest.json")" || return $?
    public_cycle="$(jq -cS -n \
      --argjson cycle "$cycle" \
      --argjson load_requested_seconds "$BENCHMARK_PRESSURE_LOAD_SECONDS" \
      --argjson load_elapsed_nanos "$traffic_elapsed_nanos" \
      --argjson idle_requested_seconds "$BENCHMARK_PRESSURE_IDLE_SECONDS" \
      --argjson idle_elapsed_centiseconds "$idle_elapsed_centiseconds" \
      --argjson successful_requests "$successful_requests" \
      --arg histogram_encoding "$BENCHMARK_PRESSURE_HISTOGRAM_ENCODING" \
      --arg private_manifest_sha256 "$manifest_digest" \
      --argjson private_manifest_bytes "$manifest_size" \
      --argjson private_file_count "$manifest_count" \
      --arg barrier_receipt_sha256 "$barrier_digest" \
      --arg admission_receipt_sha256 "$admission_digest" \
      --arg rle_result_sha256 "$result_digest" \
      --arg stack_identity_sha256 "$stack_digest" '
        {cycle:$cycle,status:"passed",
         load_requested_seconds:$load_requested_seconds,
         load_elapsed_nanos:$load_elapsed_nanos,
         idle_requested_seconds:$idle_requested_seconds,
         idle_elapsed_centiseconds:$idle_elapsed_centiseconds,
         successful_requests:$successful_requests,
         histogram_encoding:$histogram_encoding,
         private_manifest_sha256:$private_manifest_sha256,
         private_manifest_bytes:$private_manifest_bytes,
         private_file_count:$private_file_count,
         admission_receipt_sha256:$admission_receipt_sha256,
         unexpected_evictions:0,
         barrier_receipt_sha256:$barrier_receipt_sha256,
         rle_result_sha256:$rle_result_sha256,
         stack_identity_sha256:$stack_identity_sha256}
      ')" || return $?
    aggregate_cycles="$(jq -cS --argjson cycle "$public_cycle" \
      '. + [$cycle]' <<<"$aggregate_cycles")" || return $?
    if ((cycle == BENCHMARK_PRESSURE_CYCLE_COUNT)); then
      recovery_one_digest="$(sha256sum -- "$cycle_dir/recovery-01.prom")" || return $?
      recovery_one_digest="${recovery_one_digest%% *}"
      recovery_two_digest="$(sha256sum -- "$cycle_dir/recovery-02.prom")" || return $?
      recovery_two_digest="${recovery_two_digest%% *}"
      aggregate_recovery="$(jq -cS -n \
        --arg first "$recovery_one_digest" --arg second "$recovery_two_digest" \
        --argjson first_tick "$recovery_one_tick" \
        --argjson second_tick "$recovery_two_tick" \
        --argjson required_samples "$BENCHMARK_PRESSURE_RECOVERY_SAMPLES" '
          {required_samples:$required_samples,consecutive:true,map_entries:[0,0],
           captured_monotonic_centiseconds:[$first_tick,$second_tick],
           sample_sha256s:[$first,$second]}
        ')" || return $?
    fi
  done
  observed_cycle_count="$(jq -er 'length' <<<"$aggregate_cycles")" || return $?
  [[ "$observed_cycle_count" == "$BENCHMARK_PRESSURE_CYCLE_COUNT" &&
    "$aggregate_recovery" != null ]] ||
    return 1
  RUN_STAGE="benchmark-pressure-cycles-aggregate"
  publish_benchmark_pressure_aggregate \
    "$aggregate_cycles" "$aggregate_recovery" "$private_root"
}

run_scenario() {
  local -r name="$1"
  local -r diagnostics_enabled="${2:-true}"
  local -r phase_evidence="${3:-full}"
  local -r fixture_mode="${4:-none}"
  local -r retrieval_mode="${5:-normal}"
  local -r assertion_mode="${6:-}"
  local run_number=0
  local label=""
  local output=""
  local stderr_output=""
  local before_phase=""
  local after_phase=""
  local before_diagnostics=""
  local after_diagnostics=""
  local before_stage=0
  local before_success=0
  local expected_stage=0
  local expected_success=0
  local expected_requests=0
  local expected_sampled=0
  local expected_unsampled=0
  local expected_standard=0
  local expected_valid=0
  local expected_stale=0
  local expected_malformed=0
  local baseline_bridge_missing=0
  local baseline_java_missing=0
  local expected_bridge_valid=0
  local expected_bridge_lifecycle=0
  local expected_bridge_stage=0
  local expected_bridge_missing=0
  local expected_bridge_stale=0
  local expected_bridge_handoffs=0
  local include_ambiguous_candidates=false
  local expected_java_missing=0
  local pressure_hits=0
  local pressure_roots=0
  local pressure_w3c=0
  local pressure_wrong=0
  local pressure_unresolved=0
  local pressure_bridge_valid=0
  local pressure_bridge_failures=0
  local pressure_w3c_masked_valid=0
  local pressure_runtime_quiesced=false
  local pressure_traffic_completed=false
  local pressure_evidence_cleanup_deadline=0
  local pressure_evidence_work_deadline=0
  local pressure_trace_json="null"
  local pressure_bridge_json="null"
  local pressure_java_json="null"
  local pressure_container_inspections_descriptor_json="null"
  local pressure_container_inspections_container_json="null"
  local pressure_inspections_cleanup_deadline=0
  local pressure_inspections_work_deadline=0
  local pressure_status_json="null"
  local scenario_reconciliation_json="null"
  local receive_cursor_map_status_json="null"
  local pressure_unix_already_consumed_reconciled=false
  local coalesced_outcome=""
  local timeout_parent_outcome=""
  local timeout_drop_reason=""
  local diagnostic_valid_takes=0
  local expected_fault_status=""
  local expected_fault_count=0
  local fault_diagnostics_after=""
  local fault_diagnostics_delta=""
  local before_diagnostics_status_json="null"
  local after_diagnostics_status_json="null"
  local obi_metric_evidence_json="null"
  local obi_metric_pair_reference=""
  local obi_metric_boundary_id=""
  local obi_metric_boundary_ids_json="[]"
  local owns_obi_metric_boundary=false
  local bridge_was_running=false
  local obi_was_running=false
  local controlled_bridge_was_running=false
  local fixture_status=0
  local scenario_status=0
  local metric_status=0
  local status_name="passed"
  local -a request_arguments=()
  local -a scenario_arguments=()

  [[ "$diagnostics_enabled" == "true" || "$diagnostics_enabled" == "false" ]] || {
    log_error "scenario diagnostics mode must be true or false"
    return 1
  }
  [[ "$phase_evidence" == "full" || "$phase_evidence" == "metrics" ]] || {
    log_error "scenario phase evidence must be full or metrics"
    return 1
  }
  [[ "$fixture_mode" == "none" || "$fixture_mode" == "matching" ]] || {
    log_error "scenario fixture mode must be none or matching"
    return 1
  }
  [[ "$retrieval_mode" == "normal" || "$retrieval_mode" == "helper-unavailable" ]] || {
    log_error "scenario retrieval mode must be normal or helper-unavailable"
    return 1
  }
  [[ -z "$assertion_mode" || "$assertion_mode" == "disabled" || \
    "$assertion_mode" == "uninstrumented" ]] || {
    log_error "scenario assertion mode must be disabled or uninstrumented"
    return 1
  }
  if [[ -n "$assertion_mode" && "$name" != "concurrency" ]]; then
    log_error "an explicit assertion mode requires the concurrency workload"
    return 1
  fi
  if [[ "$fixture_mode" == "matching" && \
    ( "$name" != "w3c-match" || "$diagnostics_enabled" != "true" ) ]]; then
    log_error "the matching fixture requires the diagnostic w3c-match scenario"
    return 1
  fi
  if [[ "$retrieval_mode" == "helper-unavailable" && \
    ( "$fixture_mode" != "none" || "$diagnostics_enabled" != "false" ||
    ( "$name" != "helper-attach-failure" && "$name" != "w3c" ) ) ]]; then
    log_error "helper-unavailable retrieval requires a non-diagnostic helper-attach-failure or w3c scenario"
    return 1
  fi
  baseline_bridge_missing="$(
    scenario_bridge_missing_count "$name" "$SELECTED_TRANSPORT"
  )" || return $?
  baseline_java_missing="$(
    scenario_java_missing_count "$name" "$diagnostics_enabled"
  )" || return $?
  expected_requests="$(scenario_bridge_take_count "$name")" || return $?
  if [[ "$retrieval_mode" == "helper-unavailable" ]]; then
    expected_requests=1
    request_arguments=(--requests 1)
  elif [[ "$name" == "w3c-fault" ]]; then
    request_arguments=(
      --requests "$FAULT_REQUEST_COUNT"
      --fault-mode "$FAULT_MODE"
    )
  elif [[ "$name" == "tls-boundary" ]]; then
    request_arguments=(--requests 3)
  elif (( REQUEST_COUNT > 0 )); then
    request_arguments=(--requests "$REQUEST_COUNT")
  fi
  for ((run_number = 1; run_number <= REPEAT_COUNT; run_number++)); do
    controlled_bridge_was_running=false
    scenario_status=0
    metric_status=0
    status_name="passed"
    expected_bridge_valid="$expected_requests"
    expected_bridge_lifecycle="$expected_requests"
    expected_bridge_stage="$expected_requests"
    expected_bridge_stale=0
    expected_bridge_handoffs=0
    if [[ "$name" == "tls-boundary" && \
      "$SELECTED_TRANSPORT" == "getsockopt" ]]; then
      expected_bridge_handoffs="$expected_requests"
    fi
    include_ambiguous_candidates=false
    if [[ "$retrieval_mode" == "helper-unavailable" ]]; then
      expected_bridge_valid=0
      expected_bridge_stage=0
      include_ambiguous_candidates=true
    fi
    if is_w3c_stale_scenario "$name"; then
      expected_bridge_valid=0
      expected_bridge_stale="$expected_requests"
    fi
    expected_bridge_missing="$baseline_bridge_missing"
    expected_java_missing="$baseline_java_missing"
    pressure_hits=0
    pressure_roots=0
    pressure_w3c=0
    pressure_wrong=0
    pressure_unresolved=0
    pressure_bridge_valid=0
    pressure_bridge_failures=0
    pressure_w3c_masked_valid=0
    pressure_runtime_quiesced=false
    pressure_traffic_completed=false
    pressure_evidence_cleanup_deadline=0
    pressure_evidence_work_deadline=0
    pressure_trace_json="null"
    pressure_bridge_json="null"
    pressure_java_json="null"
    pressure_container_inspections_descriptor_json="null"
    pressure_container_inspections_container_json="null"
    pressure_inspections_cleanup_deadline=0
    pressure_inspections_work_deadline=0
    pressure_status_json="null"
    scenario_reconciliation_json="null"
    receive_cursor_map_status_json="null"
    pressure_unix_already_consumed_reconciled=false
    coalesced_outcome=""
    timeout_parent_outcome=""
    timeout_drop_reason=""
    diagnostic_valid_takes=0
    before_diagnostics_status_json="null"
    after_diagnostics_status_json="null"
    obi_metric_evidence_json="null"
    obi_metric_pair_reference=""
    label="$name"
    if [[ "$name" == "w3c-fault" ]]; then
      label="$name-$FAULT_MODE"
    fi
    if [[ -n "$SCENARIO_VARIANT" ]]; then
      label="$label-$SCENARIO_VARIANT"
    fi
    if (( REPEAT_COUNT > 1 )); then
      printf -v label '%s-run-%02d' "$label" "$run_number"
    fi
    obi_metric_boundary_id=""
    obi_metric_boundary_ids_json="[]"
    owns_obi_metric_boundary=false
    if obi_metric_boundary_index_is_initialized; then
      if obi_metric_boundary_id="$(active_obi_metric_boundary_id 2>/dev/null)"; then
        :
      else
        obi_metric_boundary_id="$label"
        begin_obi_metric_boundary "$obi_metric_boundary_id" || return $?
        owns_obi_metric_boundary=true
      fi
      obi_metric_boundary_ids_json="$(jq -cn \
        --arg boundary_id "$obi_metric_boundary_id" '[$boundary_id]')" || return 1
      if [[ "$OBI_RUNNING" == true ]]; then
        plan_obi_metric_pair_capture "$label" || return $?
      fi
    fi
    output="$RESULT_DIR/scenario-$label.json"
    stderr_output="$RESULT_DIR/scenario-$label.stderr.log"
    before_phase="$label-before"
    after_phase="$label-after"
    before_diagnostics="$RESULT_DIR/phases/$before_phase/java-diagnostics.txt"
    after_diagnostics="$RESULT_DIR/phases/$after_phase/java-diagnostics.txt"
    if [[ "$OBI_RUNNING" == false ]] &&
      obi_metric_pair_reference="$(
        active_stopped_obi_metric_pair_reference 2>/dev/null
      )" && [[ -n "$obi_metric_pair_reference" ]]; then
      if ! obi_metric_evidence_json="$(
        obi_metric_pair_evidence_json_from_reference "$obi_metric_pair_reference"
      )"; then
        log_error "could not retain the stopped OBI metric boundary in $label status"
        obi_metric_evidence_json="null"
        metric_status=1
      fi
    fi

    log_info "running $label scenario"
    if [[ "$fixture_mode" == "matching" ]]; then
      if start_matching_bridge "$label" "$expected_requests"; then
        controlled_bridge_was_running=true
      else
        fixture_status=$?
        scenario_status="$fixture_status"
      fi
    fi
    if [[ "$retrieval_mode" == "helper-unavailable" ]]; then
      if ! flush_bridge_metric_boundary "$label" 0 0; then
        metric_status=1
      fi
    elif is_w3c_stale_scenario "$name"; then
      if [[ "$diagnostics_enabled" == "true" ]] &&
        ! mkdir -p -- "$RESULT_DIR/phases/$before_phase"; then
        metric_status=1
      elif [[ "$diagnostics_enabled" == "true" ]] &&
        ! flush_bridge_metric_boundary "$label" 0 1 "$before_diagnostics"; then
        metric_status=1
      elif [[ "$diagnostics_enabled" == "false" ]] &&
        ! flush_bridge_metric_boundary "$label" 0 1; then
        metric_status=1
      fi
    elif ! flush_bridge_metric_boundary "$label"; then
      metric_status=1
    fi
    if [[ "$name" != "w3c-fault" && "$diagnostics_enabled" == "true" ]]; then
      if ! is_w3c_stale_scenario "$name" &&
        ! capture_java_diagnostics "$before_phase"; then
        metric_status=1
      fi
      if [[ "$BRIDGE_RUNNING" == "true" ]] &&
        ! wait_for_bridge_metrics_quiescent \
          0 \
          0 \
          "$RESULT_DIR/metrics-diagnostics-$label.prom" \
          "$label pre-scenario diagnostics quiescence"; then
        metric_status=1
      fi
    fi
    if [[ "$phase_evidence" == "metrics" ]]; then
      if ! capture_metric_phase_evidence "$before_phase"; then
        metric_status=1
      fi
    elif ! capture_phase_evidence "$before_phase"; then
      metric_status=1
    fi
    if [[ "$name" == "tls-boundary" || "$name" == "coalesced-bridge" ]] && \
      ! capture_receive_cursor_map_baseline "$label"; then
      metric_status=1
    fi
    bridge_was_running="$BRIDGE_RUNNING"
    obi_was_running="$OBI_RUNNING"
    if [[ "$bridge_was_running" == "true" ]]; then
      before_success="$(bridge_success_total \
        "$RESULT_DIR/phases/$before_phase/obi-metrics.prom")" || return $?
      before_stage="$(bridge_stage_total \
        "$RESULT_DIR/phases/$before_phase/obi-metrics.prom")" || return $?
    fi
    if ((scenario_status == 0)); then
      scenario_arguments=(
        --scenario "$name"
        --expected-tls "$TLS_PROTOCOL"
        --seed "$SCENARIO_SEED"
        "${request_arguments[@]}"
        --timeout "${PRESSURE_TRAFFIC_TIMEOUT_SECONDS}s"
      )
      if scenario_uses_in_band_java_diagnostics "$name"; then
        if assert_sanitized_java_diagnostics "$before_diagnostics"; then
          scenario_arguments+=(
            --java-diagnostics-before "$(<"$before_diagnostics")"
          )
        else
          log_error "$label has no valid Java diagnostics baseline"
          scenario_status=1
        fi
      fi
      if [[ -n "$assertion_mode" ]]; then
        scenario_arguments+=(--assertion-mode "$assertion_mode")
      fi
    fi
    if ((scenario_status == 0)) && [[ "$name" == pressure ]]; then
      if start_pressure_scenario_barrier \
        "$output" "$stderr_output" "${scenario_arguments[@]}"; then
        scenario_status=0
      else
        scenario_status=$?
        if cleanup_pressure_scenario_runtime_with_retries 0; then
          pressure_runtime_quiesced=true
        else
          metric_status=1
        fi
      fi
      if ((scenario_status == 0)); then
        if start_map_pressure \
          "$label" "$RESULT_DIR/phases/$before_phase/obi-metrics.prom"; then
          scenario_status=0
        else
          scenario_status=$?
          if cleanup_pressure_scenario_runtime_with_retries 0; then
            pressure_runtime_quiesced=true
            cleanup_map_pressure_with_retries || metric_status=1
          else
            metric_status=1
          fi
        fi
      fi
      if ((scenario_status == 0)); then
        if publish_pressure_scenario_release \
          "$RESULT_DIR/map-pressure-$label-fill.json"; then
          scenario_status=0
        else
          scenario_status=$?
          if cleanup_pressure_scenario_runtime_with_retries 0; then
            pressure_runtime_quiesced=true
            cleanup_map_pressure_with_retries || metric_status=1
          else
            metric_status=1
          fi
        fi
      fi
      if ((scenario_status == 0)); then
        if wait_for_pressure_scenario_container; then
          pressure_traffic_completed=true
          scenario_status=0
        else
          scenario_status=$?
          if pressure_scenario_terminal_failure_receipt_matches \
            "$scenario_status"; then
            pressure_traffic_completed=true
          fi
          if cleanup_pressure_scenario_runtime_with_retries 0; then
            pressure_runtime_quiesced=true
            cleanup_map_pressure_with_retries || metric_status=1
          else
            metric_status=1
          fi
        fi
      fi
      if ((scenario_status == 0)); then
        if retain_pressure_control_evidence "$label"; then
          if [[ "$PRESSURE_BARRIER_RUNTIME_STATUS" == retained &&
            "$PRESSURE_SCENARIO_REMOVAL_STATUS" == absence-proved &&
            "$PRESSURE_CONTROL_REMOVAL_STATUS" == not-run &&
            -z "$PRESSURE_CONTROL_LIVE_DIR" &&
            -z "$PRESSURE_CONTROL_LIVE_IDENTITY" ]] &&
            pressure_helper_runtime_state_is_empty; then
            pressure_runtime_quiesced=true
            pressure_traffic_completed=true
            scenario_status=0
          else
            log_error "pressure runtime was not quiescent after evidence retention"
            scenario_status=1
            if cleanup_pressure_scenario_runtime_with_retries 0; then
              pressure_runtime_quiesced=true
            else
              metric_status=1
            fi
          fi
        else
          scenario_status=$?
          if cleanup_pressure_scenario_runtime_with_retries 0; then
            pressure_runtime_quiesced=true
            cleanup_map_pressure_with_retries || metric_status=1
          else
            metric_status=1
          fi
        fi
      fi
    elif ((scenario_status == 0)); then
      if run_bounded "$SCENARIO_RUN_TIMEOUT_SECONDS" \
        "${COMPOSE[@]}" run --rm --no-deps --no-TTY scenario \
          "${scenario_arguments[@]}" \
          2> >(tee "$stderr_output" >&2) | tee "$output"; then
        scenario_status=0
      else
        scenario_status=$?
      fi
    fi
    if scenario_uses_in_band_java_diagnostics "$name"; then
      if ! mkdir -p -- "$RESULT_DIR/phases/$after_phase"; then
        metric_status=1
      elif ! extract_java_diagnostics_after "$output" "$after_diagnostics"; then
        log_error "could not extract in-band Java diagnostics for $label"
        metric_status=1
      elif ! write_java_diagnostics_delta \
        "$before_diagnostics" \
        "$after_diagnostics" \
        "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta"; then
        log_error "could not compute in-band Java diagnostics for $label"
        metric_status=1
      else
        diagnostic_valid_takes="$(java_diagnostic_delta \
          "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta" t_valid)" || {
          diagnostic_valid_takes=""
          metric_status=1
        }
      fi
    fi
	if ((scenario_status == 0)) && [[ "$name" == "concurrency" ]]; then
		if ! scenario_reconciliation_json="$(concurrency_overlap_reconciliation \
			"$output" "$expected_requests")"; then
			log_error "concurrency result did not retain exact worker and arrival evidence"
			scenario_reconciliation_json="null"
			scenario_status=1
		fi
	elif ((scenario_status == 0)) && [[ "$name" == "tls-boundary" ]]; then
		if ! scenario_reconciliation_json="$(tls_boundary_reconciliation "$output")"; then
			log_error "TLS boundary result did not bind exact parents to same-request record evidence"
			scenario_reconciliation_json="null"
			scenario_status=1
		fi
	elif ((scenario_status == 0)) && [[ "$name" == "coalesced-bridge" ]]; then
      if scenario_reconciliation_json="$(coalesced_bridge_reconciliation "$output")"; then
        coalesced_outcome="$(jq -er '.outcome' <<<"$scenario_reconciliation_json")" || {
          coalesced_outcome=""
          metric_status=1
        }
      else
		log_error "coalesced receive control did not prove one fail-closed ambiguity outcome"
        scenario_reconciliation_json="null"
        scenario_status=1
      fi
      case "$coalesced_outcome" in
		receive_ambiguous)
          expected_bridge_valid=0
          expected_bridge_stage=0
          ;;
      esac
    elif ((scenario_status == 0)) && [[ "$name" == "timeout-retry" ]]; then
      if scenario_reconciliation_json="$(timeout_cancellation_reconciliation "$output")"; then
        timeout_parent_outcome="$(jq -er '.parent_outcome' \
          <<<"$scenario_reconciliation_json")" || {
          timeout_parent_outcome=""
          metric_status=1
        }
        if [[ "$timeout_parent_outcome" == "reason_coded_drop" ]]; then
          timeout_drop_reason="$(jq -er \
            '.drop_reasons | if length == 1 then .[0] else error("expected one drop reason") end' \
            <<<"$scenario_reconciliation_json")" || {
            timeout_drop_reason=""
            metric_status=1
          }
        fi
      else
        log_error "timeout result did not retain one bounded cancellation outcome"
        scenario_reconciliation_json="null"
        scenario_status=1
      fi
      if [[ "$diagnostic_valid_takes" =~ ^[12]$ ]]; then
        expected_bridge_valid="$diagnostic_valid_takes"
        expected_bridge_stage="$diagnostic_valid_takes"
      else
        log_error "timeout result did not report one or two valid Java takes"
        metric_status=1
      fi
    fi
    if [[ "$name" == "pressure" ]]; then
      if [[ "$pressure_runtime_quiesced" == true &&
        "$pressure_traffic_completed" == true &&
        -s "$output" && -f "$output" && ! -L "$output" ]]; then
        pressure_evidence_cleanup_deadline="$((
          SECONDS + PRESSURE_TRAFFIC_FINALIZATION_TIMEOUT_SECONDS +
            PRESSURE_TRANSACTION_CLEANUP_RESERVE_SECONDS
        ))"
        pressure_evidence_work_deadline="$(pressure_work_deadline \
          "$pressure_evidence_cleanup_deadline")" || {
          pressure_evidence_work_deadline=0
          metric_status=1
        }
      fi
      if ((pressure_evidence_work_deadline > 0)); then
        pressure_hits="$(pressure_scenario_count \
          "$output" exact_hit_count "$expected_requests" \
          "$pressure_evidence_work_deadline")" || pressure_hits=""
        pressure_roots="$(pressure_scenario_count \
          "$output" explicit_root_count "$expected_requests" \
          "$pressure_evidence_work_deadline")" || pressure_roots=""
        pressure_w3c="$(pressure_scenario_count \
          "$output" w3c_parent_count "$expected_requests" \
          "$pressure_evidence_work_deadline")" || pressure_w3c=""
        pressure_wrong="$(pressure_scenario_count \
          "$output" wrong_parent_count "$expected_requests" \
          "$pressure_evidence_work_deadline")" || pressure_wrong=""
        pressure_unresolved="$(pressure_scenario_count \
          "$output" unresolved_count "$expected_requests" \
          "$pressure_evidence_work_deadline")" || \
          pressure_unresolved=""
      else
        pressure_hits=""
        pressure_roots=""
        pressure_w3c=""
        pressure_wrong=""
        pressure_unresolved=""
      fi
      if [[ -n "$pressure_hits" && -n "$pressure_roots" && \
        -n "$pressure_w3c" && -n "$pressure_wrong" && \
        -n "$pressure_unresolved" ]]; then
        printf -v pressure_trace_json \
          '{"request_count":%d,"exact_hit_count":%d,"explicit_root_count":%d,"w3c_parent_count":%d,"wrong_parent_count":%d,"unresolved_count":%d}' \
          "$expected_requests" \
          "$pressure_hits" \
          "$pressure_roots" \
          "$pressure_w3c" \
          "$pressure_wrong" \
          "$pressure_unresolved"
      fi
      if [[ -z "$pressure_hits" || -z "$pressure_roots" || \
        -z "$pressure_w3c" || -z "$pressure_wrong" || \
        -z "$pressure_unresolved" ]] || \
        ((pressure_hits + pressure_roots + pressure_w3c + pressure_wrong +
          pressure_unresolved != expected_requests)); then
        log_error "pressure scenario did not report complete bounded parent outcomes"
        expected_bridge_valid=0
        expected_bridge_missing="$baseline_bridge_missing"
        expected_java_missing="$baseline_java_missing"
        if ((scenario_status == 0)); then
          scenario_status=1
        fi
      else
        # H is the only pre-reconciliation lower bound: the single W3C
        # request may add either one valid take or one attributable failure.
        expected_bridge_valid="$pressure_hits"
        expected_bridge_missing="$baseline_bridge_missing"
        expected_java_missing="$baseline_java_missing"
        if ((scenario_status == 0 &&
          (pressure_roots == 0 || pressure_w3c != 1 ||
          baseline_java_missing != 1 ||
          pressure_wrong != 0 || pressure_unresolved != 0 ||
          pressure_hits + pressure_roots + pressure_w3c != expected_requests))); then
          log_error "pressure scenario did not report H+R+W=N with W=1, R>=1, wrong=0, unresolved=0"
          scenario_status=1
        fi
      fi
    fi
    if [[ "$name" == pressure && "$PRESSURE_ACTIVE" == true ]]; then
      if [[ "$pressure_runtime_quiesced" == true ]]; then
        if [[ "$pressure_traffic_completed" == true &&
          "$PRESSURE_VERIFY_STATUS" == not-run ]] &&
          ! verify_map_pressure_after_traffic "$label"; then
          log_error "map-pressure synthetic content changed before cleanup"
          metric_status=1
        fi
        if ! cleanup_map_pressure_with_retries; then
          metric_status=1
        fi
      else
        log_error "deferring map-pressure cleanup until EXIT because runtime absence is unproved"
        metric_status=1
      fi
    fi
    if [[ ( "$name" == "tls-boundary" || "$name" == "coalesced-bridge" ) && \
      -n "$RECEIVE_CURSOR_MAP_ID" ]] && \
      ! wait_for_receive_cursor_map_recovery "$label"; then
      metric_status=1
    fi
    if [[ "$retrieval_mode" == "normal" ]] && ! is_w3c_stale_scenario "$name"; then
      case "$name" in
        coalesced-bridge)
		  # Go crypto/tls does not use the request-owned exact-prewrite path.
		  # This negative control therefore requires a zero native bridge
		  # lifecycle and a reason-coded ambiguity at the Java receive boundary.
          expected_bridge_lifecycle=0
          ;;
        timeout-retry)
          expected_bridge_lifecycle=2
          ;;
        *)
          expected_bridge_lifecycle="$expected_bridge_valid"
          expected_bridge_stage="$expected_bridge_valid"
          ;;
      esac
    fi
    if [[ "$bridge_was_running" == "true" ]]; then
      expected_success="$((before_success + expected_bridge_valid))"
      expected_stage="$((before_stage + expected_bridge_stage))"
      if ! wait_for_bridge_metrics_quiescent \
        "$expected_success" \
        "$expected_stage" \
        "$RESULT_DIR/metrics-after-$label.prom" \
        "$label scenario-attributable bridge operations"; then
        metric_status=1
      fi
    fi
    if [[ "$phase_evidence" == "metrics" ]]; then
      if ! capture_metric_phase_evidence "$after_phase"; then
        metric_status=1
      fi
    elif ! capture_phase_evidence "$after_phase"; then
      metric_status=1
    fi
    if [[ "$name" != "w3c-fault" && "$diagnostics_enabled" == "true" ]]; then
      if is_w3c_stale_scenario "$name" &&
        ! extract_java_diagnostics_after "$output" "$after_diagnostics"; then
        log_error "could not extract in-band Java diagnostics for $label"
        metric_status=1
      elif scenario_uses_in_band_java_diagnostics "$name" &&
        ! assert_sanitized_java_diagnostics "$after_diagnostics"; then
        log_error "in-band Java diagnostics became unavailable for $label"
        metric_status=1
      elif ! is_w3c_stale_scenario "$name" &&
        ! scenario_uses_in_band_java_diagnostics "$name" &&
        ! capture_java_diagnostics "$after_phase"; then
        metric_status=1
      fi
    fi
    if [[ "$name" == "w3c-fault" ]]; then
      fault_diagnostics_after="$RESULT_DIR/phases/$after_phase/java-diagnostics.txt"
      fault_diagnostics_delta="$RESULT_DIR/phases/$after_phase/java-diagnostics.delta"
      if [[ -z "$W3C_FAULT_DIAGNOSTICS_PREVIOUS" ]]; then
        log_error "W3C fault diagnostics baseline is unavailable for $label"
        metric_status=1
      elif ! extract_fault_diagnostics_after "$output" "$fault_diagnostics_after"; then
        log_error "could not extract terminal W3C fault diagnostics for $label"
        metric_status=1
      elif ! write_java_diagnostics_delta \
        "$W3C_FAULT_DIAGNOSTICS_PREVIOUS" \
        "$fault_diagnostics_after" \
        "$fault_diagnostics_delta"; then
        log_error "could not compute chained W3C fault diagnostics for $label"
        metric_status=1
      elif ! assert_w3c_fault_diagnostics_delta \
        "$fault_diagnostics_delta" \
        "$FAULT_MODE" \
        "$FAULT_REQUEST_COUNT"; then
        log_error "W3C fault diagnostics were not exactly attributable for $label"
        metric_status=1
      else
        W3C_FAULT_DIAGNOSTICS_PREVIOUS="$fault_diagnostics_after"
      fi
    fi
    if [[ -f "$RESULT_DIR/phases/$before_phase/obi-identity.json" &&
      ! -L "$RESULT_DIR/phases/$before_phase/obi-identity.json" &&
      -f "$RESULT_DIR/phases/$after_phase/obi-identity.json" &&
      ! -L "$RESULT_DIR/phases/$after_phase/obi-identity.json" ]]; then
      if ! obi_metric_pair_reference="$(record_obi_metric_pair \
        "$label" "$before_phase" "$after_phase" same_process "$after_phase")"; then
        log_error "could not retain the bounded OBI metric pair for $label"
        metric_status=1
      elif ! obi_metric_evidence_json="$(
        obi_metric_pair_evidence_json_from_reference "$obi_metric_pair_reference"
      )"; then
        log_error "could not bind the bounded OBI metric pair into $label status"
        obi_metric_evidence_json="null"
        metric_status=1
      fi
    elif [[ "$obi_was_running" == true ]]; then
      log_error "could not bind the $label metric snapshots to one OBI process"
      metric_status=1
    fi
    if ! write_metrics_delta \
      "$RESULT_DIR/phases/$before_phase/obi-metrics.prom" \
      "$RESULT_DIR/phases/$after_phase/obi-metrics.prom" \
      "$RESULT_DIR/phases/$after_phase/obi-metrics.delta"; then
      metric_status=1
    fi
    if [[ "$bridge_was_running" == "true" ]]; then
      if [[ "$name" == "coalesced-bridge" && -n "$coalesced_outcome" ]]; then
        if ! assert_coalesced_bridge_metric_delta \
          "$RESULT_DIR/phases/$after_phase/obi-metrics.delta" \
          "$SELECTED_TRANSPORT" \
          "$coalesced_outcome"; then
          metric_status=1
        fi
      elif [[ "$name" == "timeout-retry" && -n "$timeout_parent_outcome" ]]; then
        if ! assert_timeout_cancellation_metric_delta \
          "$RESULT_DIR/phases/$after_phase/obi-metrics.delta" \
          "$SELECTED_TRANSPORT" \
          "$timeout_parent_outcome" \
          "$diagnostic_valid_takes" \
          "$timeout_drop_reason"; then
          metric_status=1
        fi
      elif [[ "$name" == "pressure" ]]; then
        if [[ -n "$pressure_hits" && -n "$pressure_roots" &&
          -n "$pressure_w3c" && -n "$pressure_wrong" &&
          -n "$pressure_unresolved" ]]; then
          pressure_bridge_json="$(pressure_w3c_bridge_reconciliation \
            "$RESULT_DIR/phases/$after_phase/obi-metrics.delta" \
            "$SELECTED_TRANSPORT" \
            "$pressure_hits" \
            "$pressure_roots" \
            "$pressure_w3c" \
            "$expected_requests")" || {
            pressure_bridge_json="null"
            metric_status=1
          }
          if [[ "$pressure_bridge_json" != null ]]; then
            pressure_bridge_valid="$(jq -er '.retrieval_valid_count' \
              <<<"$pressure_bridge_json")" || pressure_bridge_valid=""
            pressure_bridge_failures="$(jq -er '.attributable_failure_count' \
              <<<"$pressure_bridge_json")" || pressure_bridge_failures=""
            pressure_w3c_masked_valid="$(jq -er '.w3c_masked_valid_count' \
              <<<"$pressure_bridge_json")" || pressure_w3c_masked_valid=""
            if [[ ! "$pressure_bridge_valid" =~ ^(0|[1-9][0-9]*)$ ||
              ! "$pressure_bridge_failures" =~ ^(0|[1-9][0-9]*)$ ||
              ! "$pressure_w3c_masked_valid" =~ ^(0|1)$ ]] ||
              ((pressure_hits > pressure_bridge_valid ||
                pressure_bridge_valid > pressure_hits + pressure_w3c ||
                pressure_roots > pressure_bridge_failures ||
                pressure_bridge_failures > pressure_roots + pressure_w3c ||
                pressure_bridge_valid + pressure_bridge_failures != expected_requests ||
                pressure_w3c_masked_valid != pressure_bridge_valid - pressure_hits ||
                pressure_w3c_masked_valid +
                  pressure_bridge_failures - pressure_roots != pressure_w3c)); then
              pressure_java_json="null"
              metric_status=1
            else
              expected_bridge_valid="$pressure_bridge_valid"
              expected_java_missing="$((
                baseline_java_missing + pressure_bridge_failures
              ))"
              printf -v pressure_java_json \
                '{"take_valid_count":%d,"take_sampled_count":%d,"take_unsampled_count":0,"discard_standard_count":%d,"attributable_absence_count":%d,"diagnostic_self_miss_count":%d}' \
                "$pressure_bridge_valid" \
                "$pressure_bridge_valid" \
                "$pressure_w3c_masked_valid" \
                "$pressure_bridge_failures" \
                "$baseline_java_missing"
            fi
          fi
          if [[ "$SELECTED_TRANSPORT" == "unix" ]]; then
            if [[ "$pressure_bridge_json" != null &&
              "$pressure_bridge_failures" =~ ^[1-9][0-9]*$ ]] &&
              pressure_unix_already_consumed_roots_are_reconciled \
                "$pressure_bridge_json" "$pressure_bridge_failures"; then
              pressure_unix_already_consumed_reconciled=true
            else
              metric_status=1
            fi
          fi
        else
          metric_status=1
        fi
      elif ! assert_bridge_metric_delta \
        "$RESULT_DIR/phases/$after_phase/obi-metrics.delta" \
        "$SELECTED_TRANSPORT" \
        "$expected_bridge_valid" \
        0 \
        "$expected_bridge_missing" \
        "$expected_bridge_lifecycle" \
        "$expected_bridge_stage" \
        "$include_ambiguous_candidates" \
        "$expected_bridge_stale" \
        "$expected_bridge_handoffs"; then
        metric_status=1
      fi
    fi
    if [[ "$diagnostics_enabled" == "true" && \
      ( "$bridge_was_running" == "true" || "$controlled_bridge_was_running" == "true" ) ]]; then
      if ! write_java_diagnostics_delta \
        "$RESULT_DIR/phases/$before_phase/java-diagnostics.txt" \
        "$RESULT_DIR/phases/$after_phase/java-diagnostics.txt" \
        "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta"; then
        log_error "could not parse Java diagnostics for $label"
        metric_status=1
      else
        expected_sampled="$expected_bridge_valid"
        expected_unsampled=0
        expected_standard=0
        expected_valid="$expected_bridge_valid"
        expected_stale=0
        expected_malformed=0
        expected_fault_status=""
        expected_fault_count=0
        case "$name" in
          w3c)
            expected_standard="$(((expected_requests + 1) / 2))"
            ;;
          w3c-match)
            expected_standard="$expected_requests"
            ;;
          obi-flags)
            expected_sampled="$((expected_requests / 2))"
            expected_unsampled="$(((expected_requests + 1) / 2))"
            ;;
          pressure)
            expected_standard="$pressure_w3c_masked_valid"
            ;;
          primary-w3c-stale|unix-w3c-stale)
            expected_stale="$expected_requests"
            ;;
        esac
        if [[ "$name" == "coalesced-bridge" ]]; then
          if ! assert_coalesced_bridge_diagnostics_delta \
            "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta" \
            "$coalesced_outcome"; then
            metric_status=1
          fi
        elif [[ "$name" == "timeout-retry" ]]; then
          if ! assert_timeout_cancellation_diagnostics_delta \
            "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta" \
            "$scenario_reconciliation_json"; then
            metric_status=1
          fi
		elif [[ "$name" == "pressure" && \
          "$pressure_unix_already_consumed_reconciled" == "true" ]]; then
          if ! assert_pressure_unix_already_consumed_diagnostics_delta \
            "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta" \
            "$expected_valid" \
            "$baseline_java_missing" \
            "$expected_sampled" \
            "$expected_unsampled" \
            "$expected_standard" \
            "$pressure_bridge_failures"; then
            metric_status=1
          fi
		elif ! assert_java_diagnostics_delta \
          "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta" \
          "$expected_valid" \
          "$expected_stale" \
          "$expected_malformed" \
          "$expected_java_missing" \
          "$expected_sampled" \
          "$expected_unsampled" \
          "$expected_standard" \
          "$expected_fault_status" \
          "$expected_fault_count"; then
          metric_status=1
        fi
      fi
    fi
    if [[ "$controlled_bridge_was_running" == "true" ]] && \
      ! stop_matching_bridge "$label" "$expected_requests"; then
      metric_status=1
    fi
    if [[ "$diagnostics_enabled" == "true" ]]; then
      if ! before_diagnostics_status_json="$(
        java_diagnostics_phase_evidence_json "$before_phase"
      )"; then
        log_error "could not retain valid before-phase Java diagnostics for $label"
        before_diagnostics_status_json="null"
        metric_status=1
      fi
      if ! after_diagnostics_status_json="$(
        java_diagnostics_phase_evidence_json "$after_phase"
      )"; then
        log_error "could not retain valid after-phase Java diagnostics for $label"
        after_diagnostics_status_json="null"
        metric_status=1
      fi
    fi
    if [[ "$name" == pressure && "$pressure_trace_json" != null ]] &&
      ((scenario_status == 0 && metric_status == 0)); then
      pressure_inspections_cleanup_deadline="$((SECONDS +
        PRESSURE_TRAFFIC_FINALIZATION_TIMEOUT_SECONDS +
        PRESSURE_TRANSACTION_CLEANUP_RESERVE_SECONDS))"
      pressure_inspections_work_deadline="$(pressure_work_deadline \
        "$pressure_inspections_cleanup_deadline")" ||
        pressure_inspections_work_deadline=0
      if ((pressure_inspections_work_deadline == 0)) ||
        ! pressure_scenario_container_inspections_descriptor \
          "$label" "$pressure_inspections_work_deadline" \
          pressure_container_inspections_descriptor_json \
          pressure_container_inspections_container_json; then
        log_error "could not authenticate the pressure container inspection artifact"
        metric_status=1
      elif [[ "$pressure_container_inspections_descriptor_json" == null ||
        "$pressure_container_inspections_container_json" == null ]]; then
        metric_status=1
      fi
    fi
    if ((scenario_status != 0 || metric_status != 0)); then
      status_name="failed"
    fi
    if [[ "$name" == "pressure" && "$pressure_trace_json" != "null" ]]; then
      printf -v pressure_status_json \
        '{"trace":%s,"bridge":%s,"java_reconciliation_target":%s,"barrier_reference":"map-pressure-%s-barrier-status.json","container_inspections":%s}' \
        "$pressure_trace_json" \
        "$pressure_bridge_json" \
        "$pressure_java_json" \
        "$label" \
        "$pressure_container_inspections_descriptor_json"
    fi
    if [[ "$name" == "tls-boundary" || "$name" == "coalesced-bridge" ]]; then
      receive_cursor_map_status_json="$RECEIVE_CURSOR_MAP_STATUS_JSON"
    fi
    if ! printf '{\n  "status": "%s",\n  "scenario": "%s",\n  "exit_status": %d,\n  "metric_status": %d,\n  "pressure_correlation": %s,\n  "scenario_reconciliation": %s,\n  "receive_coordination_maps": %s,\n  "java_diagnostics": {"before": %s, "after": %s},\n  "obi_metric_evidence": %s,\n  "obi_metric_boundary_ids": %s,\n  "result": "%s",\n  "stderr": "%s",\n  "before_phase": "%s",\n  "after_phase": "%s"\n}\n' \
      "$status_name" \
      "$name" \
      "$scenario_status" \
      "$metric_status" \
      "$pressure_status_json" \
      "$scenario_reconciliation_json" \
      "$receive_cursor_map_status_json" \
      "$before_diagnostics_status_json" \
      "$after_diagnostics_status_json" \
      "$obi_metric_evidence_json" \
      "$obi_metric_boundary_ids_json" \
      "$(basename -- "$output")" \
      "$(basename -- "$stderr_output")" \
      "phases/$before_phase" \
      "phases/$after_phase" >"$RESULT_DIR/scenario-$label-status.json"; then
      return 1
    fi
    bind_status_to_active_obi_metric_boundary \
      "scenario-$label-status.json" || return $?
    if [[ "$name" == pressure && "$status_name" == passed ]]; then
      if ! finalize_pressure_barrier_status \
        "$label" "$output" "$RESULT_DIR/scenario-$label-status.json"; then
        log_error "could not finalize the pressure ready-fill-release evidence"
        return 1
      fi
      reset_pressure_scenario_control_state || return $?
    fi
    log_info "$label status=$status_name evidence=$RESULT_DIR/scenario-$label-status.json"
    if ((scenario_status != 0)); then
      return "$scenario_status"
    fi
    if ((metric_status != 0)); then
      return "$metric_status"
    fi
    if [[ "$owns_obi_metric_boundary" == true ]]; then
      complete_obi_metric_boundary "$obi_metric_boundary_id" || return $?
    fi
    if [[ "$name" == "w3c-fault" ]] && ((run_number < REPEAT_COUNT)); then
      sleep "$JAVA_PROVIDER_RETRY_SETTLE_SECONDS" || return 1
    fi
  done
}

run_deliberate_assertion_failure_control() {
  local -r label="assertion-failure"
  local -r result="$RESULT_DIR/scenario-$label.json"
  local java_bridge_diagnostics=""
  local obi_metric_boundary_ids="[]"

  run_scenario basic || return $?
  RUN_STAGE="deliberate-assertion-failure"
  seal_terminal_java_diagnostics || return $?
  java_bridge_diagnostics="$(terminal_java_diagnostics_json)" || return $?
  obi_metric_boundary_ids="$(completed_obi_metric_boundary_ids_json)" || return $?
  if ! printf '{"status":"failed","scenario":"assertion-failure","reason":"deliberate assertion failure requested","expected_exit_status":2}\n' \
    >"$result"; then
    return 1
  fi
  if ! jq -cn \
    --arg result "$(basename -- "$result")" \
    --arg java_bridge_diagnostics_reference 'terminal-java-diagnostics.json' \
    --argjson java_bridge_diagnostics "$java_bridge_diagnostics" \
    --argjson obi_metric_boundary_ids "$obi_metric_boundary_ids" '
      {
        status: "failed",
        scenario: "assertion-failure",
        exit_status: 2,
        metric_status: 0,
        result: $result,
        failure_context: "failure-context.txt",
        obi_metric_boundary_ids: $obi_metric_boundary_ids,
        java_bridge_diagnostics_reference: $java_bridge_diagnostics_reference,
        java_bridge_diagnostics: $java_bridge_diagnostics
      }
    ' >"$RESULT_DIR/scenario-$label-status.json"; then
    return 1
  fi
  log_info "basic scenario passed; recording the requested deliberate assertion failure"
  die "deliberate assertion failure requested"
}

stop_obi_for_no_state_control() {
  local -r label="$1"
  local -r diagnostics_output="${2:-}"
  local pre_stop_metric_pair_reference=""
  local stopped_metric_pair_reference=""
  local stop_status=0

  plan_obi_metric_pair_capture "$label-pre-stop" || return $?
  plan_obi_metric_pair_capture "$label-obi-stopped" || return $?
  if ! capture_phase_evidence "$label-obi-pre-stop"; then
    log_error "could not capture the $label pre-stop metric baseline"
    return 1
  fi
  if ! flush_bridge_metric_boundary "$label" 1 1 "$diagnostics_output"; then
    log_error "could not establish the $label pre-stop bridge boundary"
    return 1
  fi
  if [[ -n "$diagnostics_output" && \
    ( ! -f "$diagnostics_output" || -L "$diagnostics_output" ) ]]; then
    log_error "$label pre-stop Java diagnostics snapshot is unavailable"
    return 1
  fi
  if ! capture_phase_evidence "$label-obi-running"; then
    log_error "could not capture the $label pre-stop evidence"
    return 1
  fi
  pre_stop_metric_pair_reference="$(record_obi_metric_pair \
    "$label-pre-stop" \
    "$label-obi-pre-stop" \
    "$label-obi-running" \
    same_process \
    "$label-obi-running")" || return $?
  obi_metric_pair_evidence_json_from_reference \
    "$pre_stop_metric_pair_reference" >/dev/null || return $?
  log_info "stopping OBI for the $label control"
  invalidate_selected_transport || return $?
  BRIDGE_RUNNING=false
  if run_bounded "$OBI_COMPOSE_COMMAND_TIMEOUT_SECONDS" \
    "${COMPOSE[@]}" stop --timeout "$OBI_COMPOSE_STOP_GRACE_SECONDS" obi; then
    OBI_RUNNING=false
  else
    stop_status=$?
    log_error "could not stop OBI for the $label control"
    return "$stop_status"
  fi
  capture_obi_stopped_attestation \
    "$label-obi-stopped" \
    "phases/$label-obi-running/obi-identity.json" || return $?
  if ! capture_java_diagnostics "$label-obi-stopped" ||
    ! java_diagnostics_reference_evidence_json \
      "phases/$label-obi-stopped/java-diagnostics.txt" >/dev/null; then
    log_error "could not capture valid $label post-stop Java diagnostics"
    return 1
  fi
  stopped_metric_pair_reference="$(record_obi_metric_pair \
    "$label-obi-stopped" \
    "$label-obi-running" \
    "$label-obi-stopped" \
    same_process \
    "$label-obi-stopped")" || return $?
  obi_metric_pair_evidence_json_from_reference \
    "$stopped_metric_pair_reference" >/dev/null
}

run_fail_open_control() {
  stop_obi_for_no_state_control "fail-open" || return $?
  run_scenario fail-open
}

run_w3c_only_control() {
  stop_obi_for_no_state_control "w3c-only" || return $?
  run_scenario w3c-only
}

run_late_attach_recovery_sequence() {
  local -r attach_since="$1"
  local apache_since=""
  local scenario_status=0

  [[ -n "$attach_since" ]] || return 1
  log_info "starting OBI and requiring late helper attach without a JVM restart"
  run_bounded 120 \
    "${COMPOSE[@]}" up --detach \
      --timeout "$OBI_COMPOSE_STOP_GRACE_SECONDS" obi || return $?
  OBI_RUNNING=true
  wait_for_log \
    obi \
    "Java remote parent bridge ready" \
    "late-attach OBI remote-parent bridge" \
    "$attach_since" || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent provider ready" \
    "late-attached Java helper" \
    "$attach_since" || return $?
  wait_for_log \
    java-backend \
    "OBI Java instrumentation ready" \
    "late-attached Java instrumentation" \
    "$attach_since" || return $?
  BRIDGE_RUNNING=true
  assert_selected_transport || return $?
  log_info "recycling Apache connections created before late attach"
  run_bounded 60 \
    "${COMPOSE[@]}" stop --timeout 10 apache-proxy || return $?
  wait_for_apache_instrumentation_drain late-attach || return $?
  apache_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  run_bounded 120 \
    "${COMPOSE[@]}" up --detach --force-recreate \
      --no-deps apache-proxy || return $?
  wait_for_log \
    obi \
    "cmd=/usr/local/apache2/bin/httpd" \
    "late-attach Apache instrumentation" \
    "$apache_since" || return $?
  wait_for_apache_instrumentation late-attach || return $?
  wait_for_http \
    "$APACHE_HTTPS_HEALTH_ENDPOINT" \
    "late-attach recovered HTTPS path" || return $?
  wait_for_java_duplicate_suppression \
    "$RESULT_DIR/duplicate-suppression-late-attach-recovery.prom" || return $?
  SCENARIO_VARIANT="late-attach-recovery"
  if run_scenario restart; then
    SCENARIO_VARIANT=""
  else
    scenario_status=$?
    SCENARIO_VARIANT=""
    return "$scenario_status"
  fi
}

run_late_attach_control() {
  local attach_since=""
  local recovery_boundary_status=0
  local recovery_status=0
  local terminal_diagnostics_status=0

  stop_obi_for_no_state_control "late-attach" || return $?
  export EXTENSION_ENABLED=true
  export JAVA_TOOL_OPTIONS_VALUE="-javaagent:/otel/official-javaagent.jar"
  export OTEL_JAVAAGENT_EXTENSIONS_VALUE="/otel/obi-otel-extension.jar"
  export OTEL_PROPAGATORS_VALUE="obi,tracecontext,baggage"
  log_info "recreating the JVM while OBI is absent"
  run_bounded 120 \
    "${COMPOSE[@]}" up --detach --force-recreate \
      java-backend apache-proxy || return $?
  wait_for_http \
    "$APACHE_HTTPS_HEALTH_ENDPOINT" \
    "OBI-absent HTTPS path" || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent propagator enabled" \
    "OBI-absent external extension" || return $?
  assert_runtime_contract obi-absent || return $?

  SCENARIO_VARIANT="obi-absent"
  run_scenario fail-open
  run_scenario w3c-only
  SCENARIO_VARIANT=""

  attach_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  if capture_terminal_java_diagnostics_recovery_boundary; then
    :
  else
    recovery_boundary_status=$?
    if seal_terminal_java_diagnostics; then
      :
    else
      terminal_diagnostics_status=$?
    fi
  fi
  if run_late_attach_recovery_sequence "$attach_since"; then
    recovery_status=0
  else
    recovery_status=$?
  fi
  if ((recovery_boundary_status != 0)); then
    return "$recovery_boundary_status"
  fi
  if ((recovery_status != 0)); then
    if seal_terminal_java_diagnostics; then
      :
    else
      terminal_diagnostics_status=$?
    fi
    return "$recovery_status"
  fi
  commit_terminal_java_diagnostics_recovery_boundary || return $?
  clear_terminal_java_diagnostics_recovery_boundary || return $?
  return "$terminal_diagnostics_status"
}

assert_compose_service_stopped() {
  local -r service="$1"
  local -r boundary="${2:-permanent-absence boundary}"
  local running=""

  [[ "$service" =~ ^[a-z][a-z0-9-]{0,63}$ ]] || return 1
  [[ "$boundary" =~ ^[a-z0-9][-a-z0-9\ ]{0,95}$ ]] || return 1
  running="$(run_bounded 10 "${COMPOSE[@]}" ps --quiet "$service" 2>/dev/null)" || return $?
  [[ -z "$running" ]] || {
    log_error "$service remained running across the $boundary"
    return 1
  }
}

stop_permanent_absence_jvm() {
  assert_project_docker_identity_unchanged || return $?
  run_bounded 60 "${COMPOSE[@]}" stop --timeout 10 \
    apache-proxy java-backend || return $?
  assert_compose_service_stopped apache-proxy || return $?
  assert_compose_service_stopped java-backend
}

assert_runtime_identity_unchanged() {
  local -r before="$1"
  local -r after="$2"
  local -r description="${3:-controlled requests}"

  [[ -f "$before" && ! -L "$before" && -f "$after" && ! -L "$after" ]] || return 1
  runtime_identity_field "$before" container_id >/dev/null || return 1
  runtime_identity_field "$before" host_pid >/dev/null || return 1
  runtime_identity_field "$before" started_at >/dev/null || return 1
  runtime_identity_field "$after" container_id >/dev/null || return 1
  runtime_identity_field "$after" host_pid >/dev/null || return 1
  runtime_identity_field "$after" started_at >/dev/null || return 1
  cmp -s -- "$before" "$after" || {
    log_error "the $description did not remain in one JVM lifetime"
    return 1
  }
}

assert_permanent_absence_logs_are_bounded() {
  local -r input="$1"

  bounded_evidence_file \
    "$input" \
    "$PERMANENT_ABSENCE_LOG_MAX_BYTES" \
    "$PERMANENT_ABSENCE_LOG_MAX_LINES" || return 1
  LC_ALL=C awk \
    -v maximum="$PERMANENT_ABSENCE_REMOTE_PARENT_LOG_MAX" '
    index($0, "OBI remote-parent") {
      remote_parent_lines++
      if (length($0) > 1024) {
        overlong = 1
      }
    }
    index($0, "OBI remote-parent propagator enabled") {
      propagator_enabled++
    }
    index($0, "OBI remote-parent provider ready") {
      provider_ready++
    }
    index($0, "OBI Java instrumentation ready") {
      instrumentation_ready++
    }
    END {
      exit remote_parent_lines <= maximum && !overlong &&
        propagator_enabled >= 1 && provider_ready == 0 &&
        instrumentation_ready == 0 ? 0 : 1
    }
  ' "$input" || {
    log_error "permanent-absence Java diagnostics were unbounded or reported false readiness"
    return 1
  }
}

capture_bounded_permanent_absence_logs() {
  local -r service="$1"
  local -r since="$2"
  local -r output="$3"
  local temporary=""
  local size=""
  local pipeline_status=0
  local overflow=false

  [[ "$service" =~ ^[a-z][a-z0-9-]{0,63}$ && ! -L "$output" ]] || return 1
  temporary="$(mktemp "$output.capture.XXXXXX")" || return $?
  if run_bounded "$PERMANENT_ABSENCE_LOG_CAPTURE_TIMEOUT_SECONDS" \
    "${COMPOSE[@]}" logs --no-color --since "$since" "$service" |
    (
      LC_ALL=C head -c "$((PERMANENT_ABSENCE_LOG_MAX_BYTES + 1))" \
        >"$temporary" || exit $?
      cat >/dev/null
    ); then
    :
  else
    pipeline_status=$?
  fi
  size="$(stat -c '%s' -- "$temporary")" || {
    pipeline_status=$?
    rm -f -- "$temporary" || true
    return "$pipeline_status"
  }
  if ((size > PERMANENT_ABSENCE_LOG_MAX_BYTES)) || \
    ! bounded_evidence_file \
      "$temporary" \
      "$PERMANENT_ABSENCE_LOG_MAX_BYTES" \
      "$PERMANENT_ABSENCE_LOG_MAX_LINES"; then
    overflow=true
    retain_bounded_evidence_limits \
      "$temporary" \
      "$PERMANENT_ABSENCE_LOG_MAX_BYTES" \
      "$PERMANENT_ABSENCE_LOG_MAX_LINES" || {
      pipeline_status=$?
      rm -f -- "$temporary" || true
      return "$pipeline_status"
    }
  fi
  if chmod 0644 "$temporary" && mv -fT -- "$temporary" "$output"; then
    :
  else
    pipeline_status=$?
    rm -f -- "$temporary" || true
    return "$pipeline_status"
  fi
  if ((pipeline_status != 0)); then
    log_error "could not capture the complete permanent-absence Java log stream"
    return "$pipeline_status"
  fi
  if [[ "$overflow" == "true" ]]; then
    log_error "permanent-absence Java logs exceeded the retained bounds"
    return 1
  fi
}

wait_for_bounded_permanent_absence_log() {
  local -r service="$1"
  local -r pattern="$2"
  local -r description="$3"
  local -r since="$4"
  local -r failure_snapshot="$RESULT_DIR/permanent-absence-readiness.log"
  local snapshot=""
  local -i deadline=0
  local capture_status=0
  local sleep_status=0

  [[ -n "$pattern" && -n "$since" && \
    ! -e "$failure_snapshot" && ! -L "$failure_snapshot" ]] || return 1
  snapshot="$(mktemp "$RESULT_DIR/.permanent-absence-readiness.XXXXXX")" || return $?
  deadline=$((SECONDS + READINESS_TIMEOUT_SECONDS))
  while ((SECONDS < deadline)); do
    if capture_bounded_permanent_absence_logs \
      "$service" "$since" "$snapshot"; then
      :
    else
      capture_status=$?
      mv -fT -- "$snapshot" "$failure_snapshot" || return $?
      return "$capture_status"
    fi
    if ! bounded_evidence_file \
      "$snapshot" \
      "$PERMANENT_ABSENCE_LOG_MAX_BYTES" \
      "$PERMANENT_ABSENCE_LOG_MAX_LINES"; then
      mv -fT -- "$snapshot" "$failure_snapshot" || return $?
      log_error "permanent-absence readiness logs exceeded their fixed bounds"
      return 1
    fi
    if grep -Fq -- "$pattern" "$snapshot"; then
      rm -f -- "$snapshot" || return $?
      log_info "$description is ready"
      return 0
    fi
    if ((SECONDS < deadline)); then
      sleep 1 || {
        sleep_status=$?
        rm -f -- "$snapshot" || true
        return "$sleep_status"
      }
    fi
  done
  mv -fT -- "$snapshot" "$failure_snapshot" || return $?
  log_error "timed out waiting for $description log: $pattern"
  return 1
}

run_permanent_absence_control() (
  local -r original_variant="$SCENARIO_VARIANT"
  local -r original_transport="$TRANSPORT"
  local -r original_propagation="${CONTEXT_PROPAGATION:-tcp}"
  local -r recovery_marker="$RESULT_DIR/permanent-absence-recovery-required"
  local -r timeline="$RESULT_DIR/permanent-absence-lifetime.txt"
  local -r identity_before="$RESULT_DIR/permanent-absence-java-before.txt"
  local -r identity_after="$RESULT_DIR/permanent-absence-java-after.txt"
  local -r logs="$RESULT_DIR/permanent-absence-java.log"
  local -r diagnostics="$RESULT_DIR/phases/permanent-absence/java-diagnostics.txt"
  local absence_since=""
  local registration_failures=""
  local restore_required=false
  local absence_jvm_may_be_running=false
  local safe_to_restore=true
  local restore_status=0
  local restore_entry_status=""

  complete_permanent_absence_recovery() {
    assert_project_docker_identity_unchanged || return $?
    recreate_instrumented_stack \
      "$original_propagation" "post-permanent absence recovery" \
      "$original_transport" true false base || return $?
    SCENARIO_VARIANT="permanent-absence-recovery"
    run_scenario basic || return $?
    clear_pending_permanent_absence_recovery || return $?
    rm -f -- "$recovery_marker" || return $?
  }

  # shellcheck disable=SC2329 # Invoked by the EXIT trap below.
  restore_permanent_absence_stack() {
    local -r status="${1:-$?}"
    local terminal_diagnostics_status=0

    trap - EXIT
    set +e
    arm_permanent_absence_record_only_traps
    seal_terminal_java_diagnostics
    terminal_diagnostics_status=$?
    if [[ "$absence_jvm_may_be_running" == "true" ]]; then
      if stop_permanent_absence_jvm; then
        absence_jvm_may_be_running=false
      else
        restore_status=$?
        safe_to_restore=false
        log_error "refusing to start OBI while the permanent-absence JVM may still be running"
      fi
    fi
    if [[ "$restore_required" == "true" && "$safe_to_restore" == "true" ]]; then
      complete_permanent_absence_recovery
      restore_status=$?
    fi
    SCENARIO_VARIANT="$original_variant"
    # Recovery is complete at this boundary. Preserve every earlier signal,
    # then ignore later arrivals so this subshell's status cannot diverge from
    # the recovery decision returned to the guarded runner.
    trap '' HUP INT TERM
    if ((status == 0 && CLEANUP_SIGNAL_STATUS != 0)); then
      exit "$CLEANUP_SIGNAL_STATUS"
    fi
    if ((status == 0 && restore_status != 0)); then
      exit "$restore_status"
    fi
    if ((status == 0 && terminal_diagnostics_status != 0)); then
      exit "$terminal_diagnostics_status"
    fi
    exit "$status"
  }

  arm_permanent_absence_record_only_traps() {
    # The first update closes the re-entry window in one builtin. Subsequent
    # updates preserve the exact first signal without dynamically reparsing a
    # nested trap program during recovery.
    trap record_cleanup_term HUP INT TERM
    trap record_cleanup_hup HUP
    trap record_cleanup_int INT
    trap record_cleanup_term TERM
  }

  permanent_absence_signal_hup() {
    arm_permanent_absence_record_only_traps
    record_cleanup_signal HUP
    restore_permanent_absence_stack 129
  }

  permanent_absence_signal_int() {
    arm_permanent_absence_record_only_traps
    record_cleanup_signal INT
    restore_permanent_absence_stack 130
  }

  permanent_absence_signal_term() {
    arm_permanent_absence_record_only_traps
    record_cleanup_signal TERM
    restore_permanent_absence_stack 130
  }

  permanent_absence_exit() {
    local -r entry_status="$?"

    restore_entry_status="${restore_entry_status:-$entry_status}"
    arm_permanent_absence_record_only_traps
    restore_permanent_absence_stack "$restore_entry_status"
  }

  CLEANUP_SIGNAL_STATUS=0
  trap permanent_absence_exit EXIT
  trap permanent_absence_signal_hup HUP
  trap permanent_absence_signal_int INT
  trap permanent_absence_signal_term TERM
  assert_project_docker_identity_unchanged || return $?
  [[ "$original_transport" == "getsockopt" || "$original_transport" == "unix" || \
    "$original_transport" == "auto" ]] || return 1
  [[ ! -e "$recovery_marker" && ! -L "$recovery_marker" && \
    ! -e "$timeline" && ! -L "$timeline" ]] || return 1
  create_permanent_absence_global_marker || return $?
  if ! (umask 077; printf 'recovery_required\n' >"$recovery_marker"); then
    clear_pending_permanent_absence_recovery || true
    return 1
  fi
  restore_required=true

  assert_project_docker_identity_unchanged || return $?
  SCENARIO_VARIANT="permanent-absence-baseline"
  run_disabled_control || return $?
  SCENARIO_VARIANT="$original_variant"
  capture_control_response permanent-absence-disabled || return $?
  printf 'disabled_baseline=captured\n' >"$timeline" || return $?

  invalidate_selected_transport || return $?
  BRIDGE_RUNNING=false
  assert_project_docker_identity_unchanged || return $?
  run_bounded "$OBI_COMPOSE_MULTI_SERVICE_COMMAND_TIMEOUT_SECONDS" \
    "${COMPOSE[@]}" stop --timeout "$OBI_COMPOSE_STOP_GRACE_SECONDS" \
    apache-proxy java-backend obi || return $?
  OBI_RUNNING=false
  assert_compose_service_stopped apache-proxy || return $?
  assert_compose_service_stopped java-backend || return $?
  assert_compose_service_stopped obi || return $?
  printf 'obi=stopped-before-jvm-start\n' >>"$timeline" || return $?

  export BRIDGE_TRANSPORT="$original_transport"
  export EXTENSION_ENABLED=true
  export JAVA_TOOL_OPTIONS_VALUE="-javaagent:/otel/official-javaagent.jar"
  export OTEL_JAVAAGENT_EXTENSIONS_VALUE="/otel/obi-otel-extension.jar"
  export OTEL_PROPAGATORS_VALUE="obi,tracecontext,baggage"
  absence_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  absence_jvm_may_be_running=true
  assert_project_docker_identity_unchanged || return $?
  run_bounded 120 "${COMPOSE[@]}" up --detach --force-recreate \
    java-backend apache-proxy || return $?
  assert_compose_service_stopped obi || return $?
  wait_for_http "$APACHE_HTTPS_HEALTH_ENDPOINT" \
    "permanent-absence HTTPS path" || return $?
  wait_for_bounded_permanent_absence_log \
    java-backend "OBI remote-parent propagator enabled" \
    "permanent-absence external extension" "$absence_since" || return $?
  assert_runtime_contract permanent-absence || return $?
  capture_service_runtime_identity java-backend "$identity_before" || return $?
  printf 'jvm=started-with-obi-absent\n' >>"$timeline" || return $?

  capture_control_response permanent-absence || return $?
  cmp -s -- \
    "$RESULT_DIR/permanent-absence-disabled-response.normalized.json" \
    "$RESULT_DIR/permanent-absence-response.normalized.json" || return $?
  cmp -s -- \
    "$RESULT_DIR/permanent-absence-disabled-response.status" \
    "$RESULT_DIR/permanent-absence-response.status" || return $?
  SCENARIO_VARIANT="permanent-absence"
  run_scenario fail-open || return $?
  run_scenario w3c-only || return $?
  capture_java_diagnostics permanent-absence || return $?
  assert_sanitized_java_diagnostics "$diagnostics" || return $?
  registration_failures="$(diagnostic_counter "$diagnostics" registration_fail)" || return $?
  ((registration_failures >= 1 && \
    registration_failures <= PERMANENT_ABSENCE_REGISTRATION_FAILURE_MAX)) || {
    log_error "permanent-absence provider registration retries were not bounded"
    return 1
  }
  capture_service_runtime_identity java-backend "$identity_after" || return $?
  assert_runtime_identity_unchanged "$identity_before" "$identity_after" || return $?
  assert_compose_service_stopped obi || return $?
  printf 'requests=completed-in-one-jvm\nobi=absent-at-final-checkpoint\n' \
    >>"$timeline" || return $?

  capture_terminal_java_diagnostics_recovery_boundary || return $?
  stop_permanent_absence_jvm || return $?
  absence_jvm_may_be_running=false
  capture_bounded_permanent_absence_logs \
    java-backend "$absence_since" "$logs" || return $?
  assert_permanent_absence_logs_are_bounded "$logs" || return $?
  printf 'jvm=stopped-before-obi-recovery\n' >>"$timeline" || return $?
  complete_permanent_absence_recovery || return $?
  restore_required=false
  SCENARIO_VARIANT="$original_variant"
  printf '{"status":"passed","scenario":"permanent-absence","obi_started_during_jvm_lifetime":false,"single_jvm_lifetime":true,"disabled_baseline_equivalent":true,"fail_open":"passed","w3c_precedence":"passed","diagnostics":"bounded","post_absence_recovery":"passed"}\n' \
    >"$RESULT_DIR/scenario-permanent-absence-status.json"
  crosslink_and_bind_active_obi_metric_boundary_status \
    scenario-permanent-absence-status.json || return $?

  commit_terminal_java_diagnostics_recovery_boundary || return $?
  trap - EXIT
  clear_terminal_java_diagnostics_recovery_boundary || return $?
)

run_auto_unavailable_control() (
  # This lifecycle proof deliberately contributes one fail-open and one W3C
  # request per repeat. A custom all-suite request count must not turn this
  # bounded control into an unrelated bulk workload.
  local -r REQUEST_COUNT=1
  local -r original_variant="$SCENARIO_VARIANT"
  local -r original_propagation="${CONTEXT_PROPAGATION:-tcp}"
  local -r before_phase="auto-unavailable-before"
  local -r after_phase="auto-unavailable-after"
  local -r before_diagnostics="$RESULT_DIR/phases/$before_phase/java-diagnostics.txt"
  local -r stopped_diagnostics="$RESULT_DIR/phases/auto-unavailable-obi-stopped/java-diagnostics.txt"
  local -r diagnostics_delta="$RESULT_DIR/phases/$after_phase/java-diagnostics.delta"
  local -r transport_configuration="$RESULT_DIR/java-auto-unavailable-transport-configuration.txt"
  local -r identity_before="$RESULT_DIR/auto-unavailable-java-before.txt"
  local -r identity_fault="$RESULT_DIR/auto-unavailable-java-fault.txt"
  local -r identity_recovery="$RESULT_DIR/auto-unavailable-java-recovery.txt"
  local restart_since=""
  local restore_required=false
  local restore_status=0

  # shellcheck disable=SC2329 # Invoked by the EXIT trap below.
  restore_auto_unavailable_stack() {
    local -r status="$?"
    local terminal_diagnostics_status=0

    trap - EXIT
    set +e
    seal_terminal_java_diagnostics
    terminal_diagnostics_status=$?
    if [[ "$restore_required" == "true" ]]; then
      (
        set -Eeuo pipefail
        recreate_instrumented_stack \
          "$original_propagation" "auto-unavailable cleanup" auto
      )
      restore_status=$?
    fi
    SCENARIO_VARIANT="$original_variant"
    if ((status == 0 && restore_status != 0)); then
      exit "$restore_status"
    fi
    if ((status == 0 && terminal_diagnostics_status != 0)); then
      exit "$terminal_diagnostics_status"
    fi
    exit "$status"
  }

  trap restore_auto_unavailable_stack EXIT
  [[ "$TRANSPORT" == "auto" &&
    ( "$SELECTED_TRANSPORT" == "getsockopt" || "$SELECTED_TRANSPORT" == "unix" ) &&
    "$BRIDGE_RUNNING" == "true" ]] || {
    log_error "the auto-unavailable control requires a healthy auto-selected bridge"
    return 1
  }
  restore_required=true

  SCENARIO_VARIANT="auto-unavailable-baseline"
  run_disabled_control || return $?
  SCENARIO_VARIANT="$original_variant"
  capture_control_response auto-unavailable-disabled || return $?
  recreate_instrumented_stack \
    "$original_propagation" "auto-unavailable preparation" auto || return $?
  assert_runtime_contract basic true || return $?
  capture_service_runtime_identity java-backend "$identity_before" || return $?
  mkdir -p -- "$RESULT_DIR/phases/$before_phase" || return $?
  stop_obi_for_no_state_control auto-unavailable "$before_diagnostics" || return $?
  assert_runtime_contract auto-unavailable || return $?

  capture_control_response auto-unavailable || return $?
  cmp -s -- \
    "$RESULT_DIR/auto-unavailable-disabled-response.normalized.json" \
    "$RESULT_DIR/auto-unavailable-response.normalized.json" || return $?
  cmp -s -- \
    "$RESULT_DIR/auto-unavailable-disabled-response.status" \
    "$RESULT_DIR/auto-unavailable-response.status" || return $?

  sleep "$JAVA_PROVIDER_RETRY_SETTLE_SECONDS" || return $?
  SCENARIO_VARIANT="auto-unavailable"
  run_scenario fail-open false || return $?
  wait_for_auto_transports_unavailable_configuration \
    "$transport_configuration" || return $?
  run_scenario w3c-only false || return $?
  capture_java_diagnostics "$after_phase" || return $?
  write_java_diagnostics_delta \
    "$stopped_diagnostics" \
    "$RESULT_DIR/phases/$after_phase/java-diagnostics.txt" \
    "$diagnostics_delta" || return $?
  assert_auto_unavailable_diagnostics_delta "$diagnostics_delta" || return $?
  capture_service_runtime_identity java-backend "$identity_fault" || return $?
  assert_runtime_identity_unchanged \
    "$identity_before" "$identity_fault" "auto-unavailable requests" || return $?
  assert_compose_service_stopped obi "auto-unavailable boundary" || return $?

  capture_terminal_java_diagnostics_recovery_boundary || return $?
  restart_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  run_bounded 120 \
    "${COMPOSE[@]}" up --detach \
      --timeout "$OBI_COMPOSE_STOP_GRACE_SECONDS" obi || return $?
  OBI_RUNNING=true
  wait_for_log \
    obi \
    "Java remote parent bridge ready" \
    "auto-unavailable OBI recovery" \
    "$restart_since" || return $?
  sleep "$JAVA_PROVIDER_RETRY_SETTLE_SECONDS" || return $?
  BRIDGE_RUNNING=true
  wait_for_apache_instrumentation auto-unavailable-recovery || return $?
  wait_for_http \
    "$APACHE_HTTPS_HEALTH_ENDPOINT" \
    "auto-unavailable Java provider recovery" || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent provider ready" \
    "auto-unavailable Java provider recovery" \
    "$restart_since" || return $?
  assert_selected_transport auto || return $?
  wait_for_java_duplicate_suppression \
    "$RESULT_DIR/duplicate-suppression-auto-unavailable-recovery.prom" || return $?
  assert_runtime_contract basic true || return $?
  capture_service_runtime_identity java-backend "$identity_recovery" || return $?
  assert_runtime_identity_unchanged \
    "$identity_before" "$identity_recovery" "auto-unavailable recovery" || return $?
  SCENARIO_VARIANT="auto-unavailable-recovery"
  run_scenario basic || return $?
  SCENARIO_VARIANT="$original_variant"
  restore_required=false
  printf '{"status":"passed","scenario":"auto-unavailable","requested_transport":"auto","attempted_transports":["getsockopt","unix"],"selected_transport":"none","disabled_baseline_equivalent":true,"fail_open":"passed","w3c_precedence":"passed","single_jvm_lifetime":true,"retry_storm":"absent","post_fault_recovery":"passed"}\n' \
    >"$RESULT_DIR/scenario-auto-unavailable-status.json"
  crosslink_and_bind_active_obi_metric_boundary_status \
    scenario-auto-unavailable-status.json || return $?

  commit_terminal_java_diagnostics_recovery_boundary || return $?
  trap - EXIT
  clear_terminal_java_diagnostics_recovery_boundary || return $?
)

prepare_restart_control_directory() {
  local -r directory="$1"

  if [[ -e "$directory" || -L "$directory" ]]; then
    log_error "restart control path already exists: $directory"
    return 1
  fi
  if ! mkdir -- "$directory"; then
    log_error "could not create restart control directory: $directory"
    return 1
  fi
  [[ -d "$directory" && ! -L "$directory" ]] || {
    log_error "restart control path is not a real directory: $directory"
    return 1
  }
}

record_restart_control_event() {
  local -r directory="$1"
  local -r event="$2"
  local -r events="$directory/events.log"
  local timestamp=""

  if [[ -L "$events" || ( -e "$events" && ! -f "$events" ) ]]; then
    log_error "restart control event target is not a regular file: $events"
    return 1
  fi
  timestamp="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  printf '%s %s\n' "$timestamp" "$event" >>"$events" || return $?
}

publish_restart_control_release() {
  local -r directory="$1"
  local -r name="$2"
  local -r target="$directory/$name"
  local temporary=""

  [[ "$name" =~ ^[a-z][a-z-]{0,63}$ ]] || {
    log_error "invalid restart control release name: $name"
    return 1
  }
  [[ -d "$directory" && ! -L "$directory" ]] || {
    log_error "restart control directory changed before release: $directory"
    return 1
  }
  if [[ -e "$target" || -L "$target" ]]; then
    log_error "restart control release already exists: $target"
    return 1
  fi
  temporary="$(mktemp "$directory/.$name.XXXXXX")" || return $?
  if ! printf '%s\n' "$name" >"$temporary"; then
    rm -f -- "$temporary"
    return 1
  fi
  if ! chmod 0644 -- "$temporary"; then
    rm -f -- "$temporary"
    return 1
  fi
  if ! ln -- "$temporary" "$target"; then
    rm -f -- "$temporary"
    return 1
  fi
  if ! rm -f -- "$temporary"; then
    log_error "could not remove temporary restart release: $temporary"
    return 1
  fi
  record_restart_control_event "$directory" "released:$name"
}

wait_for_restart_control_signal() {
  local -r directory="$1"
  local -r name="$2"
  local -r description="$3"
  local -r scenario_pid="$4"
  local -r path="$directory/$name"
  local -i started_at="$SECONDS"

  [[ "$name" =~ ^[a-z][a-z-]{0,63}$ ]] || {
    log_error "invalid restart control signal name: $name"
    return 1
  }
  while ((SECONDS - started_at < READINESS_TIMEOUT_SECONDS)); do
    if [[ -e "$path" || -L "$path" ]]; then
      if [[ -L "$path" || ! -f "$path" ]]; then
        log_error "restart control signal is not a regular file: $path"
        return 1
      fi
      if ! cmp -s -- "$path" <(printf '%s\n' "$name"); then
        log_error "restart control signal has invalid contents: $path"
        return 1
      fi
      record_restart_control_event "$directory" "observed:$name" || return $?
      log_info "$description is complete"
      return 0
    fi
    if ! kill -0 "$scenario_pid" 2>/dev/null; then
      log_error "$description traffic ended before publishing $name"
      return 1
    fi
    sleep 0.1
  done
  log_error "timed out waiting for $description signal: $name"
  return 1
}

run_restart_during_traffic_control() (
  local -r label="restart-fault"
  local -r output="$RESULT_DIR/scenario-$label.json"
  local -r stderr_output="$RESULT_DIR/scenario-$label.stderr.log"
  local -r before_phase="$label-before"
  local -r after_phase="$label-after"
  local -r control_dir="$RESULT_DIR/restart-control"
  local restart_since=""
  local scenario_pid=""
  local scenario_status=0
  local obi_metric_pair_reference=""
  local obi_metric_evidence_json="null"

  # shellcheck disable=SC2329 # Invoked by the EXIT trap below.
  cleanup_restart_traffic() {
    local -r status="$?"
    local terminal_diagnostics_status=0

    trap - EXIT
    set +e
    if ((status != 0)); then
      seal_terminal_java_diagnostics
      terminal_diagnostics_status=$?
    fi
    if [[ -n "$scenario_pid" ]]; then
      if kill -0 "$scenario_pid" 2>/dev/null; then
        kill -TERM "$scenario_pid" 2>/dev/null || true
      fi
      wait "$scenario_pid" 2>/dev/null || true
      scenario_pid=""
    fi
    if ((status == 0 && terminal_diagnostics_status != 0)); then
      exit "$terminal_diagnostics_status"
    fi
    exit "$status"
  }

  trap cleanup_restart_traffic EXIT

  [[ "$BRIDGE_RUNNING" == "true" ]] || {
    log_error "restart-during-traffic control requires a running bridge"
    return 1
  }
  plan_obi_metric_pair_capture "$label" || return $?
  prepare_restart_control_directory "$control_dir" || return $?
  log_info "running valid-W3C traffic while OBI restarts"
  capture_phase_evidence "$before_phase" || return $?
  capture_java_diagnostics "$before_phase" || return $?
  timeout --signal=TERM --kill-after=10s 180s \
    "${COMPOSE[@]}" run --rm --no-deps --no-TTY \
      --volume "$control_dir:$RESTART_CONTROL_CONTAINER_DIR:rw" \
      scenario \
      --scenario restart-fault \
      --requests 32 \
      --expected-tls "$TLS_PROTOCOL" \
      --seed "$SCENARIO_SEED" \
      --restart-control-dir "$RESTART_CONTROL_CONTAINER_DIR" \
      --timeout 120s \
      </dev/null \
      >"$output" \
      2> >(tee "$stderr_output" >&2) &
  scenario_pid=$!
  wait_for_restart_control_signal \
    "$control_dir" \
    "$RESTART_SIGNAL_PRE_STOP_READY" \
    "pre-stop restart traffic" \
    "$scenario_pid" || return $?

  invalidate_selected_transport || return $?
  BRIDGE_RUNNING=false
  run_bounded "$OBI_COMPOSE_COMMAND_TIMEOUT_SECONDS" \
    "${COMPOSE[@]}" stop --timeout "$OBI_COMPOSE_STOP_GRACE_SECONDS" obi || \
    return $?
  OBI_RUNNING=false
  publish_restart_control_release \
    "$control_dir" \
    "$RESTART_RELEASE_OBI_STOPPED" || return $?
  wait_for_restart_control_signal \
    "$control_dir" \
    "$RESTART_SIGNAL_STOPPED_TRAFFIC_COMPLETE" \
    "traffic while OBI was stopped" \
    "$scenario_pid" || return $?
  restart_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  run_bounded 120 \
    "${COMPOSE[@]}" up --detach \
      --timeout "$OBI_COMPOSE_STOP_GRACE_SECONDS" obi || return $?
  OBI_RUNNING=true
  wait_for_log \
    obi \
    "Java remote parent bridge ready" \
    "OBI bridge restarted during traffic" \
    "$restart_since" || return $?
  sleep "$JAVA_PROVIDER_RETRY_SETTLE_SECONDS" || return $?
  BRIDGE_RUNNING=true
  wait_for_apache_instrumentation restart-fault-recovery || return $?
  wait_for_java_duplicate_suppression \
    "$RESULT_DIR/duplicate-suppression-restart-fault-recovery.prom" || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent provider ready" \
    "Java bridge reconfigured before restart traffic resumes" \
    "$restart_since" || return $?
  assert_selected_transport || return $?
  publish_restart_control_release \
    "$control_dir" \
    "$RESTART_RELEASE_OBI_READY" || return $?
  wait_for_restart_control_signal \
    "$control_dir" \
    "$RESTART_SIGNAL_POST_RESTART_TRAFFIC_COMPLETE" \
    "traffic after OBI recovery" \
    "$scenario_pid" || return $?
  if wait "$scenario_pid"; then
    scenario_status=0
  else
    scenario_status=$?
  fi
  scenario_pid=""
  if ((scenario_status != 0)); then
    log_error "restart fault traffic failed, status=$scenario_status"
    return "$scenario_status"
  fi
  capture_phase_evidence "$after_phase" || return $?
  capture_java_diagnostics "$after_phase" || return $?
  obi_metric_pair_reference="$(record_obi_metric_pair \
    "$label" "$before_phase" "$after_phase" process_replaced "$after_phase")" ||
    return $?
  obi_metric_evidence_json="$(
    obi_metric_pair_evidence_json_from_reference "$obi_metric_pair_reference"
  )" || return $?
  write_java_diagnostics_delta \
    "$RESULT_DIR/phases/$before_phase/java-diagnostics.txt" \
    "$RESULT_DIR/phases/$after_phase/java-diagnostics.txt" \
    "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta" || return $?
  assert_restart_fault_diagnostics \
    "$RESULT_DIR/phases/$after_phase/java-diagnostics.delta" \
    32 \
    3 \
    "$RESULT_DIR/restart-fault-diagnostics.txt" || return $?
  jq -c \
    --arg result "$(basename -- "$output")" \
    --arg after_phase "phases/$after_phase" '
      {
        status: "passed",
        scenario: "restart-fault",
        result: $result,
        after_phase: $after_phase,
        restart_control: "restart-control/events.log",
        obi_metric_evidence: .
      }
    ' <<<"$obi_metric_evidence_json" \
    >"$RESULT_DIR/scenario-$label-status.json" || return $?
  crosslink_and_bind_active_obi_metric_boundary_status \
    "scenario-$label-status.json" || return $?

  capture_terminal_java_diagnostics_recovery_boundary || return $?
  SCENARIO_VARIANT="restart-recovery"
  run_scenario restart
  SCENARIO_VARIANT=""
  commit_terminal_java_diagnostics_recovery_boundary || return $?
  trap - EXIT
  clear_terminal_java_diagnostics_recovery_boundary || return $?
)

run_extension_controls() {
  local disabled_since=""

  stop_obi_for_no_state_control "extension-controls" || return $?
  export JAVA_TOOL_OPTIONS_VALUE="-javaagent:/otel/official-javaagent.jar"

  log_info "recreating the backend with the external extension absent"
  export EXTENSION_ENABLED=false
  export OTEL_JAVAAGENT_EXTENSIONS_VALUE=""
  export OTEL_PROPAGATORS_VALUE="tracecontext,baggage"
  run_bounded 120 \
    "${COMPOSE[@]}" up --detach --force-recreate \
      java-backend apache-proxy || return $?
  wait_for_http \
    "$APACHE_HTTPS_HEALTH_ENDPOINT" \
    "extension-absent HTTPS path" || return $?
  assert_runtime_contract extension-absent || return $?
  SCENARIO_VARIANT="extension-absent"
  run_scenario w3c-only

  log_info "recreating the backend with the external extension disabled"
  export EXTENSION_ENABLED=false
  export OTEL_JAVAAGENT_EXTENSIONS_VALUE="/otel/obi-otel-extension.jar"
  export OTEL_PROPAGATORS_VALUE="obi,tracecontext,baggage"
  disabled_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  run_bounded 120 \
    "${COMPOSE[@]}" up --detach --force-recreate \
      java-backend apache-proxy || return $?
  wait_for_http \
    "$APACHE_HTTPS_HEALTH_ENDPOINT" \
    "extension-disabled HTTPS path" || return $?
  assert_runtime_contract extension-disabled || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent propagator disabled by configuration" \
    "disabled external extension" \
    "$disabled_since" || return $?
  SCENARIO_VARIANT="extension-disabled"
  run_scenario w3c-only
  SCENARIO_VARIANT=""
}

recreate_instrumented_stack() {
  local -r propagation="$1"
  local -r label="$2"
  local -r transport="${3:-$TRANSPORT}"
  local -r verify_java_traffic="${4:-true}"
  local -r fresh_trace_receiver="${5:-false}"
  local -r compose_flavor="${6:-base}"
  local recreate_since=""
  local -a services=(java-backend apache-proxy obi)
  local -a compose_command=()

  [[ "$verify_java_traffic" == "true" || "$verify_java_traffic" == "false" ]] || {
    log_error "Java traffic verification mode must be true or false"
    return 1
  }
  [[ "$fresh_trace_receiver" == "true" || "$fresh_trace_receiver" == "false" ]] || {
    log_error "trace receiver recreation mode must be true or false"
    return 1
  }
  case "$compose_flavor" in
    base)
      compose_command=("${COMPOSE[@]}")
      ;;
    primary-fault)
      compose_command=("${PRIMARY_FAULT_COMPOSE[@]}")
      ;;
    primary-live-fd)
      compose_command=("${PRIMARY_LIVE_FD_COMPOSE[@]}")
      ;;
    unix-generation-fault)
      compose_command=("${UNIX_GENERATION_FAULT_COMPOSE[@]}")
      ;;
    *)
      log_error "unsupported instrumented-stack Compose flavor: $compose_flavor"
      return 1
      ;;
  esac
  if [[ "$fresh_trace_receiver" == "true" ]]; then
    services=(trace-receiver "${services[@]}")
  fi

  CONTEXT_PROPAGATION="$propagation"
  export CONTEXT_PROPAGATION
  BRIDGE_TRANSPORT="$transport"
  export BRIDGE_TRANSPORT
  export EXTENSION_ENABLED=true
  export JAVA_TOOL_OPTIONS_VALUE="-javaagent:/otel/official-javaagent.jar"
  export OTEL_JAVAAGENT_EXTENSIONS_VALUE="/otel/obi-otel-extension.jar"
  export OTEL_PROPAGATORS_VALUE="obi,tracecontext,baggage"
  recreate_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  if [[ "$verify_java_traffic" == "false" ]]; then
    DELAYED_OTLP_PROVIDER_READY_SINCE="$recreate_since"
  fi
  log_info "recreating the instrumented stack for $label propagation=$propagation flavor=$compose_flavor"
  invalidate_selected_transport || return $?
  BRIDGE_RUNNING=false
  if [[ "$compose_flavor" == "primary-fault" || \
    "$compose_flavor" == "primary-live-fd" || \
    "$compose_flavor" == "unix-generation-fault" ]]; then
    run_bounded 30 "${compose_command[@]}" config --quiet || return $?
    run_bounded 30 "${compose_command[@]}" config \
      >"$RESULT_DIR/compose-${compose_flavor}-resolved.yaml" || return $?
  fi
  run_bounded 180 \
    "${compose_command[@]}" up --detach \
      --timeout "$OBI_COMPOSE_STOP_GRACE_SECONDS" --force-recreate \
      "${services[@]}" || return $?
  OBI_RUNNING=true
  if [[ "$fresh_trace_receiver" == "true" ]]; then
    wait_for_http "http://127.0.0.1:14318/healthz" \
      "$label trace receiver" || return $?
  fi
  wait_for_log \
    obi \
    "Java remote parent bridge ready" \
    "$label OBI remote-parent bridge" \
    "$recreate_since" || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent propagator enabled" \
    "$label external OTel extension" \
    "$recreate_since" || return $?
  wait_for_log \
    java-backend \
    "OBI Java instrumentation ready" \
    "$label injected Java instrumentation" \
    "$recreate_since" || return $?
  wait_for_log \
    java-backend \
    "Jetty HTTPS backend ready on 127.0.0.1:18443" \
    "$label Jetty HTTPS backend" \
    "$recreate_since" || return $?
  wait_for_log \
    java-backend \
    "Netty HTTPS backend ready on 127.0.0.1:18444" \
    "$label Netty HTTPS backend" \
    "$recreate_since" || return $?
  wait_for_log \
    java-backend \
    "TLS boundary split HTTPS backend ready on 127.0.0.1:18445" \
    "$label TLS boundary split HTTPS backend" \
    "$recreate_since" || return $?
  wait_for_log \
    java-backend \
    "TLS boundary coalesced HTTPS backend ready on 127.0.0.1:18446" \
    "$label TLS boundary coalesced HTTPS backend" \
    "$recreate_since" || return $?
  BRIDGE_RUNNING=true
  wait_for_apache_instrumentation recreate-instrumented || return $?
  if [[ "$verify_java_traffic" == "false" ]]; then
    wait_for_log \
      apache-proxy \
      "resuming normal operations" \
      "$label Apache HTTP proxy" \
      "$recreate_since" || return $?
    return 0
  fi
  wait_for_http "$APACHE_HTTPS_HEALTH_ENDPOINT" "$label HTTPS path" || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent provider ready" \
    "$label injected Java helper" \
    "$recreate_since" || return $?
  assert_selected_transport "$transport" || return $?
  wait_for_java_duplicate_suppression \
    "$RESULT_DIR/duplicate-suppression-${label// /-}.prom" || return $?
}

run_delayed_otlp_suppression_sequence() {
  local scenario_status=0
  local earliest_export_millisecond=""
  local -r provider_ready_since="$DELAYED_OTLP_PROVIDER_READY_SINCE"
  local -r before_phase="delayed-otlp-prime-before"
  local -r after_phase="delayed-otlp-suppression-after"

  [[ -n "$provider_ready_since" ]] || {
    log_error "delayed OTLP provider-readiness cursor is unavailable"
    return 1
  }

  initialize_delayed_otlp_run_identity || return $?
  plan_obi_metric_pair_capture delayed-otlp-prime-suppression || return $?
  capture_phase_evidence "$before_phase" || return $?
  earliest_export_millisecond="$(delayed_otlp_earliest_export_millisecond)" || return $?
  assert_delayed_otlp_receiver_empty \
    "$RESULT_DIR/delayed-otlp-receiver-before-request.json" || return $?
  assert_java_duplicate_suppression_absent \
    "$RESULT_DIR/duplicate-suppression-delayed-otlp-before-request.prom" || return $?
  # Registration can race bridge attachment. Let the provider's bounded retry interval expire,
  # then use the one intentional prime request to activate recovery without adding another span.
  sleep "$JAVA_PROVIDER_RETRY_SETTLE_SECONDS" || return $?
  run_bounded 10 curl --fail --silent --show-error \
    --header "x-obi-demo-id: $DELAYED_OTLP_PRIME_MARKER" \
    "$APACHE_HTTPS_HEALTH_ENDPOINT" >/dev/null || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent provider ready" \
    "delayed-otlp-suppression injected Java helper" \
    "$provider_ready_since" || return $?
  assert_delayed_otlp_pre_export_window \
    "$RESULT_DIR/delayed-otlp-window.txt" \
    "$earliest_export_millisecond" || return $?
  sleep "$DELAYED_OTLP_PRE_EXPORT_WAIT_SECONDS" || return $?
  assert_delayed_otlp_receiver_has_no_java_export \
    "$RESULT_DIR/delayed-otlp-receiver-before-export.json" || return $?
  assert_java_duplicate_suppression_absent \
    "$RESULT_DIR/duplicate-suppression-delayed-otlp-before-export.prom" || return $?
  wait_for_java_duplicate_suppression_without_prime \
    "$RESULT_DIR/duplicate-suppression-delayed-otlp-ready.prom" \
    "$DELAYED_OTLP_SUPPRESSION_TIMEOUT_SECONDS" || return $?
  wait_for_delayed_otlp_receiver_export \
    "$RESULT_DIR/delayed-otlp-receiver-ready.json" \
    "$DELAYED_OTLP_SUPPRESSION_TIMEOUT_SECONDS" \
    "$earliest_export_millisecond" \
    "$RESULT_DIR/delayed-otlp-receiver-early.json" \
    "$RESULT_DIR/delayed-otlp-receiver-unexpected.json" \
    "$DELAYED_OTLP_POST_EXPORT_SETTLE_SECONDS" || return $?
  capture_phase_evidence "$after_phase" || return $?
  record_obi_metric_pair \
    delayed-otlp-prime-suppression "$before_phase" "$after_phase" \
    same_process "$after_phase" >/dev/null || return $?
  assert_selected_transport || return $?
  assert_runtime_contract delayed-otlp-suppression true || return $?
  SCENARIO_VARIANT="delayed-otlp-suppression"
  if run_scenario basic; then
    SCENARIO_VARIANT=""
  else
    scenario_status=$?
    SCENARIO_VARIANT=""
    return "$scenario_status"
  fi
}

run_delayed_otlp_suppression_control() {
  local schedule_delay_previous=""
  local schedule_delay_was_set=false
  local java_retry_disabled_previous=""
  local java_retry_disabled_was_set=false
  local control_status=0
  local recovery_boundary_status=0
  local recovery_status=0
  local terminal_diagnostics_status=0

  if [[ "$SCENARIO" == "all" ]]; then
    if [[ -v OTEL_BSP_SCHEDULE_DELAY_VALUE ]]; then
      schedule_delay_was_set=true
      schedule_delay_previous="$OTEL_BSP_SCHEDULE_DELAY_VALUE"
    fi
    if [[ -v OTEL_JAVA_EXPORTER_OTLP_RETRY_DISABLED_VALUE ]]; then
      java_retry_disabled_was_set=true
      java_retry_disabled_previous="$OTEL_JAVA_EXPORTER_OTLP_RETRY_DISABLED_VALUE"
    fi
    export OTEL_BSP_SCHEDULE_DELAY_VALUE="$DELAYED_OTLP_SCHEDULE_DELAY_MILLISECONDS"
    export OTEL_JAVA_EXPORTER_OTLP_RETRY_DISABLED_VALUE="$DELAYED_OTLP_JAVA_RETRY_DISABLED"
    if recreate_instrumented_stack \
      tcp "delayed-otlp-suppression startup" "$TRANSPORT" false true; then
      :
    else
      control_status=$?
    fi
  fi

  if ((control_status == 0)); then
    if run_delayed_otlp_suppression_sequence; then
      :
    else
      control_status=$?
    fi
  fi
  if ((control_status != 0)); then
    if seal_terminal_java_diagnostics; then
      :
    else
      terminal_diagnostics_status=$?
    fi
  fi

  if [[ "$SCENARIO" == "all" ]]; then
    if [[ "$schedule_delay_was_set" == "true" ]]; then
      export OTEL_BSP_SCHEDULE_DELAY_VALUE="$schedule_delay_previous"
    else
      unset OTEL_BSP_SCHEDULE_DELAY_VALUE
    fi
    if [[ "$java_retry_disabled_was_set" == "true" ]]; then
      export OTEL_JAVA_EXPORTER_OTLP_RETRY_DISABLED_VALUE="$java_retry_disabled_previous"
    else
      unset OTEL_JAVA_EXPORTER_OTLP_RETRY_DISABLED_VALUE
    fi
    if ((control_status != 0)); then
      log_warn "restoring the standard instrumented stack after delayed OTLP control failure"
      recreate_instrumented_stack \
        tcp "post-delayed-otlp suppression recovery" || true
      return "$control_status"
    fi
    if capture_terminal_java_diagnostics_recovery_boundary; then
      :
    else
      recovery_boundary_status=$?
      if seal_terminal_java_diagnostics; then
        :
      else
        terminal_diagnostics_status=$?
      fi
    fi
    if recreate_instrumented_stack \
      tcp "post-delayed-otlp suppression restoration"; then
      recovery_status=0
    else
      recovery_status=$?
    fi
    if ((recovery_boundary_status != 0)); then
      return "$recovery_boundary_status"
    fi
    if ((recovery_status != 0)); then
      if seal_terminal_java_diagnostics; then
        :
      else
        terminal_diagnostics_status=$?
      fi
      return "$recovery_status"
    fi
    commit_terminal_java_diagnostics_recovery_boundary || return $?
    clear_terminal_java_diagnostics_recovery_boundary || return $?
  fi
  if ((control_status == 0 && terminal_diagnostics_status != 0)); then
    return "$terminal_diagnostics_status"
  fi
  return "$control_status"
}

capture_service_runtime_identity() {
  local -r service="$1"
  local -r output="$2"
  local container_id=""
  local inspected_id=""
  local host_pid=""
  local started_at=""
  local extra=""
  local inspection=""

  container_id="$(
    run_bounded 10 "${COMPOSE[@]}" ps --quiet "$service"
  )" || return $?
  [[ -n "$container_id" ]] || {
    log_error "$service container identity is unavailable"
    return 1
  }
  inspection="$(run_bounded 10 docker inspect \
    --format '{{.Id}} {{.State.Pid}} {{.State.StartedAt}}' \
    "$container_id")" || return $?
  read -r inspected_id host_pid started_at extra <<<"$inspection" || return $?
  [[ "$inspected_id" == "$container_id" && "$host_pid" =~ ^[1-9][0-9]*$ &&
    -n "$started_at" && "$started_at" != "0001-01-01T00:00:00Z" &&
    -z "$extra" ]] || {
    log_error "$service runtime identity is invalid"
    return 1
  }
  {
    printf 'container_id=%s\n' "$container_id"
    printf 'host_pid=%s\n' "$host_pid"
    printf 'started_at=%s\n' "$started_at"
  } >"$output" || return $?
}

runtime_identity_field() {
  local -r identity="$1"
  local -r name="$2"
  local value=""
  local -i matches=0
  local line=""

  while IFS= read -r line; do
    if [[ "$line" == "$name="* ]]; then
      value="${line#*=}"
      ((matches += 1))
    fi
  done <"$identity"
  [[ "$matches" == "1" && -n "$value" ]] || return 1
  printf '%s\n' "$value"
}

assert_runtime_identity_replaced() {
  local -r before="$1"
  local -r after="$2"
  local before_container=""
  local before_started=""
  local after_container=""
  local after_started=""

  before_container="$(runtime_identity_field "$before" container_id)" || return 1
  before_started="$(runtime_identity_field "$before" started_at)" || return 1
  after_container="$(runtime_identity_field "$after" container_id)" || return 1
  after_started="$(runtime_identity_field "$after" started_at)" || return 1
  [[ "$before_container" != "$after_container" && "$before_started" != "$after_started" ]] || {
    log_error "Java recovery did not replace the failed JVM generation"
    return 1
  }
}

capture_service_logs_since() {
  local -r service="$1"
  local -r since="$2"
  local -r output="$3"

  run_bounded 30 \
    "${COMPOSE[@]}" logs --no-color --since "$since" "$service" >"$output"
}

assert_log_message_count() {
  local -r input="$1"
  local -r message="$2"
  local -r expected="$3"
  local count=""

  count="$(awk -v message="$message" \
    'index($0, message) != 0 { count++ } END { print count + 0 }' "$input")"
  [[ "$count" == "$expected" ]] || {
    log_error "expected $expected log lines containing '$message', got $count"
    return 1
  }
}

assert_log_message_for_pid_count() {
  local -r input="$1"
  local -r message="$2"
  local -r host_pid="$3"
  local -r expected="$4"
  local count=""

  bounded_decimal "$host_pid" "$MAX_SHELL_INTEGER" false >/dev/null || return 1
  count="$(awk -v message="$message" -v pid="$host_pid" \
    'index($0, message) != 0 &&
      $0 ~ ("(^|[[:space:]])pid=" pid "([^0-9]|$)") { count++ }
    END { print count + 0 }' \
    "$input")"
  [[ "$count" == "$expected" ]] || {
    log_error "expected $expected log lines containing '$message' for pid=$host_pid, got $count"
    return 1
  }
}

next_scenario_seed() {
  local -r current="$1"

  bounded_decimal "$current" "$MAX_SHELL_INTEGER" true >/dev/null || return 1
  if [[ "$current" == "$MAX_SHELL_INTEGER" ]]; then
    printf '0\n'
  else
    printf '%d\n' "$((current + 1))"
  fi
}

next_java_attach_error_total() {
  local -r baseline="$1"
  local current=0

  if [[ "$baseline" != "absent" ]]; then
    current="$(bounded_decimal "$baseline" "$MAX_SHELL_INTEGER" true)" || return 1
  fi
  ((current < MAX_SHELL_INTEGER)) || return 1
  printf '%d\n' "$((current + 1))"
}

recover_helper_attach_failure_stack() {
  local -r propagation="$1"
  local -r label="$2"
  local -r transport="$3"
  local recovery_since=""

  CONTEXT_PROPAGATION="$propagation"
  export CONTEXT_PROPAGATION
  BRIDGE_TRANSPORT="$transport"
  export BRIDGE_TRANSPORT
  export EXTENSION_ENABLED=true
  export JAVA_TOOL_OPTIONS_VALUE="-javaagent:/otel/official-javaagent.jar"
  export OTEL_JAVAAGENT_EXTENSIONS_VALUE="/otel/obi-otel-extension.jar"
  export OTEL_PROPAGATORS_VALUE="obi,tracecontext,baggage"
  recovery_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  log_info "replacing the failed JVM for $label propagation=$propagation"
  invalidate_selected_transport || return $?
  run_bounded 180 \
    "${COMPOSE[@]}" up --detach --force-recreate \
      java-backend apache-proxy || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent provider ready" \
    "$label injected Java helper" \
    "$recovery_since" || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent propagator enabled" \
    "$label external OTel extension" \
    "$recovery_since" || return $?
  wait_for_log \
    java-backend \
    "OBI Java instrumentation ready" \
    "$label injected Java instrumentation" \
    "$recovery_since" || return $?
  wait_for_log \
    java-backend \
    "Jetty HTTPS backend ready on 127.0.0.1:18443" \
    "$label Jetty HTTPS backend" \
    "$recovery_since" || return $?
  wait_for_log \
    java-backend \
    "Netty HTTPS backend ready on 127.0.0.1:18444" \
    "$label Netty HTTPS backend" \
    "$recovery_since" || return $?
  wait_for_log \
    java-backend \
    "TLS boundary split HTTPS backend ready on 127.0.0.1:18445" \
    "$label TLS boundary split HTTPS backend" \
    "$recovery_since" || return $?
  wait_for_log \
    java-backend \
    "TLS boundary coalesced HTTPS backend ready on 127.0.0.1:18446" \
    "$label TLS boundary coalesced HTTPS backend" \
    "$recovery_since" || return $?
  BRIDGE_RUNNING=true
  assert_selected_transport "$transport" || return $?
  wait_for_apache_instrumentation "$label" || return $?
  wait_for_http "$APACHE_HTTPS_HEALTH_ENDPOINT" "$label HTTPS path" || return $?
}

run_helper_attach_failure_control() (
  local -r original_transport="$TRANSPORT"
  local -r original_propagation="$CONTEXT_PROPAGATION"
  local -r original_seed="$SCENARIO_SEED"
  local alternate_seed=""
  local attach_baseline=""
  local expected_attach_total=""
  local failed_java_pid=""
  local fault_since=""
  local restore_required=false
  local unexpected_log_status=0
  local -r obi_log="$RESULT_DIR/helper-attach-failure-obi.log"
  local -r java_log="$RESULT_DIR/helper-attach-failure-java.log"
  local -r baseline_metrics="$RESULT_DIR/helper-attach-failure-metrics-before.prom"
  local -r fault_metrics="$RESULT_DIR/helper-attach-failure-metrics-after.prom"
  local -r quiet_metrics="$RESULT_DIR/helper-attach-failure-metrics-quiet.prom"
  local -r recovery_metrics="$RESULT_DIR/helper-attach-failure-metrics-recovery.prom"
  local -r before_phase="helper-attach-failure-before"
  local -r after_phase="helper-attach-failure-after"
  local -r obi_identity_before="$RESULT_DIR/helper-attach-failure-obi-before.txt"
  local -r obi_identity_fault="$RESULT_DIR/helper-attach-failure-obi-fault.txt"
  local -r obi_identity_recovery="$RESULT_DIR/helper-attach-failure-obi-recovery.txt"
  local -r java_identity_fault="$RESULT_DIR/helper-attach-failure-java-fault.txt"
  local -r java_identity_after="$RESULT_DIR/helper-attach-failure-java-after-traffic.txt"
  local -r java_identity_recovery="$RESULT_DIR/helper-attach-failure-java-recovery.txt"

  # shellcheck disable=SC2329 # Invoked by the EXIT trap below.
  restore_helper_attach_failure_stack() {
    local -r status="$?"
    local restore_status=0
    local terminal_diagnostics_status=0

    trap - EXIT
    set +e
    seal_terminal_java_diagnostics
    terminal_diagnostics_status=$?
    if [[ "$restore_required" == "true" ]]; then
      log_warn \
        "restoring the normal instrumented stack after helper attach failure control" || true
      (
        set -Eeuo pipefail
        recreate_instrumented_stack \
          "$original_propagation" \
          "helper attach failure cleanup" \
          "$original_transport"
      )
      restore_status=$?
      if ((restore_status != 0)); then
        log_error \
          "could not restore the instrumented stack after helper attach failure control" || true
      fi
    fi
    if ((status == 0 && restore_status != 0)); then
      exit "$restore_status"
    fi
    if ((status == 0 && terminal_diagnostics_status != 0)); then
      exit "$terminal_diagnostics_status"
    fi
    exit "$status"
  }

  trap restore_helper_attach_failure_stack EXIT
  [[ "$BRIDGE_RUNNING" == "true" ]] || {
    log_error "helper attach failure control requires a healthy running bridge"
    return 1
  }
  alternate_seed="$(next_scenario_seed "$original_seed")" || return $?

  restore_required=true
  SCENARIO_VARIANT="helper-attach-bridge-disabled"
  SCENARIO_SEED="$alternate_seed"
  run_disabled_control || return $?
  capture_control_response "helper-attach-bridge-disabled" || return $?
  SCENARIO_VARIANT=""

  recreate_instrumented_stack \
    "$original_propagation" \
    "helper attach failure preparation" \
    "$original_transport" || return $?
  plan_obi_metric_pair_capture helper-attach-rejection || return $?
  capture_phase_evidence "$before_phase" || return $?
  capture_service_runtime_identity obi "$obi_identity_before" || return $?
  fetch_obi_metrics "$baseline_metrics" || return $?
  attach_baseline="$(java_attach_error_total "$baseline_metrics")" || {
    log_error "helper attach failure baseline metric is malformed"
    return 1
  }
  expected_attach_total="$(next_java_attach_error_total "$attach_baseline")" || {
    log_error "helper attach failure baseline metric cannot be incremented"
    return 1
  }

  export BRIDGE_TRANSPORT="$original_transport"
  export EXTENSION_ENABLED=true
  export JAVA_TOOL_OPTIONS_VALUE="$HELPER_ATTACH_FAILURE_JAVA_TOOL_OPTIONS"
  export OTEL_JAVAAGENT_EXTENSIONS_VALUE="/otel/obi-otel-extension.jar"
  export OTEL_PROPAGATORS_VALUE="obi,tracecontext,baggage"
  invalidate_selected_transport || return $?
  run_bounded 30 "${COMPOSE[@]}" config \
    >"$RESULT_DIR/compose-helper-attach-failure.yaml" || return $?
  fault_since="$(date -u +'%Y-%m-%dT%H:%M:%S.%NZ')" || return $?
  log_info "replacing the JVM with dynamic agent loading disabled"
  run_bounded 180 \
    "${COMPOSE[@]}" up --detach --force-recreate \
      java-backend apache-proxy || return $?
  wait_for_log \
    java-backend \
    "OBI remote-parent propagator enabled" \
    "helper attach failure external OTel extension" \
    "$fault_since" || return $?
  wait_for_http \
    "$APACHE_HTTPS_HEALTH_ENDPOINT" \
    "helper attach failure HTTPS path" || return $?
  capture_service_runtime_identity \
    java-backend "$java_identity_fault" || return $?
  failed_java_pid="$(runtime_identity_field \
    "$java_identity_fault" host_pid)" || return $?

  wait_for_log \
    obi \
    "couldn't attach OpenTelemetry eBPF Java Agent" \
    "rejected dynamic Java helper attach" \
    "$fault_since" || return $?
  wait_for_log \
    obi \
    "unable to attach java agent to process, Java TLS telemetry will not work" \
    "attributed Java helper attach failure" \
    "$fault_since" || return $?
  wait_for_java_attach_error_total \
    "$expected_attach_total" \
    "$attach_baseline" \
    "$fault_metrics" \
    "helper attach failure" || return $?
  write_metrics_delta \
    "$baseline_metrics" \
    "$fault_metrics" \
    "$RESULT_DIR/helper-attach-failure-metrics.delta" || return $?
  capture_phase_evidence "$after_phase" || return $?
  record_obi_metric_pair \
    helper-attach-rejection "$before_phase" "$after_phase" same_process "" \
    >/dev/null || return $?

  capture_service_runtime_identity obi "$obi_identity_fault" || return $?
  cmp -- "$obi_identity_before" "$obi_identity_fault" || return $?
  BRIDGE_RUNNING=true
  wait_for_apache_instrumentation helper-attach-failure || return $?
  capture_service_logs_since obi "$fault_since" "$obi_log" || return $?
  capture_service_logs_since \
    java-backend "$fault_since" "$java_log" || return $?
  assert_runtime_contract helper-attach-fault || return $?

  capture_control_response "helper-attach-failure" || return $?
  cmp \
    "$RESULT_DIR/helper-attach-bridge-disabled-response.normalized.json" \
    "$RESULT_DIR/helper-attach-failure-response.normalized.json" || return $?
  cmp \
    "$RESULT_DIR/helper-attach-bridge-disabled-response.status" \
    "$RESULT_DIR/helper-attach-failure-response.status" || return $?

  SCENARIO_VARIANT="helper-unavailable"
  run_scenario \
    helper-attach-failure false full none helper-unavailable
  run_scenario w3c false full none helper-unavailable
  SCENARIO_VARIANT=""
  capture_service_runtime_identity \
    java-backend "$java_identity_after" || return $?
  cmp -- "$java_identity_fault" "$java_identity_after" || return $?
  wait_for_java_attach_error_total \
    "$expected_attach_total" \
    "$expected_attach_total" \
    "$quiet_metrics" \
    "helper attach failure quiet window" \
    3 || return $?

  capture_service_logs_since obi "$fault_since" "$obi_log" || return $?
  capture_service_logs_since \
    java-backend "$fault_since" "$java_log" || return $?
  assert_log_message_count \
    "$obi_log" \
    "injecting OpenTelemetry eBPF instrumentation for Java process" \
    1 || return $?
  assert_log_message_count \
    "$obi_log" \
    "couldn't attach OpenTelemetry eBPF Java Agent" \
    1 || return $?
  assert_log_message_count \
    "$obi_log" \
    "unable to attach java agent to process, Java TLS telemetry will not work" \
    1 || return $?
  assert_log_message_for_pid_count \
    "$obi_log" \
    "injecting OpenTelemetry eBPF instrumentation for Java process" \
    "$failed_java_pid" \
    1 || return $?
  assert_log_message_for_pid_count \
    "$obi_log" \
    "couldn't attach OpenTelemetry eBPF Java Agent" \
    "$failed_java_pid" \
    1 || return $?
  assert_log_message_for_pid_count \
    "$obi_log" \
    "unable to attach java agent to process, Java TLS telemetry will not work" \
    "$failed_java_pid" \
    1 || return $?
  assert_log_message_count \
    "$java_log" \
    "OBI remote-parent propagator enabled" \
    1 || return $?
  assert_log_message_count \
    "$java_log" "OBI remote-parent compatibility " 1 || return $?
  grep -F "OBI remote-parent compatibility " "$java_log" |
    grep -Fq "supported=true" || return $?
  if grep -Eq \
    'OBI remote-parent (provider ready|transport configuration)|OBI Java instrumentation ready' \
    "$java_log"; then
    log_error "helper attach failure JVM unexpectedly loaded the injected helper"
    return 1
  else
    unexpected_log_status=$?
  fi
  if ((unexpected_log_status != 1)); then
    log_error "could not verify that the failed JVM omitted helper readiness logs"
    return "$unexpected_log_status"
  fi
  grep -Fq "reason=bridge_lookup_missing" "$java_log" || return $?

  curl --fail --silent --show-error --max-time 5 \
    --cacert "$CERT_DIR/ca.crt" \
    "https://127.0.0.1:18443/obi-diagnostics" \
    >"$RESULT_DIR/helper-attach-failure-java-diagnostics.txt" || return $?
  cmp -s \
    "$RESULT_DIR/helper-attach-failure-java-diagnostics.txt" \
    <(printf 'unavailable\n') || {
    log_error "helper attach failure diagnostics did not report unavailable"
    return 1
  }
  capture_terminal_java_diagnostics_recovery_boundary || return $?
  recover_helper_attach_failure_stack \
    "$original_propagation" \
    "helper-attach-recovery" \
    "$original_transport" || return $?
  restore_required=false
  capture_service_runtime_identity \
    java-backend "$java_identity_recovery" || return $?
  assert_runtime_identity_replaced \
    "$java_identity_fault" "$java_identity_recovery" || return $?
  capture_service_runtime_identity obi "$obi_identity_recovery" || return $?
  cmp -- "$obi_identity_before" "$obi_identity_recovery" || return $?
  wait_for_java_attach_error_total \
    "$expected_attach_total" \
    "$expected_attach_total" \
    "$recovery_metrics" \
    "helper attach recovery" \
    3 || return $?
  capture_java_diagnostics helper-attach-recovery || return $?
  assert_sanitized_java_diagnostics \
    "$RESULT_DIR/phases/helper-attach-recovery/java-diagnostics.txt" || return $?
  capture_control_response "helper-attach-recovery" || return $?
  cmp \
    "$RESULT_DIR/helper-attach-bridge-disabled-response.normalized.json" \
    "$RESULT_DIR/helper-attach-recovery-response.normalized.json" || return $?
  cmp \
    "$RESULT_DIR/helper-attach-bridge-disabled-response.status" \
    "$RESULT_DIR/helper-attach-recovery-response.status" || return $?

  SCENARIO_VARIANT="helper-attach-recovery"
  run_scenario basic
  SCENARIO_VARIANT=""
  SCENARIO_SEED="$original_seed"

  commit_terminal_java_diagnostics_recovery_boundary || return $?
  trap - EXIT
  clear_terminal_java_diagnostics_recovery_boundary || return $?
  return 0
)

reset_matching_bridge_environment() {
  FAULT_MODE="alternating"
  MATCHING_VALID_TAKES=1
  export FAULT_MODE MATCHING_VALID_TAKES
}

matching_bridge_sequence_is_exact() {
  local -r input="$1"
  local -r expected_valid="$2"

  awk -v expected_valid="$expected_valid" '
    /operation=take status=/ {
      count++
      status = count == 1 || count == expected_valid + 2 ? "missing" : "valid"
      pattern = "operation=take status=" status " take_count=" count "([^0-9]|$)"
      if ($0 !~ pattern) {
        invalid = 1
      }
    }
    END {
      exit invalid || count != expected_valid + 2 ? 1 : 0
    }
  ' "$input"
}

start_matching_bridge() {
  local -r label="$1"
  local -r expected_valid="$2"
  local start_status=0

  [[ "$BRIDGE_RUNNING" == "false" ]] || {
    log_error "refusing to start the controlled matching bridge while OBI is running"
    return 1
  }
  bounded_decimal "$expected_valid" 1000 false >/dev/null || {
    log_error "matching bridge valid-take count is invalid: $expected_valid"
    return 1
  }
  FAULT_MODE="matching"
  MATCHING_VALID_TAKES="$expected_valid"
  export FAULT_MODE MATCHING_VALID_TAKES
  log_info "starting controlled matching bridge for $label valid_takes=$expected_valid"
  MATCHING_BRIDGE_RUNNING=true
  if run_bounded 60 \
    "${COMPOSE[@]}" up --detach --no-deps --force-recreate bridge-fault; then
    :
  else
    start_status=$?
    if run_bounded 30 "${COMPOSE[@]}" stop --timeout 5 bridge-fault; then
      MATCHING_BRIDGE_RUNNING=false
    fi
    reset_matching_bridge_environment
    return "$start_status"
  fi
  if wait_for_log \
    bridge-fault \
    "mode=matching matching_valid_takes=$expected_valid" \
    "$label controlled matching bridge"; then
    :
  else
    start_status=$?
    if run_bounded 30 "${COMPOSE[@]}" stop --timeout 5 bridge-fault; then
      MATCHING_BRIDGE_RUNNING=false
    fi
    reset_matching_bridge_environment
    return "$start_status"
  fi
}

stop_matching_bridge() {
  local -r label="$1"
  local -r expected_valid="$2"
  local -r fixture_log="$RESULT_DIR/$label-matching-bridge.log"
  local status=0

  if ! run_bounded 15 \
    "${COMPOSE[@]}" logs --no-color bridge-fault >"$fixture_log"; then
    log_error "could not capture the controlled matching bridge log for $label"
    status=1
  elif ! matching_bridge_sequence_is_exact "$fixture_log" "$expected_valid"; then
    log_error "matching bridge sequence for $label was not missing, $expected_valid valid, missing"
    status=1
  fi
  if ! run_bounded 30 "${COMPOSE[@]}" stop --timeout 5 bridge-fault; then
    log_error "could not stop the controlled matching bridge for $label"
    status=1
  else
    MATCHING_BRIDGE_RUNNING=false
  fi
  reset_matching_bridge_environment
  return "$status"
}

run_w3c_match_control() {
  local -r original_transport="$TRANSPORT"
  local recovery_boundary_status=0
  local recovery_status=0
  local terminal_diagnostics_status=0

  if [[ "$SELECTED_TRANSPORT" != "unix" ]]; then
    recreate_instrumented_stack \
      "tcp" "matching W3C and OBI preparation" unix || return $?
  fi
  stop_obi_for_no_state_control "w3c-match" || return $?
  run_scenario w3c-match true full matching || return $?
  if [[ "$SCENARIO" == "all" || "$KEEP_RUNNING" == "true" ]]; then
    if capture_terminal_java_diagnostics_recovery_boundary; then
      :
    else
      recovery_boundary_status=$?
      if seal_terminal_java_diagnostics; then
        :
      else
        terminal_diagnostics_status=$?
      fi
    fi
    if recreate_instrumented_stack \
      "tcp" "post-match bridge restoration" "$original_transport"; then
      recovery_status=0
    else
      recovery_status=$?
    fi
    if ((recovery_boundary_status != 0)); then
      return "$recovery_boundary_status"
    fi
    if ((recovery_status != 0)); then
      if seal_terminal_java_diagnostics; then
        :
      else
        terminal_diagnostics_status=$?
      fi
      return "$recovery_status"
    fi
    commit_terminal_java_diagnostics_recovery_boundary || return $?
    clear_terminal_java_diagnostics_recovery_boundary || return $?
  fi
  return "$terminal_diagnostics_status"
}

capture_w3c_fault_bridge_log() {
  local -r fault_log="$1"
  local capture_status=0

  if run_bounded 15 \
    "${COMPOSE[@]}" logs --no-color bridge-fault >"$fault_log"; then
    return 0
  else
    capture_status=$?
  fi
  log_error "could not capture the W3C fault bridge log"
  return "$capture_status"
}

stop_w3c_fault_bridge() {
  local stop_status=0

  [[ "$FAULT_BRIDGE_RUNNING" == "true" ]] || return 0
  if run_bounded 30 "${COMPOSE[@]}" stop --timeout 5 bridge-fault; then
    FAULT_BRIDGE_RUNNING=false
    return 0
  else
    stop_status=$?
  fi
  return "$stop_status"
}

abort_w3c_fault_mode() {
  local -r primary_status="$1"
  local -r fault_log="$2"
  local -r capture_log="$3"
  local cleanup_status=0
  local terminal_diagnostics_status=0

  if seal_terminal_java_diagnostics; then
    :
  else
    terminal_diagnostics_status=$?
  fi

  if [[ "$capture_log" == "true" ]] && \
    ! capture_w3c_fault_bridge_log "$fault_log"; then
    cleanup_status=1
  fi
  if ! stop_w3c_fault_bridge; then
    log_error "could not stop the W3C fault bridge after a mode failure"
    cleanup_status=1
  fi
  if ((primary_status != 0)); then
    return "$primary_status"
  fi
  if ((cleanup_status == 0 && terminal_diagnostics_status != 0)); then
    return "$terminal_diagnostics_status"
  fi
  return "$cleanup_status"
}

run_w3c_fault_control() {
  local -r diagnostics_baseline="$RESULT_DIR/phases/w3c-fault-pre-stop/java-diagnostics.txt"
  local -r stopped_diagnostics="$RESULT_DIR/phases/w3c-fault-obi-stopped/java-diagnostics.txt"
  local fault_log=""
  local expected_requests=""
  local stale=""
  local malformed=""
  local observed=""
  local control_status=0
  local recovery_boundary_status=0
  local recovery_status=0
  local terminal_diagnostics_status=0
  local -a fault_modes=(
    alternating timeout disconnect overload truncated bad-magic bad-size
    version-mismatch zero-trace-id zero-span-id
  )

  [[ "$TRANSPORT" == "unix" && "$SELECTED_TRANSPORT" == "unix" ]] || {
    log_error "the W3C malformed/stale control requires the forced Unix transport"
    return 1
  }
  W3C_FAULT_DIAGNOSTICS_PREVIOUS=""
  ensure_java_diagnostics_phase_directory w3c-fault-pre-stop || return $?
  if ! stop_obi_for_no_state_control "w3c-fault" "$diagnostics_baseline"; then
    return 1
  fi
  # The required post-stop diagnostics probe is itself instrumented. Start the
  # fault-mode chain after that probe so every delta remains attributable only
  # to its controlled responder request.
  W3C_FAULT_DIAGNOSTICS_PREVIOUS="$stopped_diagnostics"
  for FAULT_MODE in "${fault_modes[@]}"; do
    FAULT_REQUEST_COUNT=1
    if [[ "$FAULT_MODE" == "alternating" ]]; then
      FAULT_REQUEST_COUNT=2
    fi
    export FAULT_MODE
    fault_log="$RESULT_DIR/w3c-fault-$FAULT_MODE-bridge.log"
    log_info "starting bounded Unix fault responder mode=$FAULT_MODE"
    FAULT_BRIDGE_RUNNING=true
    if run_bounded 60 \
      "${COMPOSE[@]}" up --detach --no-deps --force-recreate bridge-fault; then
      :
    else
      control_status=$?
      abort_w3c_fault_mode "$control_status" "$fault_log" true || return $?
      return 1
    fi
    if wait_for_log \
      bridge-fault \
      "mode=$FAULT_MODE" \
      "Unix fault responder mode=$FAULT_MODE"; then
      :
    else
      control_status=$?
      abort_w3c_fault_mode "$control_status" "$fault_log" true || return $?
      return 1
    fi
    if run_scenario w3c-fault; then
      :
    else
      control_status=$?
      abort_w3c_fault_mode "$control_status" "$fault_log" true || return $?
      return 1
    fi
    if capture_w3c_fault_bridge_log "$fault_log"; then
      :
    else
      control_status=$?
      abort_w3c_fault_mode "$control_status" "$fault_log" false || return $?
      return 1
    fi
    expected_requests="$(scenario_request_count w3c-fault)"
    expected_requests="$((expected_requests * REPEAT_COUNT))"
    if [[ "$FAULT_MODE" == "alternating" ]]; then
      stale="$(awk '/operation=take status=stale/ { count++ } END { print count + 0 }' "$fault_log")"
      malformed="$(awk '/operation=take status=malformed/ { count++ } END { print count + 0 }' "$fault_log")"
      if [[ "$stale" != "$(((expected_requests + 1) / 2))" || \
        "$malformed" != "$((expected_requests / 2))" ]]; then
        log_error "fault responder expected stale=$(((expected_requests + 1) / 2)) malformed=$((expected_requests / 2)), got stale=$stale malformed=$malformed"
        abort_w3c_fault_mode 1 "$fault_log" false || return $?
        return 1
      fi
    else
      observed="$(awk -v wanted="$FAULT_MODE" \
        '$0 ~ ("operation=take status=" wanted) { count++ } END { print count + 0 }' \
        "$fault_log")"
      if [[ "$observed" != "$expected_requests" ]]; then
        log_error "fault responder mode=$FAULT_MODE expected requests=$expected_requests, got $observed"
        abort_w3c_fault_mode 1 "$fault_log" false || return $?
        return 1
      fi
    fi
    if ! sleep "$JAVA_PROVIDER_RETRY_SETTLE_SECONDS"; then
      abort_w3c_fault_mode 1 "$fault_log" false || return $?
      return 1
    fi
  done
  stop_w3c_fault_bridge || return $?
  FAULT_MODE="alternating"
  FAULT_REQUEST_COUNT=2
  W3C_FAULT_DIAGNOSTICS_PREVIOUS=""
  export FAULT_MODE
  if capture_terminal_java_diagnostics_recovery_boundary; then
    :
  else
    recovery_boundary_status=$?
    if seal_terminal_java_diagnostics; then
      :
    else
      terminal_diagnostics_status=$?
    fi
  fi
  if recreate_instrumented_stack "tcp" "post-fault bridge recovery"; then
    recovery_status=0
  else
    recovery_status=$?
  fi
  if ((recovery_boundary_status != 0)); then
    return "$recovery_boundary_status"
  fi
  if ((recovery_status != 0)); then
    if seal_terminal_java_diagnostics; then
      :
    else
      terminal_diagnostics_status=$?
    fi
    return "$recovery_status"
  fi
  commit_terminal_java_diagnostics_recovery_boundary || return $?
  clear_terminal_java_diagnostics_recovery_boundary || return $?
  return "$terminal_diagnostics_status"
}

