  [[ -n "$expected_device" && -n "$expected_inode" &&
    "$expected_owner" == "$(id -u)" &&
    ( "$expected_mode" == 600 || "$expected_mode" == 644 ) &&
    "$expected_links" == 1 ]] || return 1
  for attempt in 1 2 3; do
    [[ -f "$path" && ! -L "$path" &&
      "$(stat -Lc '%d:%i:%u:%a:%h' -- "$path")" == \
        "$expected_identity" ]] || return 1
    if rm -f -- "$path"; then
      removal_status=0
    else
      removal_status=$?
    fi
    [[ ! -e "$path" && ! -L "$path" ]] && return 0
