  IFS=: read -r device inode owner mode links <<<"$identity"
  [[ "$device:$inode:$owner" == "$expected_inode" &&
    "$owner" == "$(id -u)" && "$mode" =~ $allowed_mode_pattern &&
    "$links" == 1 ]] || return 1
  remove_terminal_owned_private_path "$path" "$identity"
