  if [[ -n "$digest" ]]; then
    [[ "$digest" =~ ^[0-9a-f]{64}$ ]] || return 1
  else
    digest="$(sha256sum "$RESULT_DIR/$reference")" || return 1
    digest="${digest%% *}"
  fi
  updated="$(jq -cS \
    --arg capture_id "$phase" --arg reference "$reference" \
